    /// known before writing.
    /// </summary>
    public static long ResolveWriteLength(Stream source, long? length)
    {
        if (source.CanSeek)
        {
            return source.Length - source.Position;
        }

        if (length is null)
        {
            throw new ArgumentException(
                "A non-seekable stream requires an explicit length.",
                nameof(length)
            );
        }

        return length.Value;
    }
