    /// <inheritdoc />
    public override void RegisterDuplicateError(
        IReadOnlyList<string> propertyNames,
        string? message
    )
    {
        var displayNames = new List<string>(propertyNames.Count);
        var targets = new List<string>(propertyNames.Count);

        foreach (var propertyName in propertyNames)
        {
            switch (propertyName)
            {
                case nameof(DocumentId):
                    displayNames.Add(GetDisplayName(nameof(DocumentId), null));
                    targets.Add(nameof(BindingDocumentId));
                    break;

                case nameof(Title):
                    displayNames.Add(GetDisplayName(nameof(Title), null));
                    targets.Add(nameof(BindingTitle));
                    break;

                case nameof(IsPublished):
                    displayNames.Add(GetDisplayName(nameof(IsPublished), null));
                    targets.Add(nameof(BindingIsPublished));
                    break;

                case nameof(Payload):
                    displayNames.Add(GetDisplayName(nameof(Payload), null));
                    targets.Add(nameof(BindingPayload));
                    break;

                case nameof(Thumb):
                    displayNames.Add(GetDisplayName(nameof(Thumb), null));
                    targets.Add(nameof(BindingThumb));
                    break;

                case nameof(Checksum):
                    displayNames.Add(GetDisplayName(nameof(Checksum), null));
                    targets.Add(nameof(BindingChecksum));
                    break;

                case nameof(RowVer):
                    displayNames.Add(GetDisplayName(nameof(RowVer), null));
                    targets.Add(nameof(BindingRowVer));
                    break;

                default:
                    // A name that does not belong to this edit model (a user-defined check may report one) has no binding property to attach the error to.
                    displayNames.Add(propertyName);
                    break;
            }
        }

        var resolved = message ?? ResolveDuplicateErrorMessage(propertyNames, displayNames);

        // Names that could not be mapped (and an empty list) become a model-level error.
        if (targets.Count == 0)
        {
            SetDuplicateError(string.Empty, resolved);
            return;
        }

        foreach (var target in targets)
        {
            SetDuplicateError(target, resolved);
        }
    }

