    }

    /// <summary>Called just after a new DocumentEntity is created (set initial values via a partial implementation).</summary>
    partial void OnEntityCreated(DocumentEntity entity);

    /// <summary>Creates a new DocumentEditModel from a DocumentEntity.</summary>
    public override DocumentEditModel CreateEditModel(DocumentEntity entity)
    {
        var editModel = new DocumentEditModel();
        ApplyToEditModel(entity, editModel);
        OnEditModelCreated(editModel);
        return editModel;
    }

    /// <summary>Called just after a new DocumentEditModel is created (after loading) (set initial values via a partial implementation; branch on IsAdded to target new models only).</summary>
    partial void OnEditModelCreated(DocumentEditModel editModel);

    /// <summary>Applies the DocumentEditModel's confirmed values to an existing DocumentEntity (destructive update).</summary>
    /// <param name="includeRemoved">Whether to also restore and apply deletion-tracked (Removed) items (true for saving, false for report display and similar).</param>
    public override void ApplyToEntity(
        DocumentEditModel editModel,
        DocumentEntity entity,
        bool includeRemoved = false
    )
    {
        entity.DocumentId =
            editModel.DocumentId ?? throw new InvalidOperationException("DocumentId has no input value.");
        entity.Title =
            editModel.Title ?? throw new InvalidOperationException("Title has no input value.");
        entity.IsPublished =
            editModel.IsPublished ?? throw new InvalidOperationException("IsPublished has no input value.");
        entity.Payload = editModel.Payload;
        entity.Thumb =
            editModel.Thumb ?? throw new InvalidOperationException("Thumb has no input value.");
        entity.Checksum = editModel.Checksum;

        // The database generates this column, so an absent input keeps the entity's current value.
        if (editModel.RowVer is not null)
        {
            entity.RowVer = editModel.RowVer;
        }

        // Transfer the RowState raised on the edit model by confirmed-value changes as-is (no state is created here).
        entity.RowState = editModel.RowState;
        entity.DocumentNotes = new DocumentNoteMapper().CreateEntities(editModel.DocumentNotes, includeRemoved);
        OnEntityApplied(editModel, entity);
    }

    /// <summary>Called after the DocumentEditModel's confirmed values are applied to the DocumentEntity (save additional properties via a partial implementation).</summary>
    partial void OnEntityApplied(DocumentEditModel editModel, DocumentEntity entity);

    /// <summary>Applies the DocumentEntity's values to an existing DocumentEditModel.</summary>
    /// <remarks>
    /// Loading is lossless: the confirmed values are copied straight from the entity instead of being rebuilt by parsing
    /// the on-screen input strings, so nothing that the display format cannot express (sub-second precision of a
    /// DateTime, its Kind, and so on) is dropped. The input strings are then derived from the confirmed values.
    /// </remarks>
    public void ApplyToEditModel(DocumentEntity entity, DocumentEditModel editModel)
    {
        editModel.ExecuteLoad(() =>
        {
            editModel.DocumentId = entity.DocumentId;
            editModel.Title = entity.Title;
            editModel.IsPublished = entity.IsPublished;
            editModel.Payload = entity.Payload;
            editModel.Thumb = entity.Thumb;
            editModel.Checksum = entity.Checksum;
            editModel.RowVer = entity.RowVer;

            // Derive the on-screen input strings from the confirmed values just loaded and clear stale conversion errors.
            editModel.RevertInput();
            editModel.DocumentNotes = new DocumentNoteMapper().CreateEditModels(entity.DocumentNotes);
            OnEditModelLoaded(entity, editModel);
        });

        // The edit model's state is based on the source entity (loaded = Unchanged, new = Added).
        editModel.RowState = entity.RowState;
    }

    /// <summary>Called after the default load into the DocumentEditModel (load additional properties via a partial implementation).</summary>
    partial void OnEditModelLoaded(DocumentEntity entity, DocumentEditModel editModel);
}

