/// <summary>Common repository interface limited to operations that can be provided across a network boundary (the remote surface).</summary>
/// <remarks>
/// <para>
/// Holds only CRUD and save operations for single entities and entity graphs; it excludes members that take arguments
/// that cannot be carried out of process, such as expression trees (<see cref="IRepository{TEntity, TKey}.Query"/>) or
/// raw SQL. Because every member's arguments and return values are pure data (entities, primary keys, counts), code that
/// depends only on this surface stays compile-time safe even if the implementation is later swapped for a remote
/// implementation (over a web service).
/// </para>
/// <para>
/// <see cref="IRepository{TEntity, TKey}"/> inherits this interface and provides all of its methods, so existing consuming
/// code is unchanged. With remote contract generation (GenerateRemoteContracts), an I{Entity}RemoteRepository that has only
/// this surface (plus the named queries) is additionally generated, and I{Entity}Repository inherits it.
/// </para>
/// </remarks>
public partial interface IRemoteRepository<TEntity, TKey>
    where TEntity : EntityBase, new()
{
    /// <summary>Gets a single entity by primary key (null when not found).</summary>
    Task<TEntity?> GetByIdAsync(TKey id, CancellationToken cancellationToken = default);

    /// <summary>Gets all entities.</summary>
    Task<IReadOnlyList<TEntity>> GetAllAsync(CancellationToken cancellationToken = default);

    /// <summary>Inserts an entity.</summary>
    Task InsertAsync(TEntity entity, CancellationToken cancellationToken = default);

    /// <summary>Updates an entity (true when a matching row was updated).</summary>
    /// <param name="entity">The entity to update.</param>
    /// <param name="mode">How a concurrent modification is handled when the table has a rowversion column (no effect otherwise). An undefined value throws <see cref="ArgumentOutOfRangeException"/>.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<bool> UpdateAsync(
        TEntity entity,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    );

    /// <summary>Deletes an entity by primary key (true when a matching row was deleted).</summary>
    Task<bool> DeleteAsync(TKey id, CancellationToken cancellationToken = default);

    /// <summary>Saves inserts, updates, and deletes in a single transaction according to RowState (children cascade by default).</summary>
    /// <param name="entity">The entity to save (the aggregate root).</param>
    /// <param name="cascadeSave">Whether to cascade the save to child objects.</param>
    /// <param name="cascadeDelete">Whether to cascade deletes to child objects.</param>
    /// <param name="insertWhenUpdateMissing">Whether to switch to INSERT when no row exists to update (throws by default).</param>
    /// <param name="mode">How a concurrent modification is handled for entities whose table has a rowversion column (no effect otherwise). An undefined value throws <see cref="ArgumentOutOfRangeException"/>.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <returns>The number of records saved.</returns>
    Task<int> SaveAsync(
        TEntity entity,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    );

    /// <summary>Saves multiple aggregate roots together in a single transaction (an atomic all-succeed-or-all-rollback operation).</summary>
    /// <param name="entities">The list of entities to save (the aggregate roots).</param>
    /// <param name="cascadeSave">Whether to cascade the save to child objects.</param>
    /// <param name="cascadeDelete">Whether to cascade deletes to child objects.</param>
    /// <param name="insertWhenUpdateMissing">Whether to switch to INSERT when no row exists to update (throws by default).</param>
    /// <param name="mode">How a concurrent modification is handled for entities whose table has a rowversion column (no effect otherwise). An undefined value throws <see cref="ArgumentOutOfRangeException"/>.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <returns>The number of records saved.</returns>
    Task<int> SaveAsync(
        IEnumerable<TEntity> entities,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    );
}

/// <summary>Common repository interface that provides CRUD operations for entities.</summary>
/// <remarks>
/// The full-featured surface that, in addition to the remote surface (<see cref="IRemoteRepository{TEntity, TKey}"/>), adds
/// members that assume local execution (a direct DB connection): expression-tree queries, raw SQL, and bulk insert.
/// I{Entity}Repository always provides this full-featured surface.
/// </remarks>
public partial interface IRepository<TEntity, TKey> : IRemoteRepository<TEntity, TKey>
    where TEntity : EntityBase, new()
{
    /// <summary>Bulk inserts a collection of entities.</summary>
    /// <param name="entities">The list of entities to insert.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <returns>The number of rows inserted.</returns>
    Task<int> BulkInsertAsync(
        IEnumerable<TEntity> entities,
        CancellationToken cancellationToken = default
    );

    /// <summary>Starts a query where filters, ordering, and Include can be specified via a fluent chain.</summary>
    SqlQuery<TEntity> Query();

    /// <summary>Executes a raw SQL SELECT and maps the result rows to {TEntity}.</summary>
    /// <remarks>
    /// <para>
    /// The SELECT must return all columns of {TEntity} (<c>SELECT *</c> or all columns listed). A partial SELECT (missing
    /// columns) is not allowed; if any column is missing, an exception is thrown that names the missing column.
    /// </para>
    /// <para>
    /// <paramref name="parameters"/> enumerates the public instance properties of an anonymous object (or similar) and binds
    /// property name <c>Foo</c> as SQL parameter <c>@Foo</c> (null means no parameters). Because raw SQL has no column context,
    /// values are bound without an explicit type via <c>AddWithValue</c>.
    /// <b>Always pass values as parameters (concatenating them into the SQL string risks injection).</b>
    /// </para>
    /// </remarks>
    /// <param name="sql">A SELECT statement that returns all columns.</param>
    /// <param name="parameters">An anonymous object bound to @name parameters (null for no parameters).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<IReadOnlyList<TEntity>> QueryBySqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    );

    /// <summary>Executes raw SQL (UPDATE/DELETE/any DML) and returns the number of affected rows.</summary>
    /// <remarks>
    /// <para>
    /// <paramref name="parameters"/> is bound the same way as <see cref="QueryBySqlAsync"/> (property name <c>Foo</c> → <c>@Foo</c>,
    /// <c>AddWithValue</c> without an explicit type, null for no parameters).
    /// <b>Always pass values as parameters (string concatenation risks injection).</b>
    /// </para>
    /// <para>
    /// The connection is opened and closed per call (no transaction argument). To execute multiple statements atomically,
    /// write <c>BEGIN TRAN ... COMMIT</c> inside a single <see cref="ExecuteSqlAsync"/> call.
    /// </para>
    /// </remarks>
    /// <param name="sql">The DML statement to execute.</param>
    /// <param name="parameters">An anonymous object bound to @name parameters (null for no parameters).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    );

    /// <summary>Executes raw SQL and returns a single scalar value (<c>default</c> when there is no match or DBNull).</summary>
    /// <remarks>
    /// <para>
    /// <paramref name="parameters"/> is bound the same way as <see cref="QueryBySqlAsync"/>.
    /// <b>Always pass values as parameters (string concatenation risks injection).</b>
    /// </para>
    /// <para>
    /// When the result is <c>null</c> / <see cref="DBNull"/>, returns <c>default(TResult)</c>. When the type does not match
    /// <typeparamref name="TResult"/>, it performs a best-effort conversion with
    /// <see cref="System.Convert.ChangeType(object, System.Type, System.IFormatProvider)"/>
    /// (<see cref="System.Globalization.CultureInfo.InvariantCulture"/>), throwing a descriptive exception when it cannot convert.
    /// </para>
    /// </remarks>
    /// <param name="sql">A SELECT statement that returns a single value (for example, <c>SELECT COUNT(*) ...</c>).</param>
    /// <param name="parameters">An anonymous object bound to @name parameters (null for no parameters).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<TResult?> ExecuteScalarSqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    );
}

/// <summary>A raw SQL executor not bound to a specific entity (executes arbitrary SQL and maps to entities, projection DTOs, or single values).</summary>
/// <remarks>
/// <para>
/// Unlike the raw SQL methods on <see cref="IRepository{TEntity, TKey}"/>, the caller specifies the type via a type argument,
/// so cross-entity JOIN and aggregate queries can be projected onto any DTO. The repository's raw SQL methods delegate to
/// this executor internally.
/// </para>
/// <para>
/// <c>parameters</c> is bound the same way as the repository's raw SQL methods (property name <c>Foo</c> of an anonymous
/// object is bound as <c>@Foo</c> without an explicit type; null for no parameters).
/// <b>Always pass values as parameters (concatenating them into the SQL string risks injection).</b>
/// </para>
/// </remarks>
public partial interface ISqlExecutor
{
    /// <summary>Executes a raw SQL SELECT and maps the result rows strictly (all columns required) to {TEntity}.</summary>
    /// <remarks>
    /// The SELECT must return all columns of {TEntity} (<c>SELECT *</c> or all columns listed); if any column is missing, a
    /// descriptive exception is thrown. Mapping and the RowState=Unchanged treatment are identical to
    /// <see cref="IRepository{TEntity, TKey}.QueryBySqlAsync"/>.
    /// </remarks>
    /// <param name="sql">A SELECT statement that returns all columns.</param>
    /// <param name="parameters">An anonymous object bound to @name parameters (null for no parameters).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<IReadOnlyList<TEntity>> QueryBySqlAsync<TEntity>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
        where TEntity : EntityBase, new();

    /// <summary>Executes a raw SQL SELECT and leniently projects the result rows onto an arbitrary <typeparamref name="TResult"/>.</summary>
    /// <remarks>
    /// <para>
    /// <b>Single-value mode</b>: when <typeparamref name="TResult"/> (Nullable is judged by its underlying type) is primitive / enum /
    /// string / decimal / DateTime / DateTimeOffset / TimeSpan / Guid / byte[],
    /// the <b>first column</b> of each row is converted and returned (DBNull becomes <c>default</c>). Conversion uses the same
    /// Nullable-aware <see cref="System.Convert.ChangeType(object, System.Type, System.IFormatProvider)"/> as the scalar methods.
    /// </para>
    /// <para>
    /// <b>DTO mode</b>: any other type requires a public parameterless constructor (positional records are not supported). Result
    /// set column names are matched <b>case-insensitively</b> against the writable properties (set/init) of
    /// <typeparamref name="TResult"/>, and only matching columns are assigned. Extra columns are ignored and missing columns keep
    /// their defaults. When no column matches at all, an exception listing the column names and property names is thrown (typo guard).
    /// </para>
    /// <para>
    /// Projection DTOs have no save path, so a partial map carries no data-corruption risk; unlike entities, they are mapped <b>leniently</b>.
    /// </para>
    /// </remarks>
    /// <param name="sql">The SELECT statement to project.</param>
    /// <param name="parameters">An anonymous object bound to @name parameters (null for no parameters).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<IReadOnlyList<TResult>> QueryProjectionBySqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    );

    /// <summary>Executes raw SQL (UPDATE/DELETE/any DML) and returns the number of affected rows.</summary>
    /// <remarks>
    /// The connection is opened and closed per call (no transaction argument). To execute multiple statements atomically,
    /// write <c>BEGIN TRAN ... COMMIT</c> in the SQL within a single call.
    /// </remarks>
    /// <param name="sql">The DML statement to execute.</param>
    /// <param name="parameters">An anonymous object bound to @name parameters (null for no parameters).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    );

    /// <summary>Executes raw SQL and returns a single scalar value (<c>default</c> when there is no match or DBNull).</summary>
    /// <remarks>
    /// When the result is <c>null</c> / <see cref="DBNull"/>, returns <c>default(TResult)</c>. When the type does not match,
    /// it performs a best-effort conversion with
    /// <see cref="System.Convert.ChangeType(object, System.Type, System.IFormatProvider)"/> (<see cref="System.Globalization.CultureInfo.InvariantCulture"/>),
    /// throwing a descriptive exception when it cannot convert.
    /// </remarks>
    /// <param name="sql">A SELECT statement that returns a single value (for example, <c>SELECT COUNT(*) ...</c>).</param>
    /// <param name="parameters">An anonymous object bound to @name parameters (null for no parameters).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<TResult?> ExecuteScalarSqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    );
}

/// <summary>The kind of DB operation performed for a single entity during a graph save (Save).</summary>
public enum SaveOperation
{
    /// <summary>Insert (INSERT).</summary>
    Insert,

    /// <summary>Update (UPDATE).</summary>
    Update,

    /// <summary>Delete (DELETE).</summary>
    Delete,
}

/// <summary>Selects how concurrent modifications are handled when saving an entity whose table has a rowversion column (no effect otherwise).</summary>
public enum ConcurrencyMode
{
    /// <summary>Rejects the save with a SaveConflictException when the row was modified by someone else after it was read (the default).</summary>
    Optimistic,

    /// <summary>Overwrites the row unconditionally, ignoring the version check (an explicit last-write-wins).</summary>
    ForceOverwrite,
}

/// <summary>Validates a ConcurrencyMode argument (an undefined value must fail fast instead of silently disabling the version check).</summary>
internal static class ConcurrencyModes
{
    /// <summary>Returns the mode unchanged, or throws ArgumentOutOfRangeException when it is not a defined member.</summary>
    public static ConcurrencyMode Validated(ConcurrencyMode mode) =>
        mode is ConcurrencyMode.Optimistic or ConcurrencyMode.ForceOverwrite
            ? mode
            : throw new ArgumentOutOfRangeException(
                nameof(mode),
                "The concurrency mode must be Optimistic or ForceOverwrite."
            );
}

/// <summary>
/// A hook that injects logic before and after a graph save (<c>SaveAsync</c>). Zero or more can be registered in DI and are
/// resolved per target entity type.
/// </summary>
/// <remarks>
/// <para>
/// Both methods have default implementations, so implement only the one you need. <see cref="BeforeSaveAsync"/> is called
/// immediately before each entity's operation (Insert/Update/Delete); returning <c>false</c> skips just that single
/// operation (other rows continue). <see cref="AfterSaveAsync"/> is called immediately after the operation, before commit,
/// together with an <see cref="ISaveHookContext"/> that participates in the same transaction (throwing an exception rolls
/// back the entire save).
/// </para>
/// <para>
/// Hooks fire only for <c>SaveAsync</c> (graph save, both overloads); direct calls to <c>InsertAsync</c> / <c>UpdateAsync</c> /
/// <c>DeleteAsync</c> and <c>BulkInsertAsync</c> are not covered (they pass through). Consistency across skips (for example,
/// if you block a new parent, also block its new children) is the hook implementer's responsibility; contradictions fail
/// safe via a DB constraint error followed by a full rollback.
/// </para>
/// </remarks>
/// <typeparam name="TEntity">The entity type the hook targets.</typeparam>
public interface ISaveHook<TEntity>
    where TEntity : EntityBase
{
    /// <summary>Called immediately before the operation (<c>false</c> skips that single operation; the default does not skip).</summary>
    /// <param name="entity">The entity being saved.</param>
    /// <param name="operation">The operation about to be performed (Insert/Update/Delete).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    /// <returns><c>true</c> to proceed with the operation, <c>false</c> to skip it.</returns>
    Task<bool> BeforeSaveAsync(
        TEntity entity,
        SaveOperation operation,
        CancellationToken cancellationToken = default
    ) => Task.FromResult(true);

    /// <summary>Called immediately after the operation, before commit (the default does nothing; <paramref name="context"/> participates in the same transaction).</summary>
    /// <remarks>
    /// Because this runs before the commit, a rowversion (concurrency token) property still holds the value the entity was
    /// read with: the version the database assigned during this save is written back only after the commit succeeds.
    /// </remarks>
    /// <param name="entity">The entity that was saved.</param>
    /// <param name="operation">The operation actually performed (Insert when switched via <c>insertWhenUpdateMissing</c>).</param>
    /// <param name="context">A context for performing DB operations within the same transaction.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task AfterSaveAsync(
        TEntity entity,
        SaveOperation operation,
        ISaveHookContext context,
        CancellationToken cancellationToken = default
    ) => Task.CompletedTask;
}

/// <summary>
/// The context passed to <see cref="ISaveHook{TEntity}.AfterSaveAsync"/> for performing DB operations while participating in
/// the in-progress save transaction.
/// </summary>
/// <remarks>
/// <para>
/// Calling the repository's regular API from inside a hook would use a separate connection and contend for locks, so this
/// contract provides operations that complete within the same transaction. Raw handles (connection, transaction) are not
/// exposed; only typed operations (writing excluded binary columns and raw SQL) are provided (dialect-neutral, misuse-proof).
/// </para>
/// <para>
/// <see cref="WriteBinaryColumnAsync"/> works only for diagrams generated with <c>ExcludeUnboundedBinaryColumns</c> enabled.
/// For diagrams without it, a <see cref="NotSupportedException"/> is thrown (use raw SQL via <see cref="ExecuteSqlAsync"/>,
/// or enable the option).
/// </para>
/// </remarks>
public interface ISaveHookContext
{
    /// <summary>Executes raw SQL (any DML) within the same transaction and returns the number of affected rows.</summary>
    /// <remarks>
    /// Parameter binding is the same as the repository's raw SQL methods (public property name <c>Foo</c> of an anonymous
    /// object is bound as <c>@Foo</c>).
    /// <b>Always pass values as parameters (string concatenation risks injection).</b>
    /// </remarks>
    /// <param name="sql">The DML statement to execute.</param>
    /// <param name="parameters">An anonymous object bound to @name parameters (null for no parameters).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    );

    /// <summary>
    /// Writes an unbounded binary (excluded) column from a stream, addressed by primary key, within the same transaction
    /// (O(chunk) streaming). When <paramref name="source"/> is <c>null</c>, sets the column to NULL. Returns <c>true</c>
    /// when a row was updated, <c>false</c> when no row matched.
    /// </summary>
    /// <param name="propertyName">The C# property name of the target column (use <c>nameof</c>).</param>
    /// <param name="key">The primary key value of the target row.</param>
    /// <param name="source">The stream to write (<c>null</c> for SET NULL).</param>
    /// <param name="length">The length, required when <c>source.CanSeek</c> is false (omitting it throws <see cref="ArgumentException"/>).</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<bool> WriteBinaryColumnAsync(
        string propertyName,
        object key,
        Stream? source,
        long? length = null,
        CancellationToken cancellationToken = default
    );

    /// <summary>File convenience method that writes a file's contents to an unbounded binary (excluded) column (delegates to <see cref="WriteBinaryColumnAsync"/>).</summary>
    /// <param name="propertyName">The C# property name of the target column (use <c>nameof</c>).</param>
    /// <param name="key">The primary key value of the target row.</param>
    /// <param name="path">The path of the file to read.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    async Task<bool> WriteBinaryColumnFromFileAsync(
        string propertyName,
        object key,
        string path,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(path);

        await using var stream = File.OpenRead(path);
        return await WriteBinaryColumnAsync(
            propertyName,
            key,
            stream,
            stream.Length,
            cancellationToken
        ).ConfigureAwait(false);
    }
}

/// <summary>A non-generic surface for invoking the save hooks of a specific entity type (across the mixed types of a graph).</summary>
/// <remarks>Calls Before in registration order, short-circuiting on the first <c>false</c>; calls After sequentially in registration order. Built once per type.</remarks>
public interface ISaveHookInvoker
{
    /// <summary>Calls Before in registration order, short-circuiting on the first <c>false</c> (returns false when any hook returns false).</summary>
    Task<bool> InvokeBeforeAsync(
        EntityBase entity,
        SaveOperation operation,
        CancellationToken cancellationToken
    );

    /// <summary>Calls After sequentially in registration order.</summary>
    Task InvokeAfterAsync(
        EntityBase entity,
        SaveOperation operation,
        ISaveHookContext context,
        CancellationToken cancellationToken
    );
}

/// <summary>A registry that resolves the save hook invoker surface (<see cref="ISaveHookInvoker"/>) for an entity type.</summary>
/// <remarks>Returns <c>null</c> for a type with no hooks at all (a complete no-op). Implementations cache resolution results.</remarks>
public interface ISaveHookRegistry
{
    /// <summary>Returns the hook invoker surface for the given entity type (<c>null</c> when there are no hooks).</summary>
    ISaveHookInvoker? GetInvoker(Type entityType);
}

/// <summary>
/// The default <see cref="ISaveHookRegistry"/> implementation, which resolves <c>IEnumerable&lt;ISaveHook&lt;TEntity&gt;&gt;</c>
/// from an <see cref="IServiceProvider"/> and builds the invoker surface (depends only on the BCL <see cref="IServiceProvider"/>).
/// </summary>
/// <remarks>
/// Caches the type-to-invoker mapping <b>per registry instance (Scoped)</b> — not process-static, because hooks may be
/// Scoped services. The invoker surface is created exactly once via <see cref="Type.MakeGenericType"/> on
/// <see cref="SaveHookInvoker{TEntity}"/> plus <see cref="Activator"/> (subsequent calls involve no reflection).
/// </remarks>
internal sealed class ServiceProviderSaveHookRegistry(IServiceProvider serviceProvider)
    : ISaveHookRegistry
{
    private readonly IServiceProvider _serviceProvider = serviceProvider;
    private readonly ConcurrentDictionary<Type, ISaveHookInvoker?> _invokers = new();

    /// <summary>Resolves and caches the invoker surface for the given type (<c>null</c> when there are no hooks).</summary>
    public ISaveHookInvoker? GetInvoker(Type entityType) =>
        _invokers.GetOrAdd(entityType, BuildInvoker);

    /// <summary>Resolves <c>IEnumerable&lt;ISaveHook&lt;entityType&gt;&gt;</c> and builds the invoker surface when at least one hook exists (null otherwise).</summary>
    private ISaveHookInvoker? BuildInvoker(Type entityType)
    {
        var hookType = typeof(ISaveHook<>).MakeGenericType(entityType);
        var enumerableType = typeof(IEnumerable<>).MakeGenericType(hookType);
        var resolved = (System.Collections.IEnumerable?)_serviceProvider.GetService(enumerableType);

        if (resolved is null)
        {
            return null;
        }

        // Null when nothing is registered (a complete no-op even with a registry present). Materialize to fix the count
        var hooks = resolved.Cast<object>().ToList();

        if (hooks.Count == 0)
        {
            return null;
        }

        var invokerType = typeof(SaveHookInvoker<>).MakeGenericType(entityType);
        return (ISaveHookInvoker)Activator.CreateInstance(invokerType, resolved)!;
    }
}

/// <summary>An <see cref="ISaveHookRegistry"/> built from hooks added explicitly, for use without a DI container.</summary>
/// <remarks>
/// The generated repositories take an <see cref="ISaveHookRegistry"/> as a constructor argument, so a repository created
/// with <c>new</c> can be given its hooks without standing up a service provider:
/// <c>new {Entity}Repository(connectionFactory, new SaveHookRegistry().Add(hook))</c>. Hooks run in the order they
/// were added, exactly as with the DI-backed <see cref="ServiceProviderSaveHookRegistry"/>. Building the registry is not
/// thread-safe (add every hook before handing it to a repository); resolution afterwards is read-only.
/// </remarks>
internal sealed class SaveHookRegistry : ISaveHookRegistry
{
    // The value is the List<ISaveHook<TEntity>> for the key type. Add is generic, so the typed list and its invoker are
    // built without reflection; only the storage is type-erased
    private readonly Dictionary<Type, object> _hooks = new();
    private readonly Dictionary<Type, ISaveHookInvoker> _invokers = new();

    /// <summary>Adds a hook for <typeparamref name="TEntity"/> and returns this registry so that calls can be chained.</summary>
    /// <typeparam name="TEntity">The entity type the hook targets.</typeparam>
    /// <param name="hook">The hook to add (hooks for the same type fire in the order they were added).</param>
    public SaveHookRegistry Add<TEntity>(ISaveHook<TEntity> hook)
        where TEntity : EntityBase
    {
        ArgumentNullException.ThrowIfNull(hook);

        if (!_hooks.TryGetValue(typeof(TEntity), out var registered))
        {
            registered = new List<ISaveHook<TEntity>>();
            _hooks[typeof(TEntity)] = registered;
        }

        var hooks = (List<ISaveHook<TEntity>>)registered;
        hooks.Add(hook);

        // Rebuild the invoker so that a hook added after the registry was already used still takes effect
        _invokers[typeof(TEntity)] = new SaveHookInvoker<TEntity>(hooks);
        return this;
    }

    /// <summary>Returns the invoker surface for the given type (<c>null</c> when no hook was added for it).</summary>
    public ISaveHookInvoker? GetInvoker(Type entityType) =>
        _invokers.TryGetValue(entityType, out var invoker) ? invoker : null;
}

/// <summary>Typed implementation that invokes the hooks for <typeparamref name="TEntity"/> in registration order (the concrete <see cref="ISaveHookInvoker"/>).</summary>
/// <typeparam name="TEntity">The entity type the hooks target.</typeparam>
internal sealed class SaveHookInvoker<TEntity>(IEnumerable<ISaveHook<TEntity>> hooks)
    : ISaveHookInvoker
    where TEntity : EntityBase
{
    private readonly IReadOnlyList<ISaveHook<TEntity>> _hooks =
        hooks as IReadOnlyList<ISaveHook<TEntity>> ?? hooks.ToList();

    /// <summary>Calls Before in registration order, short-circuiting on the first <c>false</c>.</summary>
    public async Task<bool> InvokeBeforeAsync(
        EntityBase entity,
        SaveOperation operation,
        CancellationToken cancellationToken
    )
    {
        var typed = (TEntity)entity;

        foreach (var hook in _hooks)
        {
            if (!await hook.BeforeSaveAsync(typed, operation, cancellationToken).ConfigureAwait(false))
            {
                return false;
            }
        }

        return true;
    }

    /// <summary>Calls After sequentially in registration order.</summary>
    public async Task InvokeAfterAsync(
        EntityBase entity,
        SaveOperation operation,
        ISaveHookContext context,
        CancellationToken cancellationToken
    )
    {
        var typed = (TEntity)entity;

        foreach (var hook in _hooks)
        {
            await hook.AfterSaveAsync(typed, operation, context, cancellationToken).ConfigureAwait(false);
        }
    }
}

/// <summary>A factory that creates SQLite connections.</summary>
public interface ISqlConnectionFactory
{
    /// <summary>Creates a new SQL connection.</summary>
    SqliteConnection CreateConnection();
}

/// <summary>The default implementation that creates SQL connections from a connection string.</summary>
/// <remarks>
/// <para>
/// Foreign key enforcement is turned on by default. SQLite leaves it off unless a connection asks for it, so the
/// foreign keys the generated DDL declares would otherwise be silently unenforced: a child row could reference a
/// parent that does not exist, and deleting a parent would leave its children behind. Because the schema declares
/// those constraints, enforcing them is the correct default.
/// </para>
/// <para>
/// An explicit <c>Foreign Keys</c> keyword in the connection string is honored exactly as written - including
/// <c>Foreign Keys=False</c>, which keeps the provider's own behavior.
/// </para>
/// </remarks>
public sealed class SqlConnectionFactory : ISqlConnectionFactory
{
    /// <summary>The connection string to open, with the foreign-key default already resolved.</summary>
    private readonly string _connectionString;

    /// <summary>Initializes a new instance from a connection string.</summary>
    /// <remarks>The connection string is parsed once here, not on every <see cref="CreateConnection"/> call.</remarks>
    /// <param name="connectionString">The connection string to open connections with.</param>
    public SqlConnectionFactory(string connectionString)
    {
        _connectionString = ApplyForeignKeysDefault(connectionString);
    }

    /// <summary>Creates a new SQL connection.</summary>
    public SqliteConnection CreateConnection() => new(_connectionString);

    /// <summary>Adds <c>Foreign Keys=True</c> when the keyword is absent, and returns the connection string unchanged when it is present.</summary>
    /// <remarks><c>SqliteConnectionStringBuilder.ForeignKeys</c> is a <c>bool?</c> whose <c>null</c> means "not specified", which is what makes "absent" distinguishable from an explicit <c>False</c>.</remarks>
    private static string ApplyForeignKeysDefault(string connectionString)
    {
        var builder = new SqliteConnectionStringBuilder(connectionString);

        if (builder.ForeignKeys is not null)
        {
            return connectionString;
        }

        builder.ForeignKeys = true;
        return builder.ConnectionString;
    }
}

/// <summary>Creates a schema by running a DDL script against a SQLite database.</summary>
/// <remarks>
/// A bootstrap convenience for development, tests, and samples - it turns the DDL QuickER generates into a usable
/// database in one call. It is not schema management: it knows nothing about versions, about what already exists,
/// or about rolling back, so anything that outlives a throwaway database wants a migration tool instead.
/// </remarks>
public static class SqliteSchemaBootstrap
{
    /// <summary>Opens a connection and runs the whole DDL script.</summary>
    /// <remarks>
    /// The script is sent as a single command: the SQLite provider executes every semicolon-separated statement of one
    /// command text. The connection is opened through <see cref="SqlConnectionFactory"/>, so foreign key enforcement
    /// follows the same rule as the repositories (on unless the connection string says otherwise).
    /// </remarks>
    /// <param name="connectionString">The connection string of the database to create the schema in.</param>
    /// <param name="ddl">The DDL script to run.</param>
    /// <param name="cancellationToken">A token that cancels the operation.</param>
    public static async Task ApplyDdlAsync(
        string connectionString,
        string ddl,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(connectionString);
        ArgumentException.ThrowIfNullOrWhiteSpace(ddl);

        await using var connection = new SqlConnectionFactory(connectionString).CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = connection.CreateCommand();
        command.CommandText = ddl;
        await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }
}

/// <summary>
/// Shared helper responsible for raw SQL binding, scalar conversion, and projection mapping (a single implementation shared
/// by QuickER's SQL Server implementation and the EF Core executor).
/// </summary>
/// <remarks>
/// Works only with the provider-agnostic <see cref="DbCommand"/> / <see cref="DbDataReader"/> and does not depend on any
/// specific DB client. Even in EF Core-only output (configurations without QuickER's SQL Server implementation), this class
/// is emitted as a shared contract and the EF Core executor calls it.
/// </remarks>
internal static class RawSqlMapper
{
    /// <summary>Caches the reflected properties of raw SQL parameter objects per type (the single binding implementation).</summary>
    private static readonly ConcurrentDictionary<Type, PropertyInfo[]> _parameterPropertyCache =
        new();

    /// <summary>Resolves the bindable properties (public instance, readable, non-indexer) of an anonymous object or similar (cached per type).</summary>
    internal static PropertyInfo[] GetBindableProperties(Type type) =>
        _parameterPropertyCache.GetOrAdd(
            type,
            static t =>
                t.GetProperties(BindingFlags.Public | BindingFlags.Instance)
                    .Where(property => property.CanRead && property.GetIndexParameters().Length == 0)
                    .ToArray()
        );

    /// <summary>
    /// Provider-agnostic <see cref="DbCommand"/> parameter binding. Binds public property name <c>Foo</c> of an anonymous
    /// object as SQL parameter <c>@Foo</c> without an explicit type (raw SQL has no column context). Does nothing when null.
    /// </summary>
    internal static void BindParameters(DbCommand command, object? parameters)
    {
        if (parameters is null)
        {
            return;
        }

        foreach (var property in GetBindableProperties(parameters.GetType()))
        {
            var value =
                property.GetValue(parameters);

            // Collection values (for IN) are expanded and bound as @name0, @name1, ... (the @name in the SQL is rewritten too)
            if (IsCollectionParameter(value))
            {
                BindCollectionParameter(command, property.Name, (System.Collections.IEnumerable)value!);
                continue;
            }

            var parameter = command.CreateParameter();
            parameter.ParameterName = $"@{property.Name}";
            parameter.Value = value ?? DBNull.Value;
            command.Parameters.Add(parameter);
        }
    }

    /// <summary>Whether the value is a collection subject to IN expansion (string / byte[] are treated as single values).</summary>
    internal static bool IsCollectionParameter(object? value) =>
        value is System.Collections.IEnumerable && value is not string && value is not byte[];

    /// <summary>
    /// Expands and binds a collection-valued parameter for IN. Rewrites <c>@name</c> in the SQL to per-element
    /// <c>@name0, @name1, ...</c> and adds each element as an individual parameter.
    /// </summary>
    /// <remarks>
    /// Reference it inside parentheses in the SQL, as in <c>IN (@name)</c>. An empty collection expands to a single
    /// <c>NULL</c> (<c>IN (NULL)</c>) and matches no rows (following SQL's three-valued logic).
    /// </remarks>
    internal static void BindCollectionParameter(
        DbCommand command,
        string name,
        System.Collections.IEnumerable values
    )
    {
        var names = new List<string>();

        foreach (var item in values)
        {
            var value = item;
            var parameter = command.CreateParameter();
            parameter.ParameterName = $"@{name}{names.Count}";
            parameter.Value = value ?? DBNull.Value;
            command.Parameters.Add(parameter);
            names.Add(parameter.ParameterName);
        }

        // When an identifier character follows @name (as in @name0 or @nameX) it is a different parameter, so do not rewrite it
        command.CommandText = Regex.Replace(
            command.CommandText,
            $"@{Regex.Escape(name)}(?![0-9A-Za-z_])",
            names.Count == 0 ? "NULL" : string.Join(", ", names)
        );
    }

    /// <summary>
    /// Reads the full result set, leniently projecting it onto <typeparamref name="TResult"/> (the single implementation of
    /// single-value mode and DTO mode). Takes a provider-agnostic <see cref="DbDataReader"/>, so the QuickER and EF Core
    /// executors share the mapping implementation.
    /// </summary>
    internal static async Task<IReadOnlyList<TResult>> ReadProjectionRowsAsync<TResult>(
        DbDataReader reader,
        CancellationToken cancellationToken
    )
    {
        var resultType = typeof(TResult);
        var items = new List<TResult>();

        // Single-value mode (primitive/enum/string/decimal/date-time/Guid/byte[]) converts and returns the first column of each row
        if (IsSingleValueType(resultType))
        {
            while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
            {
                var raw = reader.IsDBNull(0) ? null : reader.GetValue(0);
                // Single-value mode allows DBNull → default (may be null for reference types, but projections carry no corruption risk)
                items.Add(ConvertSingleValue<TResult>(raw)!);
            }

            return items;
        }

        // DTO mode: cache the per-type resolver (column name → property setter) and match by column name per result set
        var accessor = _projectionAccessorCache.GetOrAdd(resultType, BuildProjectionAccessor);

        // Match result set column names to setters (matching properties only). If no column matches, throw via the typo guard
        var setters = new Action<object, object?>?[reader.FieldCount];
        var matched = false;
        for (var i = 0; i < reader.FieldCount; i++)
        {
            if (accessor.SettersByColumn.TryGetValue(reader.GetName(i), out var setter))
            {
                setters[i] = setter;
                matched = true;
            }
        }

        if (!matched)
        {
            var columnNames = new string[reader.FieldCount];
            for (var i = 0; i < reader.FieldCount; i++)
            {
                columnNames[i] = reader.GetName(i);
            }

            throw new InvalidOperationException(
                $"No column in the result set matches a writable property of projection target {resultType.Name}. "
                    + $"Result set columns: [{string.Join(", ", columnNames)}]. "
                    + $"Properties of {resultType.Name}: [{string.Join(", ", accessor.SettersByColumn.Keys)}]. "
                    + "Check the SELECT aliases (AS) and property name spellings (matching is case-insensitive)."
            );
        }

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            var result = accessor.Create();
            for (var i = 0; i < setters.Length; i++)
            {
                var setter = setters[i];
                if (setter is null)
                {
                    continue;
                }

                var raw = reader.IsDBNull(i) ? null : reader.GetValue(i);
                setter(result!, raw);
            }

            items.Add((TResult)result!);
        }

        return items;
    }

    /// <summary>Value conversion shared by the scalar and single-value modes (DBNull/null becomes default; best-effort conversion via Nullable-aware ChangeType).</summary>
    internal static TResult? ConvertSingleValue<TResult>(object? raw)
    {
        if (raw is null)
        {
            return default;
        }

        if (raw is TResult typed)
        {
            return typed;
        }

        // When TResult is Nullable<T>, convert to the underlying type (ChangeType cannot handle Nullable directly)
        var targetType = Nullable.GetUnderlyingType(typeof(TResult)) ?? typeof(TResult);

        try
        {
            return (TResult)Convert.ChangeType(raw, targetType, CultureInfo.InvariantCulture);
        }
        catch (Exception ex)
            when (ex is InvalidCastException or FormatException or OverflowException)
        {
            throw new InvalidOperationException(
                $"Could not convert the raw SQL result value (of type {raw.GetType().Name}) to {typeof(TResult).Name}.",
                ex
            );
        }
    }

    /// <summary>Whether the type is handled in single-value mode (primitive/enum/string/decimal/date-time/Guid/byte[]; Nullable is judged by its underlying type).</summary>
    private static bool IsSingleValueType(Type type)
    {
        var actual = Nullable.GetUnderlyingType(type) ?? type;

        return actual.IsPrimitive
            || actual.IsEnum
            || actual == typeof(string)
            || actual == typeof(decimal)
            || actual == typeof(DateTime)
            || actual == typeof(DateTimeOffset)
            || actual == typeof(TimeSpan)
            || actual == typeof(Guid)
            || actual == typeof(byte[]);
    }

    /// <summary>Resolver holding a projection DTO's factory function and its column-name (case-insensitive) to property-setter map.</summary>
    private sealed record ProjectionAccessor(
        Func<object> Create,
        IReadOnlyDictionary<string, Action<object, object?>> SettersByColumn
    );

    /// <summary>Caches the resolver per projection target type (the column-to-property matching itself happens per result set).</summary>
    private static readonly ConcurrentDictionary<Type, ProjectionAccessor> _projectionAccessorCache =
        new();

    /// <summary>Builds the factory function and the property-name-to-setter map from the projection target type (parameterless constructor required; writable properties only).</summary>
    private static ProjectionAccessor BuildProjectionAccessor(Type resultType)
    {
        var constructor = resultType.GetConstructor(Type.EmptyTypes);
        if (constructor is null)
        {
            throw new InvalidOperationException(
                $"Projection target {resultType.Name} cannot be used with QueryProjectionBySqlAsync. "
                    + "Specify a type with a public parameterless constructor (positional records are not supported)."
            );
        }

        // Init-only properties can also be set via PropertyInfo.SetValue, so include any property with a SetMethod, whether set or init
        var setters = new Dictionary<string, Action<object, object?>>(StringComparer.OrdinalIgnoreCase);
        foreach (
            var property in resultType.GetProperties(BindingFlags.Public | BindingFlags.Instance)
        )
        {
            if (
                property.SetMethod is null
                || property.GetIndexParameters().Length != 0
            )
            {
                continue;
            }

            // The raw type returned by the driver differs by dialect (e.g. SQLite's INTEGER is long),
            // so coerce to the property's underlying type (Nullable uses its underlying type) before setting
            var underlyingType =
                Nullable.GetUnderlyingType(property.PropertyType) ?? property.PropertyType;
            setters[property.Name] = (target, raw) =>
                property.SetValue(
                    target,
                    raw is null ? null : CoerceProjectionValue(raw, underlyingType)
                );
        }

        return new ProjectionAccessor(() => constructor.Invoke(null), setters);
    }

    /// <summary>Coerces a value being assigned to a projection DTO property to the underlying type (same semantics as the scalar conversion ConvertSingleValue).</summary>
    private static object CoerceProjectionValue(object raw, Type underlyingType)
    {
        if (underlyingType.IsInstanceOfType(raw))
        {
            return raw;
        }

        try
        {
            return Convert.ChangeType(raw, underlyingType, CultureInfo.InvariantCulture);
        }
        catch (Exception ex)
            when (ex is InvalidCastException or FormatException or OverflowException)
        {
            throw new InvalidOperationException(
                $"Could not convert the raw SQL projection value (of type {raw.GetType().Name}) to {underlyingType.Name}.",
                ex
            );
        }
    }
}

/// <summary>The default implementation of the entity-agnostic raw SQL executor (the single implementation of binding, scalar conversion, and projection mapping).</summary>
/// <remarks>Stateless (holds only the connection factory), so it can be registered as a Singleton in DI. The repository's raw SQL methods delegate to this implementation.</remarks>
public sealed partial class SqlExecutor(ISqlConnectionFactory connectionFactory) : ISqlExecutor
{
    /// <summary>The source of SQL connections.</summary>
    private readonly ISqlConnectionFactory _connectionFactory = connectionFactory;

    /// <summary>Executes a raw SQL SELECT and maps the result rows strictly (all columns required) to {TEntity}.</summary>
    public async Task<IReadOnlyList<TEntity>> QueryBySqlAsync<TEntity>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
        where TEntity : EntityBase, new()
    {
        ArgumentNullException.ThrowIfNull(sql);

        var metadata = EntitySaveMetadata.For(typeof(TEntity));
        var items = new List<TEntity>();

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(sql, connection);
        BindParameters(command, parameters);

        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);
        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            items.Add(metadata.MapEntityFromRawSql<TEntity>(reader));
        }

        return items;
    }

    /// <summary>Executes a raw SQL SELECT and leniently projects the result rows onto an arbitrary <typeparamref name="TResult"/>.</summary>
    public async Task<IReadOnlyList<TResult>> QueryProjectionBySqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(sql);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(sql, connection);
        BindParameters(command, parameters);

        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);
        // Projection mapping (single-value mode and DTO mode) uses the shared helper's single implementation
        return await RawSqlMapper.ReadProjectionRowsAsync<TResult>(reader, cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Executes raw SQL (UPDATE/DELETE/any DML) and returns the number of affected rows.</summary>
    public async Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(sql);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(sql, connection);
        BindParameters(command, parameters);

        return await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Executes raw SQL and returns a single scalar value (<c>default</c> when there is no match or DBNull).</summary>
    public async Task<TResult?> ExecuteScalarSqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(sql);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(sql, connection);
        BindParameters(command, parameters);

        var scalar = await command.ExecuteScalarAsync(cancellationToken).ConfigureAwait(false);
        return RawSqlMapper.ConvertSingleValue<TResult>(scalar is DBNull ? null : scalar);
    }

    /// <summary>
    /// Enumerates the public instance properties of an anonymous object (or similar) and binds property name <c>Foo</c> as
    /// SQL parameter <c>@Foo</c> via <c>AddWithValue</c> (raw SQL has no column context, so no explicit type). Does nothing
    /// when null. Bindable property resolution shares the single implementation in the shared helper
    /// <see cref="RawSqlMapper.GetBindableProperties"/>.
    /// </summary>
    internal static void BindParameters(SqliteCommand command, object? parameters)
    {
        if (parameters is null)
        {
            return;
        }

        foreach (var property in RawSqlMapper.GetBindableProperties(parameters.GetType()))
        {
            var value =
                property.GetValue(parameters);

            // Collection values (for IN) are expanded via the shared helper into @name0, @name1, ... (the @name in the SQL is rewritten too)
            if (RawSqlMapper.IsCollectionParameter(value))
            {
                RawSqlMapper.BindCollectionParameter(
                    command,
                    property.Name,
                    (System.Collections.IEnumerable)value!
                );
                continue;
            }

            command.Parameters.AddWithValue($"@{property.Name}", value ?? DBNull.Value);
        }
    }
}

/// <summary>Repository base class for SQLite that implements CRUD using metadata.</summary>
public abstract partial class SqliteRepository<TEntity, TKey>(
    ISqlConnectionFactory connectionFactory,
    ISaveHookRegistry? saveHooks = null
) : IRepository<TEntity, TKey>
    where TEntity : EntityBase, new()
{
    /// <summary>Metadata built exactly once per entity type (reused via a static field).</summary>
    private static readonly EntitySaveMetadata _metadata = EntitySaveMetadata.For(typeof(TEntity));

    /// <summary>The source of SQL connections.</summary>
    private readonly ISqlConnectionFactory _connectionFactory = connectionFactory;

    /// <summary>The delegate target of the raw SQL methods (consolidates binding and mapping into a single implementation).</summary>
    private readonly ISqlExecutor _sqlExecutor = new SqlExecutor(connectionFactory);

    /// <summary>The save hook registry (unspecified = null = no hooks, a complete no-op).</summary>
    private readonly ISaveHookRegistry? _saveHooks = saveHooks;

    /// <summary>Gets a single entity by primary key (null when not found).</summary>
    public async Task<TEntity?> GetByIdAsync(TKey id, CancellationToken cancellationToken = default)
    {
        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(_metadata.SelectByIdSql, connection);
        _metadata.BindKeyParameter(command, id);

        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        if (!await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            return null;
        }

        return _metadata.MapEntity<TEntity>(reader);
    }

    /// <summary>Gets all entities.</summary>
    public async Task<IReadOnlyList<TEntity>> GetAllAsync(
        CancellationToken cancellationToken = default
    )
    {
        var items = new List<TEntity>();

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(_metadata.SelectAllSql, connection);
        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        // Resolve column-name-to-ordinal once per result set instead of looking it up per row
        var ordinals = _metadata.SelectOrdinals(reader);

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            items.Add(_metadata.MapEntity<TEntity>(reader, ordinals));
        }

        return items;
    }

    /// <summary>Inserts an entity.</summary>
    public async Task InsertAsync(TEntity entity, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(entity);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(_metadata.InsertSql, connection);
        _metadata.BindInsertParameters(command, entity);
        await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Bulk inserts a collection of entities as a batch of INSERTs in a single transaction.</summary>
    /// <remarks>
    /// SQLite has no SqlBulkCopy equivalent, so INSERTs are repeated over a single connection and transaction (the command
    /// is prepared once and reused with swapped parameter values). The performance characteristics differ from the
    /// SQL Server variant that uses SqlBulkCopy, and large row counts may be slow.
    /// </remarks>
    public async Task<int> BulkInsertAsync(
        IEnumerable<TEntity> entities,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entities);

        // If a collection with a known count is empty, return without opening a connection
        if (entities is ICollection<TEntity> { Count: 0 })
        {
            return 0;
        }

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var transaction = (SqliteTransaction)
            await connection.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);

        try
        {
            var rows = 0;
            foreach (var entity in entities)
            {
                if (entity is null)
                {
                    continue;
                }

                await using var command = new SqliteCommand(
                    _metadata.InsertSql,
                    connection,
                    transaction
                );
                _metadata.BindInsertParameters(command, entity);
                rows += await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
            }

            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
            return rows;
        }
        catch
        {
            // Roll back with CancellationToken.None: a canceled token must not interrupt the rollback or mask the original exception.
            await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
            throw;
        }
    }

    /// <summary>Updates an entity (true when a matching row was updated).</summary>
    public async Task<bool> UpdateAsync(
        TEntity entity,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entity);
        mode = ConcurrencyModes.Validated(mode);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(_metadata.UpdateSql, connection);
        _metadata.BindUpdateParameters(command, entity);

        var affected = await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
        return affected > 0;
    }

    /// <summary>Deletes an entity by primary key (true when a matching row was deleted).</summary>
    public async Task<bool> DeleteAsync(TKey id, CancellationToken cancellationToken = default)
    {
        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = new SqliteCommand(_metadata.DeleteSql, connection);
        _metadata.BindKeyParameter(command, id);

        var affected = await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
        return affected > 0;
    }

    /// <summary>Starts a query where filters, ordering, and Include can be specified via a fluent chain.</summary>
    public SqlQuery<TEntity> Query() => new(new SqliteSqlQueryExecutor<TEntity>(_connectionFactory));

    /// <summary>
    /// Reads an unbounded binary (excluded) column, addressed by primary key, into the destination stream (O(chunk)
    /// streaming — the full blob is never loaded into memory). <paramref name="propertyName"/> is the C# property name of
    /// the target column. Returns <c>false</c> when the row is missing or the column is NULL (nothing is written to the
    /// destination), <c>true</c> when data was written (an empty blob is also true).
    /// Optimistic concurrency (rowversion) is out of scope — this is a direct column operation on par with raw SQL.
    /// </summary>
    protected async Task<bool> ReadUnboundedBinaryColumnAsync(
        string propertyName,
        TKey id,
        Stream destination,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(destination);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        // Delegate to the streaming engine in standalone mode (own connection, no transaction)
        return await UnboundedBinaryColumnEngine.ReadAsync(
            _metadata,
            propertyName,
            id!,
            destination,
            connection,
            transaction: null,
            cancellationToken
        ).ConfigureAwait(false);
    }

    /// <summary>
    /// Writes an unbounded binary (excluded) column from a stream, addressed by primary key (O(chunk) streaming).
    /// When <paramref name="source"/> is <c>null</c>, sets the column to NULL. A Stream that is not <c>CanSeek</c> requires
    /// <paramref name="length"/> (omitting it throws <see cref="ArgumentException"/>). Returns <c>true</c> when a row was
    /// updated, <c>false</c> when no row matched.
    /// Optimistic concurrency (rowversion) is out of scope — this is a direct column operation on par with raw SQL.
    /// </summary>
    protected async Task<bool> WriteUnboundedBinaryColumnAsync(
        string propertyName,
        TKey id,
        Stream? source,
        long? length = null,
        CancellationToken cancellationToken = default
    )
    {
        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        // Delegate to the streaming engine in standalone mode (own connection, own transaction)
        return await UnboundedBinaryColumnEngine.WriteAsync(
            _metadata,
            propertyName,
            id!,
            source,
            length,
            connection,
            transaction: null,
            cancellationToken
        ).ConfigureAwait(false);
    }

    /// <summary>Saves inserts, updates, and deletes in a single transaction according to RowState (children cascade by default).</summary>
    public async Task<int> SaveAsync(
        TEntity entity,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entity);
        mode = ConcurrencyModes.Validated(mode);

        // If the entire graph has no changes, return without even opening a connection
        if (!EntityGraphSaver.HasChanges(entity, cascadeSave))
        {
            return 0;
        }

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        // Save the entire graph, cascades included, over a single connection and transaction (avoids MSDTC promotion)
        await using var transaction = (SqliteTransaction)
            await connection.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);

        // If hooks are registered, build a session that supplies a context participating in the in-progress (connection, transaction)
        var hooks =
            _saveHooks is null
                ? null
                : new SaveHookSession(
                    _saveHooks,
                    e => new SqlSaveHookContext(connection, transaction, e.GetType())
                );

        try
        {
            // HasChanges was already checked before this call, so skip the redundant internal graph traversal
            var rows = await EntityGraphSaver.SaveAsync(
                entity,
                connection,
                transaction,
                cascadeSave,
                cascadeDelete,
                insertWhenUpdateMissing,
                cancellationToken,
                hooks,
                changesAlreadyVerified: true
            ).ConfigureAwait(false);
            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);

            // After a successful commit, settle the state (Added/Updated → Unchanged) to prevent double-processing on a re-save.
            // Skipped rows (where a hook's Before returned false) are left as they are
            EntityGraphSaver.AcceptChanges(entity, cascadeSave, hooks?.Skipped);
            return rows;
        }
        catch
        {
            // Roll back with CancellationToken.None: a canceled token must not interrupt the rollback or mask the original exception.
            await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
            throw;
        }
    }

    /// <summary>Saves multiple aggregate roots together in a single transaction (an atomic all-succeed-or-all-rollback operation).</summary>
    public async Task<int> SaveAsync(
        IEnumerable<TEntity> entities,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entities);
        mode = ConcurrencyModes.Validated(mode);

        // Target only graphs with changes (filter before opening the connection and transaction)
        var targets = entities
            .Where(entity => entity is not null && EntityGraphSaver.HasChanges(entity, cascadeSave))
            .ToList();
        if (targets.Count == 0)
        {
            return 0;
        }

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        // Save the graphs of all entities over a single connection and transaction (a mid-way failure rolls back everything)
        await using var transaction = (SqliteTransaction)
            await connection.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);

        // If hooks are registered, build a session that supplies a context participating in the in-progress (connection, transaction)
        var hooks =
            _saveHooks is null
                ? null
                : new SaveHookSession(
                    _saveHooks,
                    e => new SqlSaveHookContext(connection, transaction, e.GetType())
                );

        try
        {
            var rows = 0;
            foreach (var entity in targets)
            {
                // targets is already filtered by HasChanges, so skip the redundant internal graph traversal
                rows += await EntityGraphSaver.SaveAsync(
                    entity,
                    connection,
                    transaction,
                    cascadeSave,
                    cascadeDelete,
                    insertWhenUpdateMissing,
                    cancellationToken,
                    hooks,
                    changesAlreadyVerified: true
                ).ConfigureAwait(false);
            }

            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);

            // After a successful commit, settle the state of every graph (Added/Updated → Unchanged) to prevent double-processing on a re-save.
            // Skipped rows (where a hook's Before returned false) are left as they are
            foreach (var entity in targets)
            {
                EntityGraphSaver.AcceptChanges(entity, cascadeSave, hooks?.Skipped);
            }

            return rows;
        }
        catch
        {
            // Roll back with CancellationToken.None: a canceled token must not interrupt the rollback or mask the original exception.
            await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
            throw;
        }
    }

    /// <summary>Executes a raw SQL SELECT and maps the result rows to {TEntity}.</summary>
    /// <remarks>
    /// The SELECT must return all columns of {TEntity} (<c>SELECT *</c> or all columns listed). A partial SELECT (missing
    /// columns) is not allowed. Parameters bind the public property names of an anonymous object as <c>@name</c> without an
    /// explicit type (<b>always pass values as parameters; string concatenation risks injection</b>).
    /// The implementation delegates to <see cref="ISqlExecutor"/> (a single implementation of binding and mapping).
    /// </remarks>
    public Task<IReadOnlyList<TEntity>> QueryBySqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => _sqlExecutor.QueryBySqlAsync<TEntity>(sql, parameters, cancellationToken);

    /// <summary>Executes raw SQL (UPDATE/DELETE/any DML) and returns the number of affected rows.</summary>
    /// <remarks>
    /// The connection is opened and closed per call (no transaction argument). To execute multiple statements atomically,
    /// write <c>BEGIN TRAN ... COMMIT</c> in the SQL within a single call.
    /// Parameter binding is the same as <see cref="QueryBySqlAsync"/>
    /// (<b>always pass values as parameters; string concatenation risks injection</b>).
    /// The implementation delegates to <see cref="ISqlExecutor"/>.
    /// </remarks>
    public Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => _sqlExecutor.ExecuteSqlAsync(sql, parameters, cancellationToken);

    /// <summary>Executes raw SQL and returns a single scalar value (<c>default</c> when there is no match or DBNull).</summary>
    /// <remarks>
    /// When the result is <c>null</c> / <see cref="DBNull"/>, returns <c>default(TResult)</c>. When the type does not match,
    /// it performs a best-effort conversion with <see cref="Convert.ChangeType(object, Type, IFormatProvider)"/>
    /// (InvariantCulture), throwing a descriptive exception when it cannot convert. Parameter binding is the same as
    /// <see cref="QueryBySqlAsync"/> (<b>always pass values as parameters; string concatenation risks injection</b>).
    /// The implementation delegates to <see cref="ISqlExecutor"/>.
    /// </remarks>
    public Task<TResult?> ExecuteScalarSqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => _sqlExecutor.ExecuteScalarSqlAsync<TResult>(sql, parameters, cancellationToken);

    /// <summary>Executes a raw SQL SELECT and leniently projects the result rows onto an arbitrary <typeparamref name="TResult"/> (for raw SQL projections of named queries).</summary>
    /// <remarks>
    /// Parameter binding is the same as <see cref="QueryBySqlAsync"/>
    /// (<b>always pass values as parameters; string concatenation risks injection</b>).
    /// The implementation delegates to <see cref="ISqlExecutor"/>.
    /// </remarks>
    protected Task<IReadOnlyList<TResult>> QueryProjectionBySqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => _sqlExecutor.QueryProjectionBySqlAsync<TResult>(sql, parameters, cancellationToken);
}

/// <summary>The SQLite context passed to a save hook's After, participating in the in-progress (connection, transaction).</summary>
/// <remarks>Created bound to an entity type (<see cref="WriteBinaryColumnAsync"/> resolves that type's excluded columns). Raw SQL reuses <c>SqlExecutor.BindParameters</c>.</remarks>
internal sealed class SqlSaveHookContext(
    SqliteConnection connection,
    SqliteTransaction transaction,
    Type entityType
) : ISaveHookContext
{
    private readonly SqliteConnection _connection = connection;
    private readonly SqliteTransaction _transaction = transaction;
    private readonly EntitySaveMetadata _metadata = EntitySaveMetadata.For(entityType);

    /// <summary>Executes raw SQL (any DML) within the same transaction and returns the number of affected rows (binding shares the single implementation with SqlExecutor).</summary>
    public async Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(sql);

        await using var command = new SqliteCommand(sql, _connection, _transaction);
        SqlExecutor.BindParameters(command, parameters);
        return await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Stream-writes an unbounded binary (excluded) column within the same transaction (unsupported for diagrams without exclusions).</summary>
    public Task<bool> WriteBinaryColumnAsync(
        string propertyName,
        object key,
        Stream? source,
        long? length = null,
        CancellationToken cancellationToken = default
    ) =>
        UnboundedBinaryColumnEngine.WriteAsync(
            _metadata,
            propertyName,
            key,
            source,
            length,
            _connection,
            _transaction,
            cancellationToken
        );
}

/// <summary>
/// Engine that performs streaming reads and writes of unbounded binary (excluded) columns against an in-progress connection
/// (plus, optionally, a transaction).
/// </summary>
/// <remarks>
/// <para>
/// Shared by the repository's streaming accessors (standalone mode — no <c>transaction</c>) and the save hook's
/// <see cref="ISaveHookContext.WriteBinaryColumnAsync"/> (enlisted mode — participating in the in-progress transaction).
/// </para>
/// <para>
/// <b>Beware the enlisted/standalone split for SQLite</b>: a write allocates a zeroblob, resolves the rowid, and copies via
/// SqliteBlob within one transaction. Standalone mode opens its own transaction and commits it, whereas enlisted mode uses
/// the in-progress transaction as is and does not commit (the outer Save commits). Mixing these up loses the blob.
/// </para>
/// </remarks>
internal static class UnboundedBinaryColumnEngine
{
    /// <summary>Creates a command on the given connection (plus an optional transaction).</summary>
    private static SqliteCommand CreateCommand(
        string sql,
        SqliteConnection connection,
        SqliteTransaction? transaction
    ) => transaction is null ? new(sql, connection) : new(sql, connection, transaction);

    /// <summary>Reads an unbounded binary column into the destination stream (<c>false</c> when the row is missing or the column is NULL).</summary>
    public static async Task<bool> ReadAsync(
        EntitySaveMetadata metadata,
        string propertyName,
        object key,
        Stream destination,
        SqliteConnection connection,
        SqliteTransaction? transaction,
        CancellationToken cancellationToken
    )
    {
        var column = metadata.ColumnByPropertyName(propertyName);
        var quotedColumn = metadata.QuotedColumnName(column);

        // Resolve the rowid and test for NULL in a single SELECT (SqliteBlob requires a rowid table; safe because QuickER's
        // SQLite DDL never generates WITHOUT ROWID). IS NULL yields 1 (true)
        long rowid;

        await using (
            var probe = CreateCommand(
                $"SELECT rowid, {quotedColumn} IS NULL FROM {metadata.TableName} WHERE \"{metadata.KeyColumnName}\" = @id;",
                connection,
                transaction
            )
        )
        {
            metadata.BindKeyParameter(probe, key);
            await using var reader = await probe.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

            if (!await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
            {
                return false;
            }

            if (reader.GetInt64(1) != 0)
            {
                return false;
            }

            rowid = reader.GetInt64(0);
        }

        await using var blob = new SqliteBlob(
            connection,
            metadata.RawTableName,
            metadata.RawColumnName(column),
            rowid,
            readOnly: true
        );
        await blob.CopyToAsync(
            destination,
            UnboundedBinaryColumns.StreamCopyBufferSize,
            cancellationToken
        ).ConfigureAwait(false);
        return true;
    }

    /// <summary>Writes an unbounded binary column from a stream (<paramref name="source"/>=null means SET NULL; <c>false</c> when no row matched).</summary>
    public static async Task<bool> WriteAsync(
        EntitySaveMetadata metadata,
        string propertyName,
        object key,
        Stream? source,
        long? length,
        SqliteConnection connection,
        SqliteTransaction? transaction,
        CancellationToken cancellationToken
    )
    {
        var column = metadata.ColumnByPropertyName(propertyName);
        var quotedColumn = metadata.QuotedColumnName(column);

        // source=null sets the column to NULL (the way to reset an excluded column to "unset")
        if (source is null)
        {
            await using var nullCommand = CreateCommand(
                $"UPDATE {metadata.TableName} SET {quotedColumn} = NULL WHERE \"{metadata.KeyColumnName}\" = @id;",
                connection,
                transaction
            );
            metadata.BindKeyParameter(nullCommand, key);
            return await nullCommand.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false) > 0;
        }

        // The CanSeek/length contract is validated uniformly across dialects (SQLite's zeroblob requires a fixed length)
        var payloadLength = UnboundedBinaryColumns.ResolveWriteLength(source, length);

        // Enlisted mode (transaction given) uses the outer transaction and does not commit.
        // Standalone mode (no transaction) opens its own transaction and commits on success
        var ownsTransaction = transaction is null;
        var activeTransaction =
            transaction
            ?? (SqliteTransaction)await connection.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);

        try
        {
            await using (
                var allocate = new SqliteCommand(
                    $"UPDATE {metadata.TableName} SET {quotedColumn} = zeroblob(@len) WHERE \"{metadata.KeyColumnName}\" = @id;",
                    connection,
                    activeTransaction
                )
            )
            {
                allocate.Parameters.AddWithValue("@len", payloadLength);
                metadata.BindKeyParameter(allocate, key);

                if (await allocate.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false) == 0)
                {
                    // No matching row (the zeroblob could not be allocated). Roll back only in standalone mode (enlisted mode defers to the outer transaction)
                    if (ownsTransaction)
                    {
                        await activeTransaction.RollbackAsync(cancellationToken).ConfigureAwait(false);
                    }

                    return false;
                }
            }

            long rowid;

            await using (
                var rowidCommand = new SqliteCommand(
                    $"SELECT rowid FROM {metadata.TableName} WHERE \"{metadata.KeyColumnName}\" = @id;",
                    connection,
                    activeTransaction
                )
            )
            {
                metadata.BindKeyParameter(rowidCommand, key);
                rowid = (long)(await rowidCommand.ExecuteScalarAsync(cancellationToken).ConfigureAwait(false))!;
            }

            await using (
                var blob = new SqliteBlob(
                    connection,
                    metadata.RawTableName,
                    metadata.RawColumnName(column),
                    rowid,
                    readOnly: false
                )
            )
            {
                await source.CopyToAsync(
                    blob,
                    UnboundedBinaryColumns.StreamCopyBufferSize,
                    cancellationToken
                ).ConfigureAwait(false);
            }

            // Commit only in standalone mode (in enlisted mode the outer Save commits — do not close it here)
            if (ownsTransaction)
            {
                await activeTransaction.CommitAsync(cancellationToken).ConfigureAwait(false);
            }

            return true;
        }
        catch
        {
            if (ownsTransaction)
            {
                // Roll back with CancellationToken.None: a canceled token must not interrupt the rollback or mask the original exception.
                await activeTransaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
            }

            throw;
        }
        finally
        {
            if (ownsTransaction)
            {
                await activeTransaction.DisposeAsync().ConfigureAwait(false);
            }
        }
    }
}

/// <summary>A query WHERE clause parameter (name, value, target column name). The column name is set only when known and is used for explicit typing.</summary>
/// <param name="Name">The parameter name (for example, @p0).</param>
/// <param name="Value">The value to bind (may include a value object; unwrapping to the raw value happens on the binding side).</param>
/// <param name="ColumnName">The target column name without brackets; null when the column cannot be identified.</param>
internal readonly record struct SqlQueryParameter(string Name, object? Value, string? ColumnName);

/// <summary>A single ordering for SqlQuery (a key selector and a descending flag). Captured as an expression tree and translated to a column name / SQL by the executor.</summary>
/// <param name="KeySelector">The key-selecting lambda expression (may include boxing to object?; the executor strips it).</param>
/// <param name="Descending">Whether the ordering is descending.</param>
internal readonly record struct SqlQueryOrdering(LambdaExpression KeySelector, bool Descending);

/// <summary>
/// A dialect-neutral snapshot (composed only of BCL types) that hands what a SqlQuery has accumulated
/// (Where expressions, orderings, Include tree, paging) to an executor.
/// </summary>
/// <remarks>
/// Predicates and orderings are kept as expression trees; translation to SQL (dialect differences such as
/// identifier quoting, date parts, and LIKE) and execution are the responsibility of each backend's
/// <see cref="ISqlQueryExecutor{TEntity}"/> implementation (the per-dialect ADO executor and the EF Core executor).
/// </remarks>
/// <param name="Predicates">The predicate expressions captured by Where (combined with AND).</param>
/// <param name="Orderings">The orderings captured by OrderBy / OrderByDescending (in the specified order).</param>
/// <param name="Includes">The navigation tree from Include / ThenInclude.</param>
/// <param name="Take">The maximum number of rows to fetch (null when unspecified).</param>
/// <param name="Skip">The number of rows to skip (null when unspecified).</param>
/// <param name="WithUnboundedBinary">Whether to fetch including unbounded binary columns (true means an all-column plain SELECT; cannot be combined with Include).</param>
internal sealed record SqlQueryPlan<TEntity>(
    IReadOnlyList<LambdaExpression> Predicates,
    IReadOnlyList<SqlQueryOrdering> Orderings,
    IReadOnlyList<IncludeNode> Includes,
    int? Take,
    int? Skip,
    bool WithUnboundedBinary
);

/// <summary>
/// The internal abstraction that swaps out execution of SqlQuery's terminal methods. Each backend
/// (the per-dialect ADO executor and the EF Core variant) implements it and is injected into SqlQuery
/// via the constructor. SqlQuery itself holds no dialect SQL and delegates the captured plan
/// (expression trees, Include, paging) to this executor.
/// </summary>
internal interface ISqlQueryExecutor<TEntity>
    where TEntity : class
{
    /// <summary>Fetches the entities matching the conditions (together with the requested Includes) as a list.</summary>
    Task<IReadOnlyList<TEntity>> ToListAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    );

    /// <summary>Fetches the entities matching the conditions with a projection (pruning columns server-side when the backend supports it).</summary>
    Task<IReadOnlyList<TResult>> ToProjectionListAsync<TResult>(
        SqlQueryPlan<TEntity> plan,
        Expression<Func<TEntity, TResult>> selector,
        CancellationToken cancellationToken
    );

    /// <summary>Fetches the first entity matching the conditions (together with the requested Includes); returns null when there is no match.</summary>
    Task<TEntity?> FirstOrDefaultAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    );

    /// <summary>Returns the count of rows matching the conditions (orderings, paging, and Include are not involved).</summary>
    Task<int> CountAsync(SqlQueryPlan<TEntity> plan, CancellationToken cancellationToken);

    /// <summary>Returns whether any record matching the conditions exists (orderings, paging, and Include are not involved).</summary>
    Task<bool> AnyAsync(SqlQueryPlan<TEntity> plan, CancellationToken cancellationToken);

    /// <summary>Bulk-deletes the rows matching the conditions. When cascadeDelete=true, descendants are also deleted along FK chains.</summary>
    Task<int> ExecuteDeleteAsync(
        SqlQueryPlan<TEntity> plan,
        bool cascadeDelete,
        CancellationToken cancellationToken
    );
}

/// <summary>
/// An expression-tree visitor that walks a projection selector (<c>v =&gt; new Dto { ... v.Prop ... }</c>) and determines
/// both "the set of referenced column property names" and "whether the projection can be safely reconstructed from that
/// set alone (i.e. whether server-side column pruning is possible)".
/// </summary>
/// <remarks>
/// If the lambda parameter (the target entity) appears anywhere other than a "direct member reference (<c>v.Prop</c>)",
/// extraction is treated as impossible (referencing <c>v</c> as a whole, a method call that takes the entity as an argument
/// or receiver, a multi-hop navigation reference, and so on). Whether each collected name is actually a column property
/// (rather than a navigation) is reconciled by the caller (each executor) via <c>EntitySaveMetadata.ResolveProjectionColumns</c>
/// (not referenced with cref because EntitySaveMetadata is not co-located in configurations that include only this class).
/// When extraction is impossible, the executor falls back to the legacy path (fetch all columns, then project in memory).
/// </remarks>
internal sealed class ProjectionColumnCollector : ExpressionVisitor
{
    private readonly ParameterExpression _parameter;
    private readonly HashSet<string> _members = new(StringComparer.Ordinal);
    private bool _extractable = true;

    private ProjectionColumnCollector(ParameterExpression parameter) => _parameter = parameter;

    /// <summary>
    /// Collects the direct member names referenced by the selector. Returns true plus the set of referenced names when
    /// extraction succeeded from column references alone, and false when extraction is impossible (whole reference, method call, etc.).
    /// </summary>
    public static bool TryCollect<TEntity, TResult>(
        Expression<Func<TEntity, TResult>> selector,
        out IReadOnlyCollection<string> referencedProperties
    )
    {
        // Only handle lambdas with a single parameter (one target entity)
        if (selector.Parameters.Count != 1)
        {
            referencedProperties = Array.Empty<string>();
            return false;
        }

        var collector = new ProjectionColumnCollector(selector.Parameters[0]);
        collector.Visit(selector.Body);
        referencedProperties = collector._members;
        return collector._extractable;
    }

    /// <summary>Visits a member reference. When the receiver is directly the lambda parameter (<c>v.Prop</c>), collects the name and does not descend inside.</summary>
    protected override Expression VisitMember(MemberExpression node)
    {
        if (node.Expression == _parameter && node.Member is PropertyInfo property)
        {
            // The v.Prop shape. Collect only the name as a column-reference candidate and avoid visiting the inner parameter (which would count as a whole reference).
            _members.Add(property.Name);
            return node;
        }

        return base.VisitMember(node);
    }

    /// <summary>Visits the lambda parameter. Appearing anywhere other than directly above a member reference means a whole reference, so extraction is treated as impossible.</summary>
    protected override Expression VisitParameter(ParameterExpression node)
    {
        if (node == _parameter)
        {
            _extractable = false;
        }

        return node;
    }
}

/// <summary>Validates the string-matching calls (Contains / StartsWith / EndsWith) inside a query predicate and rejects a null pattern argument up front.</summary>
/// <remarks>
/// Dialects and backends disagreed on what a null pattern means (match-all, no-match, or an exception), so the guard unifies
/// them to fail fast. Every backend (the per-dialect ADO executor, EF Core, and the in-memory store) and every generated
/// named query builds its predicates through <see cref="SqlQuery{TEntity}.Where"/>, which makes this the single enforcement point.
/// </remarks>
internal static class QueryStringMatchGuard
{
    /// <summary>Walks a predicate body and throws when a column-side string match is given a null pattern.</summary>
    public static void Validate(Expression predicateBody) =>
        new NullPatternVisitor().Visit(predicateBody);

    /// <summary>The visitor that inspects every method call in the predicate body.</summary>
    private sealed class NullPatternVisitor : ExpressionVisitor
    {
        /// <summary>Checks a string-matching call whose receiver is a column and whose argument is a value, then descends as usual.</summary>
        protected override Expression VisitMethodCall(MethodCallExpression node)
        {
            if (
                IsStringMatch(node)
                // The receiver must be the column side (it references the lambda parameter) and the argument the value side (it does not)
                && ReferencesParameter(node.Object!)
                && !ReferencesParameter(node.Arguments[0])
                && Evaluate(node.Arguments[0]) is null
            )
            {
                throw new ArgumentNullException(
                    "value",
                    "The pattern argument of Contains/StartsWith/EndsWith in a query predicate must not be null."
                );
            }

            return base.VisitMethodCall(node);
        }
    }

    /// <summary>Determines whether the call is a single-argument string match on string.</summary>
    private static bool IsStringMatch(MethodCallExpression call) =>
        call.Object is not null
        && call.Arguments.Count == 1
        && call.Method.Name is "Contains" or "StartsWith" or "EndsWith"
        && call.Method.DeclaringType == typeof(string);

    /// <summary>Walks the expression tree to determine whether it references a lambda parameter (i.e. an entity column).</summary>
    private static bool ReferencesParameter(Expression expression)
    {
        var finder = new ParameterFinder();
        finder.Visit(expression);
        return finder.Found;
    }

    /// <summary>
    /// Evaluates a value-side argument (a constant or a captured variable) to obtain the actual value. Constants and closure
    /// field / property references are read directly, avoiding (expensive) expression-tree compilation; anything else falls back to compiling.
    /// </summary>
    private static object? Evaluate(Expression expression)
    {
        switch (expression)
        {
            case ConstantExpression constant:
                return constant.Value;

            case MemberExpression member:
                var instance = member.Expression is null ? null : Evaluate(member.Expression);

                return member.Member switch
                {
                    FieldInfo field => field.GetValue(instance),
                    PropertyInfo property => property.GetValue(instance),
                    _ => Expression.Lambda(expression).Compile().DynamicInvoke(),
                };

            default:
                return Expression.Lambda(expression).Compile().DynamicInvoke();
        }
    }

    /// <summary>A lightweight visitor that merely raises a flag when it finds a lambda-parameter reference.</summary>
    private sealed class ParameterFinder : ExpressionVisitor
    {
        public bool Found { get; private set; }

        protected override Expression VisitParameter(ParameterExpression node)
        {
            Found = true;
            return node;
        }
    }
}

/// <summary>A query built up by chaining conditions, orderings, and Includes, then executed by a terminal method (ToListAsync, etc.).</summary>
/// <remarks>
/// Predicates, orderings, and Includes are captured as lambda expressions (expression trees); translation to SQL and
/// execution are delegated to the injected <see cref="ISqlQueryExecutor{TEntity}"/> implementation (the per-dialect ADO
/// executor or the EF Core executor). SqlQuery itself holds no dialect SQL at all (dialect differences stay inside the executor).
/// </remarks>
public sealed class SqlQuery<TEntity>
    where TEntity : class
{
    private readonly List<IncludeNode> _includes = new();
    private int? _take;
    private int? _skip;

    /// <summary>The WithUnboundedBinary flag (true fetches all columns including unbounded binary columns; cannot be combined with Include).</summary>
    private bool _withUnboundedBinary;

    /// <summary>The backend executor that runs the terminal methods (per-dialect ADO or EF Core).</summary>
    private readonly ISqlQueryExecutor<TEntity> _executor;

    /// <summary>The captured Where expressions (kept as expression trees without translating; the executor translates them to SQL / LINQ).</summary>
    private readonly List<LambdaExpression> _predicates = new();

    /// <summary>The captured orderings (a key selector and a descending flag).</summary>
    private readonly List<SqlQueryOrdering> _orderSelectors = new();

    /// <summary>Internal constructor that injects the backend executor.</summary>
    internal SqlQuery(ISqlQueryExecutor<TEntity> executor) => _executor = executor;

    /// <summary>Adds a search condition (multiple conditions are combined with AND).</summary>
    public SqlQuery<TEntity> Where(Expression<Func<TEntity, bool>> predicate)
    {
        ArgumentNullException.ThrowIfNull(predicate);
        // Reject a null Contains/StartsWith/EndsWith pattern here so that every backend behaves the same way
        QueryStringMatchGuard.Validate(predicate.Body);
        // Capture as an expression tree and leave translation to SQL / LINQ to the executor
        _predicates.Add(predicate);
        return this;
    }

    /// <summary>Adds an ascending ordering.</summary>
    public SqlQuery<TEntity> OrderBy(Expression<Func<TEntity, object?>> keySelector)
    {
        _orderSelectors.Add(new SqlQueryOrdering(keySelector, Descending: false));
        return this;
    }

    /// <summary>Adds a descending ordering.</summary>
    public SqlQuery<TEntity> OrderByDescending(Expression<Func<TEntity, object?>> keySelector)
    {
        _orderSelectors.Add(new SqlQueryOrdering(keySelector, Descending: true));
        return this;
    }

    /// <summary>Sets the maximum number of rows to fetch (must be greater than zero).</summary>
    public SqlQuery<TEntity> Take(int count)
    {
        // Zero and negative values are rejected up front: dialects disagree on what they mean (SQL Server requires a fetch count greater than zero
        // while SQLite treats a negative LIMIT as "no limit"), and fetching zero rows has no meaningful use (skip the query instead).
        if (count <= 0)
        {
            throw new ArgumentOutOfRangeException(
                nameof(count),
                "The number of rows to fetch must be greater than zero."
            );
        }

        _take = count;
        return this;
    }

    /// <summary>Sets the number of leading rows to skip.</summary>
    public SqlQuery<TEntity> Skip(int count)
    {
        // Negative values are rejected up front: dialects disagree on what they mean (SQL Server raises an error, SQLite clamps a negative OFFSET to zero).
        if (count < 0)
        {
            throw new ArgumentOutOfRangeException(
                nameof(count),
                "The number of rows to skip must not be negative."
            );
        }

        _skip = count;
        return this;
    }

    /// <summary>
    /// Fetches entities including unbounded binary columns (those marked with <c>UnboundedBinaryColumnAttribute</c>). Use it when you want to
    /// fetch, for this call only, the columns that ExcludeUnboundedBinaryColumns has dropped from the default SELECT (a no-op when there are no excluded columns).
    /// </summary>
    /// <remarks>
    /// Cannot be combined with Include (an <see cref="InvalidOperationException"/> is thrown when the terminal method runs). When unbounded binary
    /// columns are needed, fetch them with a separate query that has no Include. On SQL Server this uses a plain SELECT (not the default JSON path),
    /// avoiding the Base64 inflation of large blobs (5-6x peak memory). It takes effect only on ToListAsync / FirstOrDefaultAsync
    /// (it does not affect projections, counts, or existence checks). The fetched entities are equivalent to a normal fetch (RowState=Unchanged), but
    /// because excluded columns remain outside the UPDATE set, calling UpdateAsync on them as-is throws via the existing guard (perform updates with raw SQL).
    /// </remarks>
    public SqlQuery<TEntity> WithUnboundedBinary()
    {
        _withUnboundedBinary = true;
        return this;
    }

    /// <summary>Eagerly fetches a single-reference navigation (ThenInclude allows specifying multiple levels).</summary>
    public IncludableSqlQuery<TEntity, TProperty> Include<TProperty>(
        Expression<Func<TEntity, TProperty>> navigationSelector
    )
    {
        var node = new IncludeNode(IncludeNode.GetProperty(navigationSelector));
        _includes.Add(node);
        return new IncludableSqlQuery<TEntity, TProperty>(this, node);
    }

    /// <summary>Eagerly fetches a collection navigation (ThenInclude allows specifying multiple levels).</summary>
    public IncludableSqlQuery<TEntity, TElement> Include<TElement>(
        Expression<Func<TEntity, ICollection<TElement>>> navigationSelector
    )
    {
        var node = new IncludeNode(IncludeNode.GetProperty(navigationSelector));
        _includes.Add(node);
        return new IncludableSqlQuery<TEntity, TElement>(this, node);
    }

    /// <summary>Fetches the entities matching the conditions (together with the requested Includes) as a list.</summary>
    public async Task<IReadOnlyList<TEntity>> ToListAsync(
        CancellationToken cancellationToken = default
    ) => await _executor.ToListAsync(BuildPlan(), cancellationToken).ConfigureAwait(false);

    /// <summary>Fetches the first entity matching the conditions (together with the requested Includes); returns null when there is no match.</summary>
    public async Task<TEntity?> FirstOrDefaultAsync(CancellationToken cancellationToken = default) =>
        await _executor.FirstOrDefaultAsync(BuildPlan(), cancellationToken).ConfigureAwait(false);

    /// <summary>Returns the count of rows matching the conditions.</summary>
    public async Task<int> CountAsync(CancellationToken cancellationToken = default) =>
        await _executor.CountAsync(BuildPlan(), cancellationToken).ConfigureAwait(false);

    /// <summary>Returns whether any record matching the conditions exists.</summary>
    public async Task<bool> AnyAsync(CancellationToken cancellationToken = default) =>
        await _executor.AnyAsync(BuildPlan(), cancellationToken).ConfigureAwait(false);

    /// <summary>Fetches the entities matching the conditions and returns them as a list transformed by the given projection (for named-query projections).</summary>
    /// <remarks>
    /// Conditions, orderings, and paging are applied on the backend side (dialect SQL / EF Core / in-memory).
    /// The projected columns are pruned server-side when the selector references only column properties (with no Include) and the backend supports it
    /// (narrowing the SELECTed columns, the EF Core projection, and the in-memory copy to the referenced columns). When Include is combined or column
    /// references cannot be safely extracted from the selector, all columns are fetched as before and the projection is applied in memory.
    /// </remarks>
    /// <param name="selector">The expression that transforms an entity into a projection DTO.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public async Task<IReadOnlyList<TResult>> ToProjectionListAsync<TResult>(
        Expression<Func<TEntity, TResult>> selector,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(selector);

        return await _executor.ToProjectionListAsync(BuildPlan(), selector, cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Bulk-deletes the rows matching the conditions. When cascadeDelete=true, descendants are also deleted along FK chains.</summary>
    public async Task<int> ExecuteDeleteAsync(
        bool cascadeDelete = false,
        CancellationToken cancellationToken = default
    ) => await _executor.ExecuteDeleteAsync(BuildPlan(), cascadeDelete, cancellationToken).ConfigureAwait(false);

    /// <summary>Freezes the captured expressions, Include tree, and paging into a snapshot to pass to the executor.</summary>
    private SqlQueryPlan<TEntity> BuildPlan()
    {
        // WithUnboundedBinary cannot be combined with Include (both orderings, Include->With and With->Include, are detected here).
        // The SQL Server Include path goes through the default JSON (Base64), which inflates memory for large blobs, so it is
        // incompatible with the goal of "including unbounded binary columns". The combination itself is always rejected regardless of the terminal method.
        if (_withUnboundedBinary && _includes.Count > 0)
        {
            throw new InvalidOperationException(
                "WithUnboundedBinary cannot be combined with Include. When unbounded binary columns are needed, fetch them with a separate query that has no Include."
            );
        }

        return new(_predicates, _orderSelectors, _includes, _take, _skip, _withUnboundedBinary);
    }
}

/// <summary>The target navigation of an Include and the tree of its descendants (ThenInclude).</summary>
internal sealed class IncludeNode
{
    /// <summary>Creates an Include node for the specified target navigation property.</summary>
    public IncludeNode(PropertyInfo property) => Property = property;

    /// <summary>The navigation property to fetch.</summary>
    public PropertyInfo Property { get; }

    /// <summary>The descendant navigations specified via ThenInclude.</summary>
    public List<IncludeNode> Children { get; } = new();

    /// <summary>Extracts the navigation property from a lambda expression (x => x.Nav).</summary>
    public static PropertyInfo GetProperty(LambdaExpression selector)
    {
        var expression = selector.Body;
        if (
            expression is UnaryExpression
            {
                NodeType: ExpressionType.Convert or ExpressionType.ConvertChecked
            } unary
        )
        {
            expression = unary.Operand;
        }

        if (expression is MemberExpression { Member: PropertyInfo property })
        {
            return property;
        }

        throw new ArgumentException(
            $"Include/ThenInclude requires a navigation property: {selector}"
        );
    }
}

/// <summary>A query that lets you specify ThenInclude (fetching descendants) after an Include.</summary>
public sealed class IncludableSqlQuery<TEntity, TProperty>
    where TEntity : class
{
    private readonly SqlQuery<TEntity> _query;
    private readonly IncludeNode _node;

    internal IncludableSqlQuery(SqlQuery<TEntity> query, IncludeNode node)
    {
        _query = query;
        _node = node;
    }

    /// <summary>Further fetches the descendants of the single-reference navigation Included just before.</summary>
    public IncludableSqlQuery<TEntity, TNext> ThenInclude<TNext>(
        Expression<Func<TProperty, TNext>> navigationSelector
    )
    {
        var child = new IncludeNode(IncludeNode.GetProperty(navigationSelector));
        _node.Children.Add(child);
        return new IncludableSqlQuery<TEntity, TNext>(_query, child);
    }

    /// <summary>Further fetches the descendants of the collection navigation Included just before.</summary>
    public IncludableSqlQuery<TEntity, TNext> ThenInclude<TNext>(
        Expression<Func<TProperty, ICollection<TNext>>> navigationSelector
    )
    {
        var child = new IncludeNode(IncludeNode.GetProperty(navigationSelector));
        _node.Children.Add(child);
        return new IncludableSqlQuery<TEntity, TNext>(_query, child);
    }

    /// <summary>Additionally Includes another root navigation.</summary>
    public IncludableSqlQuery<TEntity, TNext> Include<TNext>(
        Expression<Func<TEntity, TNext>> navigationSelector
    ) => _query.Include(navigationSelector);

    /// <summary>Additionally Includes another root collection.</summary>
    public IncludableSqlQuery<TEntity, TNext> Include<TNext>(
        Expression<Func<TEntity, ICollection<TNext>>> navigationSelector
    ) => _query.Include(navigationSelector);

    /// <summary>Adds a search condition.</summary>
    public SqlQuery<TEntity> Where(Expression<Func<TEntity, bool>> predicate) =>
        _query.Where(predicate);

    /// <summary>Adds an ascending ordering.</summary>
    public SqlQuery<TEntity> OrderBy(Expression<Func<TEntity, object?>> keySelector) =>
        _query.OrderBy(keySelector);

    /// <summary>Adds a descending ordering.</summary>
    public SqlQuery<TEntity> OrderByDescending(Expression<Func<TEntity, object?>> keySelector) =>
        _query.OrderByDescending(keySelector);

    /// <summary>Sets the maximum number of rows to fetch.</summary>
    public SqlQuery<TEntity> Take(int count) => _query.Take(count);

    /// <summary>Sets the number of leading rows to skip.</summary>
    public SqlQuery<TEntity> Skip(int count) => _query.Skip(count);

    /// <summary>Fetches including unbounded binary columns (combining with Include throws when the terminal method runs).</summary>
    public SqlQuery<TEntity> WithUnboundedBinary() => _query.WithUnboundedBinary();

    /// <summary>Fetches the entities matching the conditions as a list.</summary>
    public Task<IReadOnlyList<TEntity>> ToListAsync(
        CancellationToken cancellationToken = default
    ) => _query.ToListAsync(cancellationToken);

    /// <summary>Fetches the first entity matching the conditions (returns null when there is no match).</summary>
    public Task<TEntity?> FirstOrDefaultAsync(CancellationToken cancellationToken = default) =>
        _query.FirstOrDefaultAsync(cancellationToken);

    /// <summary>Returns the count of rows matching the conditions.</summary>
    public Task<int> CountAsync(CancellationToken cancellationToken = default) =>
        _query.CountAsync(cancellationToken);

    /// <summary>Returns whether any record matching the conditions exists.</summary>
    public Task<bool> AnyAsync(CancellationToken cancellationToken = default) =>
        _query.AnyAsync(cancellationToken);
}

/// <summary>
/// The SQLite ADO executor for <see cref="SqlQuery{TEntity}"/>.
/// It translates the plan's predicates and orderings to SQL via <see cref="SqlExpressionTranslator"/>, and
/// materializes the roots with a plain SELECT and resolves Includes by pulling parents and children with an IN-clause multi-query, assembling them in memory.
/// </summary>
/// <remarks>
/// Dialect SQL (identifier quoting, SELECT syntax, paging clauses) is confined to this executor.
/// SqlQuery merely passes the dialect-neutral <see cref="SqlQueryPlan{TEntity}"/>, and dialect differences are absorbed only here.
/// </remarks>
internal sealed class SqliteSqlQueryExecutor<TEntity>(ISqlConnectionFactory connectionFactory)
    : ISqlQueryExecutor<TEntity>
    where TEntity : EntityBase
{
    /// <summary>The source that creates SQL connections.</summary>
    private readonly ISqlConnectionFactory _connectionFactory = connectionFactory;

    private static string TableName => EntitySaveMetadata.For(typeof(TEntity)).TableName;

    /// <summary>Fetches the entities matching the conditions (together with the requested Includes) as a list.</summary>
    public async Task<IReadOnlyList<TEntity>> ToListAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    )
    {
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);

        if (plan.WithUnboundedBinary)
        {
            // Unbounded binary columns requested: materialize with an all-column plain SELECT regardless of dialect (no-Include is already guarded at the terminal)
            return await MaterializeWithUnboundedBinaryAsync(
                plan,
                whereClause,
                parameters,
                plan.Take,
                plan.Skip,
                cancellationToken
            ).ConfigureAwait(false);
        }
        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        // Materialize the roots with a plain SELECT; Includes are resolved by a multi-query that assembles parents and children in memory
        var roots = await MaterializeRootsAsync(
            connection,
            plan,
            whereClause,
            parameters,
            plan.Take,
            plan.Skip,
            cancellationToken
        ).ConfigureAwait(false);
        await IncludeLoader
            .For(typeof(TEntity))
            .LoadAsync(roots, plan.Includes, connection, cancellationToken).ConfigureAwait(false);
        return roots;
    }

    /// <summary>Fetches the entities matching the conditions with a projection (when the selector references only columns and there is no Include, only the referenced columns are plain-SELECTed).</summary>
    /// <remarks>
    /// When there is an Include, or column references cannot be safely extracted from the selector alone, falls back to
    /// the legacy path (fetch all columns, then project in memory). When pruning is possible, only the referenced columns
    /// are issued as a plain SELECT (no JSON), partially materialized, then projected.
    /// </remarks>
    public async Task<IReadOnlyList<TResult>> ToProjectionListAsync<TResult>(
        SqlQueryPlan<TEntity> plan,
        Expression<Func<TEntity, TResult>> selector,
        CancellationToken cancellationToken
    )
    {
        var metadata = EntitySaveMetadata.For(typeof(TEntity));

        // Prune columns server-side only when there is no Include and the selector references columns only (all column properties)
        var projectionColumns =
            plan.Includes.Count == 0
            && ProjectionColumnCollector.TryCollect(selector, out var referenced)
                ? metadata.ResolveProjectionColumns(referenced)
                : null;

        var project = selector.Compile();

        if (projectionColumns is null)
        {
            // Fallback: materialize all columns, then project in memory
            var entities = await ToListAsync(plan, cancellationToken).ConfigureAwait(false);
            return entities.Select(project).ToList();
        }

        // Server-side column pruning: plain-SELECT only the referenced columns, partially materialize, then project
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);
        var sql =
            $"SELECT {metadata.BuildColumnList(projectionColumns)} FROM {TableName}{whereClause}{BuildOrderAndPaging(plan, plan.Take, plan.Skip)};";

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = CreateCommand(connection, sql, parameters);
        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        // Column-name-to-ordinal mapping is resolved only once per result set
        var ordinals = metadata.ColumnOrdinals(reader, projectionColumns);

        var results = new List<TResult>();

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            // Apply the projection to a partial entity with only the referenced columns populated (RowState is irrelevant; the entity is discarded after projection)
            var entity = metadata.MapEntityColumns<TEntity>(reader, projectionColumns, ordinals);
            results.Add(project(entity));
        }

        return results;
    }

    /// <summary>Fetches the first entity matching the conditions (together with the requested Includes); returns null when there is no match.</summary>
    public async Task<TEntity?> FirstOrDefaultAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    )
    {
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);

        if (plan.WithUnboundedBinary)
        {
            // Unbounded binary columns requested: materialize the first row with an all-column plain SELECT (no-Include is already guarded at the terminal)
            var withBinary = await MaterializeWithUnboundedBinaryAsync(
                plan,
                whereClause,
                parameters,
                take: 1,
                plan.Skip,
                cancellationToken
            ).ConfigureAwait(false);
            return withBinary.Count > 0 ? withBinary[0] : null;
        }
        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        // Materialize only the first row (LIMIT 1) and resolve Includes against that single row
        var roots = await MaterializeRootsAsync(
            connection,
            plan,
            whereClause,
            parameters,
            take: 1,
            plan.Skip,
            cancellationToken
        ).ConfigureAwait(false);
        if (roots.Count == 0)
        {
            return null;
        }

        await IncludeLoader
            .For(typeof(TEntity))
            .LoadAsync(roots, plan.Includes, connection, cancellationToken).ConfigureAwait(false);
        return roots[0];
    }

    /// <summary>Returns the count of rows matching the conditions (orderings, paging, and Include are not involved).</summary>
    public async Task<int> CountAsync(SqlQueryPlan<TEntity> plan, CancellationToken cancellationToken)
    {
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = CreateCommand(
            connection,
            $"SELECT COUNT(*) FROM {TableName}{whereClause};",
            parameters
        );
        var result = await command.ExecuteScalarAsync(cancellationToken).ConfigureAwait(false);
        return Convert.ToInt32(result);
    }

    /// <summary>Returns whether any record matching the conditions exists (orderings, paging, and Include are not involved).</summary>
    public async Task<bool> AnyAsync(SqlQueryPlan<TEntity> plan, CancellationToken cancellationToken)
    {
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = CreateCommand(
            connection,
            $"SELECT CASE WHEN EXISTS (SELECT 1 FROM {TableName}{whereClause}) THEN 1 ELSE 0 END;",
            parameters
        );
        var result = await command.ExecuteScalarAsync(cancellationToken).ConfigureAwait(false);
        return Convert.ToInt32(result) != 0;
    }

    /// <summary>Bulk-deletes the rows matching the conditions. When cascadeDelete=true, descendants are also deleted along FK chains.</summary>
    public async Task<int> ExecuteDeleteAsync(
        SqlQueryPlan<TEntity> plan,
        bool cascadeDelete,
        CancellationToken cancellationToken
    )
    {
        var parameters = new List<SqlQueryParameter>();
        var whereClause = BuildWhereClause(plan, parameters);

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        if (!cascadeDelete)
        {
            await using var command = CreateCommand(
                connection,
                $"DELETE FROM {TableName}{whereClause};",
                parameters
            );
            return await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
        }

        // Cascade: execute the DELETE statements ordered descendants-first, then the target, in a single transaction
        await using var transaction = (SqliteTransaction)
            await connection.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);

        try
        {
            var rows = 0;

            foreach (
                var sql in CascadeDeletePlanner.BuildDeleteStatements(
                    typeof(TEntity),
                    TableName,
                    whereClause
                )
            )
            {
                await using var command = new SqliteCommand(sql, connection, transaction);
                AddParameters(command, parameters);
                rows += await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
            }

            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
            return rows;
        }
        catch
        {
            // Roll back with CancellationToken.None: a canceled token must not interrupt the rollback or mask the original exception.
            await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
            throw;
        }
    }

    /// <summary>
    /// Materialization for WithUnboundedBinary. Plain-SELECTs all columns (including unbounded binary columns)
    /// without Include, materializing legitimate entities with RowState=Unchanged (shared across dialects).
    /// On SQL Server this avoids the default JSON path (Base64) and prevents memory inflation. No-Include only (guarded at the terminal).
    /// </summary>
    private async Task<IReadOnlyList<TEntity>> MaterializeWithUnboundedBinaryAsync(
        SqlQueryPlan<TEntity> plan,
        string whereClause,
        IReadOnlyList<SqlQueryParameter> parameters,
        int? take,
        int? skip,
        CancellationToken cancellationToken
    )
    {
        var metadata = EntitySaveMetadata.For(typeof(TEntity));
        // Plain-SELECT all columns (including the excluded ones, i.e. unbounded binary columns)
        var sql =
            $"SELECT {metadata.BuildColumnList(metadata.AllProperties)} FROM {TableName}{whereClause}{BuildOrderAndPaging(plan, take, skip)};";

        await using var connection = _connectionFactory.CreateConnection();
        await connection.OpenAsync(cancellationToken).ConfigureAwait(false);

        await using var command = CreateCommand(connection, sql, parameters);
        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        // Column-name-to-ordinal mapping is resolved only once per result set
        var ordinals = metadata.ColumnOrdinals(reader, metadata.AllProperties);

        var results = new List<TEntity>();

        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            // Materialize as a legitimate entity (RowState=Unchanged) with all columns bound
            results.Add(
                metadata.MapEntityColumns<TEntity>(
                    reader,
                    metadata.AllProperties,
                    ordinals,
                    markUnchanged: true
                )
            );
        }

        return results;
    }

    /// <summary>Fetches the roots with a plain SELECT and materializes them via a DataReader (the root set before Includes).</summary>
    private async Task<List<TEntity>> MaterializeRootsAsync(
        SqliteConnection connection,
        SqlQueryPlan<TEntity> plan,
        string whereClause,
        IReadOnlyList<SqlQueryParameter> parameters,
        int? take,
        int? skip,
        CancellationToken cancellationToken
    )
    {
        var metadata = EntitySaveMetadata.For(typeof(TEntity));
        var sql =
            $"SELECT {metadata.ColumnList} FROM {TableName}{whereClause}{BuildOrderAndPaging(plan, take, skip)};";

        await using var command = CreateCommand(connection, sql, parameters);
        await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

        // Column-name-to-ordinal mapping is resolved only once per result set
        var ordinals = metadata.SelectOrdinals(reader);

        var roots = new List<TEntity>();
        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
        {
            roots.Add((TEntity)(object)metadata.MapEntityObject(reader, ordinals));
        }

        return roots;
    }

    /// <summary>Builds the ORDER BY / LIMIT-OFFSET clauses (on SQLite, skip-only uses LIMIT -1 to allow all rows).</summary>
    private static string BuildOrderAndPaging(SqlQueryPlan<TEntity> plan, int? take, int? skip)
    {
        var orderings = BuildOrderings(plan);
        var ordering =
            orderings.Count == 0 ? string.Empty : " ORDER BY " + string.Join(", ", orderings);

        if (take.HasValue && skip.HasValue)
        {
            return $"{ordering} LIMIT {take.Value} OFFSET {skip.Value}";
        }

        if (take.HasValue)
        {
            return $"{ordering} LIMIT {take.Value}";
        }

        if (skip.HasValue)
        {
            // OFFSET requires LIMIT. Attach an unbounded LIMIT -1 so the skip is applied and everything after it is fetched
            return $"{ordering} LIMIT -1 OFFSET {skip.Value}";
        }

        return ordering;
    }

    /// <summary>Translates the plan's orderings (expression trees) into SQL ORDER BY elements ("[col] ASC", etc.).</summary>
    private static List<string> BuildOrderings(SqlQueryPlan<TEntity> plan)
    {
        var orderings = new List<string>(plan.Orderings.Count);
        foreach (var ordering in plan.Orderings)
        {
            orderings.Add(
                SqlExpressionTranslator.ToColumn(ordering.KeySelector)
                    + (ordering.Descending ? " DESC" : " ASC")
            );
        }

        return orderings;
    }

    /// <summary>Translates the plan's predicates (expression trees) into a WHERE clause, accumulating value parameters into parameters (empty string when there are no conditions).</summary>
    private static string BuildWhereClause(
        SqlQueryPlan<TEntity> plan,
        List<SqlQueryParameter> parameters
    )
    {
        if (plan.Predicates.Count == 0)
        {
            return string.Empty;
        }

        var conditions = new List<string>(plan.Predicates.Count);
        foreach (var predicate in plan.Predicates)
        {
            conditions.Add(SqlExpressionTranslator.ToCondition(predicate.Body, parameters));
        }

        return " WHERE " + string.Join(" AND ", conditions);
    }

    /// <summary>Creates a command with the accumulated parameters applied.</summary>
    private SqliteCommand CreateCommand(
        SqliteConnection connection,
        string sql,
        IReadOnlyList<SqlQueryParameter> parameters
    )
    {
        var command = new SqliteCommand(sql, connection);
        AddParameters(command, parameters);
        return command;
    }

    /// <summary>Applies the translated condition parameters to the command.</summary>
    /// <remarks>
    /// SQLite defers to Microsoft.Data.Sqlite's default conversions, so all parameters are bound with AddWithValue.
    /// </remarks>
    private static void AddParameters(
        SqliteCommand command,
        IReadOnlyList<SqlQueryParameter> parameters
    )
    {
        var metadata = EntitySaveMetadata.For(typeof(TEntity));
        foreach (var parameter in parameters)
        {
            var value =
                parameter.Value;
            metadata.AddQueryParameter(command, parameter.Name, parameter.ColumnName, value);
        }
    }
}

/// <summary>
/// A dialect-neutral engine that resolves the Include tree with a multi-query: "parent query, then children via an IN clause in a separate query, then assembly in memory".
/// </summary>
/// <remarks>
/// <para>
/// Same idea as EF Core's Split Query. It collects the parent set's PK/FK values, pulls the child table once with
/// <c>WHERE fk IN (@p0..@pn)</c>, and recurses along the IncludeNode tree. Dialect dependence in the SQL text is limited
/// to identifier quoting and the IN clause, so future dialects can reuse it. FK metadata comes from
/// <see cref="NavigationReferenceAttribute"/> (a property attribute) and <see cref="EntitySaveMetadata"/>.
/// </para>
/// <para>Built once per type and cached (same philosophy as <see cref="EntitySaveMetadata"/>).</para>
/// </remarks>
internal sealed class IncludeLoader
{
    private static readonly ConcurrentDictionary<Type, IncludeLoader> _cache = new();

    private readonly EntitySaveMetadata _metadata;

    private IncludeLoader(Type entityType) => _metadata = EntitySaveMetadata.For(entityType);

    /// <summary>Gets the Include loader for the specified type (built once per type and cached).</summary>
    public static IncludeLoader For(Type entityType) =>
        _cache.GetOrAdd(entityType, static t => new IncludeLoader(t));

    /// <summary>Loads the children described by the Include tree for the parent set and binds them to navigation properties.</summary>
    public async Task LoadAsync(
        IReadOnlyList<object> parents,
        IReadOnlyList<IncludeNode> includes,
        SqliteConnection connection,
        CancellationToken cancellationToken
    )
    {
        if (parents.Count == 0 || includes.Count == 0)
        {
            return;
        }

        foreach (var node in includes)
        {
            await LoadNodeAsync(parents, node, connection, cancellationToken).ConfigureAwait(false);
        }
    }

    /// <summary>Loads a single Include node (and its ThenInclude descendants) and binds them to the parents.</summary>
    private async Task LoadNodeAsync(
        IReadOnlyList<object> parents,
        IncludeNode node,
        SqliteConnection connection,
        CancellationToken cancellationToken
    )
    {
        var attribute =
            EntitySaveMetadata.NavigationAttribute(node.Property)
            ?? throw new InvalidOperationException(
                $"{node.Property.Name} is not a navigation marked with [NavigationReference]."
            );
        var childType = attribute.IsCollection
            ? node.Property.PropertyType.GetGenericArguments()[0]
            : node.Property.PropertyType;
        var childMetadata = EntitySaveMetadata.For(childType);

        // Correlation: parent reference is child.[Principal] = parent.[Dependent]; child direction is child.[Dependent] = parent.[Principal]
        var parentKeyColumn = attribute.IsParentReference
            ? attribute.DependentColumn
            : attribute.PrincipalColumn;
        var childKeyColumn = attribute.IsParentReference
            ? attribute.PrincipalColumn
            : attribute.DependentColumn;

        // Collect the parent-side key values (non-null). When the set is empty, no child query is issued
        var parentKeys = new List<object>();
        foreach (var parent in parents)
        {
            var key = _metadata.GetColumnValue((EntityBase)parent, parentKeyColumn);
            if (key is not null)
            {
                parentKeys.Add(key);
            }
        }

        var distinctKeys = parentKeys.Distinct().ToList();
        if (distinctKeys.Count == 0)
        {
            return;
        }

        var children = await QueryChildrenAsync(
            childMetadata,
            childKeyColumn,
            distinctKeys,
            connection,
            cancellationToken
        ).ConfigureAwait(false);

        // Group the children by FK value and bind them to their parents
        var childrenByKey = new Dictionary<object, List<EntityBase>>();
        foreach (var child in children)
        {
            var fk = childMetadata.GetColumnValue(child, childKeyColumn);
            if (fk is null)
            {
                continue;
            }

            if (!childrenByKey.TryGetValue(fk, out var bucket))
            {
                bucket = new List<EntityBase>();
                childrenByKey[fk] = bucket;
            }

            bucket.Add(child);
        }

        AssignChildren(parents, node.Property, attribute, childType, childrenByKey, parentKeyColumn);

        // Recursively load ThenInclude (descendants), treating the children as parents
        if (node.Children.Count > 0 && children.Count > 0)
        {
            await IncludeLoader
                .For(childType)
                .LoadAsync(children, node.Children, connection, cancellationToken).ConfigureAwait(false);
        }
    }

    /// <summary>
    /// The maximum number of keys per IN clause. Chosen to fit within database bind-variable / IN-list limits
    /// across dialects (Oracle's 1000, SQL Server's 2100 parameters, SQLite's historical 999, etc.).
    /// </summary>
    private const int InClauseChunkSize = 500;

    /// <summary>Pulls the child table with <c>WHERE fk IN (@i0..@in)</c> and materializes the rows (keys are chunked to stay within limits).</summary>
    private static async Task<List<EntityBase>> QueryChildrenAsync(
        EntitySaveMetadata childMetadata,
        string childKeyColumn,
        IReadOnlyList<object> keys,
        SqliteConnection connection,
        CancellationToken cancellationToken
    )
    {
        var children = new List<EntityBase>();

        for (var offset = 0; offset < keys.Count; offset += InClauseChunkSize)
        {
            var count = Math.Min(InClauseChunkSize, keys.Count - offset);
            var placeholders = new string[count];
            for (var i = 0; i < count; i++)
            {
                placeholders[i] = "@i" + i;
            }

            var sql =
                $"SELECT {childMetadata.ColumnList} FROM {childMetadata.TableName} "
                + $"WHERE \"{childKeyColumn}\" IN ({string.Join(", ", placeholders)});";

            await using var command = new SqliteCommand(sql, connection);
            for (var i = 0; i < count; i++)
            {
                command.Parameters.AddWithValue(placeholders[i], keys[offset + i]);
            }

            await using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);

            // Column-name-to-ordinal mapping is resolved only once per result set (chunk)
            var ordinals = childMetadata.SelectOrdinals(reader);

            while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
            {
                children.Add(childMetadata.MapEntityObject(reader, ordinals));
            }
        }

        return children;
    }

    /// <summary>Assigns the grouped children to each parent's navigation property (collection or single reference).</summary>
    private void AssignChildren(
        IReadOnlyList<object> parents,
        PropertyInfo navigation,
        NavigationReferenceAttribute attribute,
        Type childType,
        Dictionary<object, List<EntityBase>> childrenByKey,
        string parentKeyColumn
    )
    {
        foreach (var parent in parents)
        {
            var key = _metadata.GetColumnValue((EntityBase)parent, parentKeyColumn);
            var matched =
                key is not null && childrenByKey.TryGetValue(key, out var bucket)
                    ? bucket
                    : new List<EntityBase>();

            if (attribute.IsCollection)
            {
                // Create a concrete List for ICollection<childType> and fill in each element
                var listType = typeof(List<>).MakeGenericType(childType);
                var list = (System.Collections.IList)Activator.CreateInstance(listType)!;
                foreach (var child in matched)
                {
                    list.Add(child);
                }

                navigation.SetValue(parent, list);
            }
            else
            {
                navigation.SetValue(parent, matched.Count > 0 ? matched[0] : null);
            }
        }
    }
}

/// <summary>Translates lambda expressions (expression trees) into SQL conditions and column references.</summary>
/// <remarks>
/// Supported constructs are limited to comparisons (== != &lt; &lt;= &gt; &gt;=), logical combinations (&amp;&amp; ||), negation, null checks, bool columns, and string Contains/StartsWith/EndsWith; anything outside this set throws.
/// An <c>==</c> / <c>!=</c> comparison whose value side is null is compensated to <c>IS NULL</c> / <c>IS NOT NULL</c> (the same meaning C# and EF Core give it), whether the null is written as a literal or comes from a variable.
/// </remarks>
internal static class SqlExpressionTranslator
{
    /// <summary>Translates the body of a predicate lambda into a SQL condition, parameterizing values and appending them to parameters.</summary>
    public static string ToCondition(
        Expression expression,
        List<SqlQueryParameter> parameters
    ) => Visit(expression, parameters);

    /// <summary>Extracts the bracketed column name from a key-selecting lambda.</summary>
    public static string ToColumn(LambdaExpression keySelector)
    {
        var member = Unwrap(keySelector.Body) as MemberExpression;

        if (member is null || !IsColumn(member))
        {
            throw new NotSupportedException(
                $"Only entity properties can be specified as an ordering: {keySelector}"
            );
        }

        return ColumnName(member.Member);
    }

    private static string Visit(
        Expression expression,
        List<SqlQueryParameter> parameters
    )
    {
        switch (expression)
        {
            case BinaryExpression { NodeType: ExpressionType.AndAlso } binary:
                return $"({Visit(binary.Left, parameters)} AND {Visit(binary.Right, parameters)})";

            case BinaryExpression { NodeType: ExpressionType.OrElse } binary:
                return $"({Visit(binary.Left, parameters)} OR {Visit(binary.Right, parameters)})";

            case BinaryExpression binary:
                return VisitComparison(binary, parameters);

            case UnaryExpression { NodeType: ExpressionType.Not } unary:
                return Unwrap(unary.Operand) is MemberExpression boolMember && IsColumn(boolMember)
                    ? $"{ColumnName(boolMember.Member)} = 0"
                    : $"NOT ({Visit(unary.Operand, parameters)})";

            case MethodCallExpression call
                when TryGetLike(call, out var likeColumn, out var likeKind):

                // When the argument is a column, this is a column-to-column LIKE (the pattern is escaped and assembled on the SQL side; rows where the argument column is NULL do not match)
                if (TryColumnName(call.Arguments[0]) is { } patternColumn)
                {
                    return $"{likeColumn} LIKE {BuildLikePatternFromColumn(patternColumn, likeKind)} ESCAPE '\\'";
                }

                // The argument may be a string or a value object (the TSelf overload). Value objects are unwrapped to the raw value (string)
                // A null pattern is unreachable when the query was built through SqlQuery.Where (the guard rejects it up front); kept as defense in depth
                var raw =
                    Evaluate(call.Arguments[0]) as string
                    ?? throw new ArgumentNullException(
                        "value",
                        "The pattern argument of Contains/StartsWith/EndsWith in a query predicate must not be null."
                    );
                var pattern = likeKind switch
                {
                    LikeKind.Contains => "%" + EscapeLike(raw) + "%",
                    LikeKind.StartsWith => EscapeLike(raw) + "%",
                    _ => "%" + EscapeLike(raw),
                };
                return $"{likeColumn} LIKE {AddParameter(pattern, parameters, RawColumnName(likeColumn))} ESCAPE '\\'";

            case MethodCallExpression call
                when TryGetIn(call, out var inColumn, out var inCollection):
                return BuildInClause(inColumn, inCollection, parameters);

            case MethodCallExpression call
                when TryGetNullOrEmpty(call, out var neColumn, out var neWhitespace):
                // Empty-string check. IsNullOrWhiteSpace also treats surrounding whitespace as empty
                return neWhitespace
                    ? $"({neColumn} IS NULL OR LTRIM(RTRIM({neColumn})) = '')"
                    : $"({neColumn} IS NULL OR {neColumn} = '')";

            case MethodCallExpression call
                when TryGetEquals(call, out var eqColumn, out var eqArg, out var eqIgnoreCase):

                // When the argument is a column, this is a column-to-column equality (IgnoreCase variants fold both sides with LOWER, same rule as the value path)
                if (TryColumnName(eqArg) is { } eqArgColumn)
                {
                    return eqIgnoreCase
                        ? $"LOWER({eqColumn}) = LOWER({eqArgColumn})"
                        : $"{eqColumn} = {eqArgColumn}";
                }

                // The value is unwrapped to the raw value on the AddParameters side (value-object support)
                var eqParameter = AddParameter(Evaluate(eqArg), parameters, RawColumnName(eqColumn));
                // Case-insensitive comparisons fold both sides with LOWER
                return eqIgnoreCase
                    ? $"LOWER({eqColumn}) = LOWER({eqParameter})"
                    : $"{eqColumn} = {eqParameter}";

            case MemberExpression member when member.Type == typeof(bool) && IsColumn(member):
                return $"{ColumnName(member.Member)} = 1";

            default:
                throw new NotSupportedException($"This expression cannot be translated to SQL: {expression}");
        }
    }

    /// <summary>Translates a binary comparison, compensating for null values on the value side.</summary>
    /// <remarks>
    /// Each side is resolved once: an operand that stays on the SQL side (a column reference or a date component) is rendered as SQL,
    /// and every other operand is evaluated to its actual value. When an <c>==</c> / <c>!=</c> comparison has a value operand that turns
    /// out to be null (a literal null, or a variable / expression that evaluates to null), it becomes <c>IS NULL</c> / <c>IS NOT NULL</c>,
    /// which is what C# and EF Core mean by it. Binding the null as an ordinary parameter would instead leave <c>col = @p</c>, and SQL's
    /// three-valued logic makes that UNKNOWN for every row. The compensation is deliberately limited to equality: the relational operators
    /// (&lt; &lt;= &gt; &gt;=) keep binding the null as a parameter, because they have no null-aware SQL counterpart.
    /// </remarks>
    private static string VisitComparison(
        BinaryExpression binary,
        List<SqlQueryParameter> parameters
    )
    {
        var left = Unwrap(binary.Left);
        var right = Unwrap(binary.Right);

        // Resolve both sides once: SQL-side operands keep their SQL text, value-side operands are evaluated here (and reused below)
        var leftSql = OperandSql(left);
        var rightSql = OperandSql(right);
        var leftValue = leftSql is null ? Evaluate(left) : null;
        var rightValue = rightSql is null ? Evaluate(right) : null;

        if (binary.NodeType is ExpressionType.Equal or ExpressionType.NotEqual)
        {
            var suffix = binary.NodeType == ExpressionType.NotEqual ? "NOT " : string.Empty;

            if (leftSql is not null && rightSql is null && IsNullValue(rightValue))
            {
                return $"{leftSql} IS {suffix}NULL";
            }

            if (rightSql is not null && leftSql is null && IsNullValue(leftValue))
            {
                return $"{rightSql} IS {suffix}NULL";
            }
        }

        var op = binary.NodeType switch
        {
            ExpressionType.Equal => "=",
            ExpressionType.NotEqual => "<>",
            ExpressionType.GreaterThan => ">",
            ExpressionType.GreaterThanOrEqual => ">=",
            ExpressionType.LessThan => "<",
            ExpressionType.LessThanOrEqual => "<=",
            _ => throw new NotSupportedException($"Unsupported operator: {binary.NodeType}"),
        };

        // In a column-versus-value comparison, the value parameter carries the opposing column name for explicit typing (omitted when both sides are columns or both are values)
        return $"{leftSql ?? AddParameter(leftValue, parameters, RawColumnName(rightSql))} {op} {rightSql ?? AddParameter(rightValue, parameters, RawColumnName(leftSql))}";
    }

    /// <summary>Renders an operand that stays on the SQL side (a column reference, or a date component of a date-time column). Returns null for a value operand.</summary>
    private static string? OperandSql(Expression expression) =>
        TryColumnName(expression) is { } column ? column
        : TryGetDatePart(expression, out var datePart) ? datePart
        : null;

    /// <summary>Whether an evaluated value operand is null.</summary>
    private static bool IsNullValue(object? value) => value is null;

    private enum LikeKind
    {
        Contains,
        StartsWith,
        EndsWith,
    }

    private static bool TryGetLike(MethodCallExpression call, out string column, out LikeKind kind)
    {
        column = string.Empty;
        kind = LikeKind.Contains;

        if (
            call.Object is null
            || call.Arguments.Count != 1
            || (
                call.Method.DeclaringType != typeof(string)
            )
        )
        {
            return false;
        }

        if (Unwrap(call.Object) is not MemberExpression member || !IsColumn(member))
        {
            return false;
        }

        switch (call.Method.Name)
        {
            case "Contains":
                kind = LikeKind.Contains;
                break;
            case "StartsWith":
                kind = LikeKind.StartsWith;
                break;
            case "EndsWith":
                kind = LikeKind.EndsWith;
                break;
            default:
                return false;
        }

        column = ColumnName(member.Member);
        return true;
    }

    /// <summary>Determines whether a collection Contains (arrays = static Enumerable.Contains; List/HashSet = instance Contains) is a target for IN translation.</summary>
    /// <remarks>Only calls where the column is on the argument side are targeted (string.Contains with the column as the receiver is already handled by the LIKE path).</remarks>
    private static bool TryGetIn(
        MethodCallExpression call,
        out string column,
        out Expression collection
    )
    {
        column = string.Empty;
        collection = null!;

        if (call.Method.Name != "Contains")
        {
            return false;
        }

        // Arrays etc.: static Enumerable.Contains / MemoryExtensions.Contains(collection, item) (two arguments, no receiver).
        // With C# 14 first-class spans, array.Contains(x) resolves to MemoryExtensions.Contains(span, item, comparer),
        // so the three-argument form is also accepted when the comparer is null (= default equality, same IN semantics).
        // A non-null comparer cannot be translated to SQL and falls through to the unsupported-expression error.
        if (call.Object is null && call.Arguments.Count is 2 or 3)
        {
            if (
                call.Arguments.Count == 3
                && Unwrap(call.Arguments[2]) is not ConstantExpression { Value: null }
            )
            {
                return false;
            }

            if (Unwrap(call.Arguments[1]) is MemberExpression staticItem && IsColumn(staticItem))
            {
                column = ColumnName(staticItem.Member);
                collection = UnwrapCollection(call.Arguments[0]);
                return true;
            }

            return false;
        }

        // List<T> / HashSet<T> etc.: instance Contains(item) (one argument, the receiver is the collection)
        // Arrays resolve to .NET's span-based Contains, where the receiver becomes op_Implicit(array) (UnwrapCollection restores the raw array)
        if (call.Object is not null && call.Arguments.Count == 1)
        {
            if (Unwrap(call.Arguments[0]) is MemberExpression instanceItem && IsColumn(instanceItem))
            {
                column = ColumnName(instanceItem.Member);
                collection = UnwrapCollection(call.Object);
                return true;
            }
        }

        return false;
    }

    /// <summary>Strips implicit conversions attached to a collection expression (op_Implicit / Convert such as array-to-ReadOnlySpan), restoring the raw enumerable collection expression.</summary>
    private static Expression UnwrapCollection(Expression expression)
    {
        while (true)
        {
            expression = Unwrap(expression);
            if (
                expression
                is MethodCallExpression
                {
                    Method.Name: "op_Implicit",
                    Object: null,
                    Arguments.Count: 1
                } conversion
            )
            {
                expression = conversion.Arguments[0];
                continue;
            }

            return expression;
        }
    }

    /// <summary>Builds an IN clause by parameterizing each element of the collection. Empty or null collections become a no-match (always-false condition).</summary>
    private static string BuildInClause(
        string column,
        Expression collection,
        List<SqlQueryParameter> parameters
    )
    {
        // Strings are IEnumerable themselves but are not treated as enumerable collections here
        if (Evaluate(collection) is not IEnumerable enumerable || enumerable is string)
        {
            throw new NotSupportedException(
                $"IN searches require an enumerable collection (array, List, etc.): {collection}"
            );
        }

        var placeholders = new List<string>();
        var rawColumn = RawColumnName(column);
        foreach (var item in enumerable)
        {
            placeholders.Add(AddParameter(item, parameters, rawColumn));
        }

        // IN () is invalid SQL, so an empty collection becomes an always-false condition meaning "no match"
        return placeholders.Count == 0
            ? "1 = 0"
            : $"{column} IN ({string.Join(", ", placeholders)})";
    }

    /// <summary>Determines whether x.Col.Equals(value) is a target for equality translation. When the second argument is a *IgnoreCase StringComparison, case is ignored.</summary>
    /// <remarks>The column may be a plain column or a value object. Any column type (string, numeric, etc.) can be translated to equality.</remarks>
    private static bool TryGetEquals(
        MethodCallExpression call,
        out string column,
        out Expression argument,
        out bool ignoreCase
    )
    {
        column = string.Empty;
        argument = null!;
        ignoreCase = false;

        if (
            call.Object is null
            || call.Method.Name != "Equals"
            || TryColumnName(call.Object) is not { } resolvedColumn
        )
        {
            return false;
        }

        // Only the two forms Equals(value) / Equals(value, StringComparison) are supported
        if (call.Arguments.Count == 1)
        {
            column = resolvedColumn;
            argument = call.Arguments[0];
            return true;
        }

        if (call.Arguments.Count == 2 && call.Method.DeclaringType == typeof(string))
        {
            ignoreCase = Evaluate(call.Arguments[1]) is StringComparison.OrdinalIgnoreCase
                or StringComparison.InvariantCultureIgnoreCase
                or StringComparison.CurrentCultureIgnoreCase;
            column = resolvedColumn;
            argument = call.Arguments[0];
            return true;
        }

        return false;
    }

    /// <summary>Detects string.IsNullOrEmpty(x.Col) / IsNullOrWhiteSpace(x.Col) (the column may be a plain column or a value object's .Value).</summary>
    private static bool TryGetNullOrEmpty(
        MethodCallExpression call,
        out string column,
        out bool whitespace
    )
    {
        column = string.Empty;
        whitespace = call.Method.Name == "IsNullOrWhiteSpace";

        if (
            call.Object is not null
            || call.Method.DeclaringType != typeof(string)
            || call.Arguments.Count != 1
            || !(call.Method.Name == "IsNullOrEmpty" || whitespace)
            || TryColumnName(call.Arguments[0]) is not { } resolvedColumn
        )
        {
            return false;
        }

        column = resolvedColumn;
        return true;
    }

    /// <summary>Removes Convert nodes such as boxing to object.</summary>
    private static Expression Unwrap(Expression expression)
    {
        while (
            expression
                is UnaryExpression
                {
                    NodeType: ExpressionType.Convert or ExpressionType.ConvertChecked
                } unary
        )
        {
            expression = unary.Operand;
        }

        return expression;
    }

    /// <summary>Whether the member is a property reference on the lambda parameter (i.e. a column).</summary>
    private static bool IsColumn(MemberExpression member) =>
        member is { Expression: ParameterExpression, Member: PropertyInfo };

    /// <summary>Caches member-to-bracketed-column-name resolution per type member (avoiding [Column] reflection for every column reference).</summary>
    private static readonly ConcurrentDictionary<MemberInfo, string> _columnNameCache = new();

    private static string ColumnName(MemberInfo member) =>
        _columnNameCache.GetOrAdd(
            member,
            static m => $"\"{m.GetCustomAttribute<ColumnAttribute>()?.Name ?? m.Name}\""
        );

    /// <summary>Extracts the bracketed column name from a column reference (a plain column x.Col, or a value object's x.Col.Value). Returns null when it is not a column.</summary>
    private static string? TryColumnName(Expression expression)
    {
        if (Unwrap(expression) is not MemberExpression member)
        {
            return null;
        }

        if (IsColumn(member))
        {
            return ColumnName(member.Member);
        }

        return null;
    }

    /// <summary>Translates date-component references on DateTime columns (x.Col.Year / x.Col.Value.Month, etc.) into SQL date functions.</summary>
    private static bool TryGetDatePart(Expression expression, out string sql)
    {
        sql = string.Empty;

        if (
            Unwrap(expression) is not MemberExpression member
            || member.Expression is not { } source
            || TryColumnName(source) is not { } column
        )
        {
            return false;
        }

        sql = member.Member.Name switch
        {
            // SQLite stores date-times as ISO8601 TEXT, so extract the part with strftime and CAST to INTEGER
            "Year" => $"CAST(strftime('%Y', {column}) AS INTEGER)",
            "Month" => $"CAST(strftime('%m', {column}) AS INTEGER)",
            "Day" => $"CAST(strftime('%d', {column}) AS INTEGER)",
            "Hour" => $"CAST(strftime('%H', {column}) AS INTEGER)",
            "Minute" => $"CAST(strftime('%M', {column}) AS INTEGER)",
            "Second" => $"CAST(strftime('%S', {column}) AS INTEGER)",
            "DayOfYear" => $"CAST(strftime('%j', {column}) AS INTEGER)",
            "Date" => $"date({column})",
            _ => string.Empty,
        };

        return sql.Length != 0;
    }

    /// <summary>
    /// Evaluates constants, closure variables, and the like to obtain the actual value. Most cases are constants or
    /// field/property references on a closure capturing local variables, so they are read directly via reflection,
    /// avoiding (expensive) expression-tree compilation. Only other expressions such as method calls are evaluated
    /// with <see cref="Expression.Lambda(Expression, ParameterExpression[])"/> as before.
    /// </summary>
    private static object? Evaluate(Expression expression)
    {
        // Entity column references (the lambda parameter) cannot be evaluated as values. Reject explicitly before expression-tree compilation fails with an internal error
        if (ReferencesLambdaParameter(expression))
        {
            throw new NotSupportedException(
                $"This expression cannot be translated to SQL (entity columns cannot appear in a value position): {expression}"
            );
        }

        switch (expression)
        {
            // Constants return their value as-is
            case ConstantExpression constant:
                return constant.Value;

            // For field/property references, recursively evaluate the target instance (null for static members), then read via reflection
            case MemberExpression member:
                var instance = member.Expression is null ? null : Evaluate(member.Expression);

                return member.Member switch
                {
                    FieldInfo field => field.GetValue(instance),
                    PropertyInfo property => property.GetValue(instance),
                    _ => CompileAndInvoke(expression),
                };

            // Everything else (method calls, arithmetic, etc.) is evaluated by compiling the expression tree (compatibility-first fallback)
            default:
                return CompileAndInvoke(expression);
        }
    }

    /// <summary>Wraps an arbitrary expression tree in a lambda, compiles and invokes it to obtain the actual value (fallback for expressions that cannot be read directly via reflection).</summary>
    private static object? CompileAndInvoke(Expression expression) =>
        Expression.Lambda(expression).Compile().DynamicInvoke();

    /// <param name="value">The actual value to parameterize (may be null).</param>
    /// <param name="parameters">The list that receives the generated parameter.</param>
    /// <param name="columnName">The target column name (without brackets). Passed only when the column can be identified, and used for explicit typing.</param>
    private static string AddParameter(
        object? value,
        List<SqlQueryParameter> parameters,
        string? columnName = null
    )
    {
        var name = "@p" + parameters.Count;
        parameters.Add(new SqlQueryParameter(name, value, columnName));
        return name;
    }

    /// <summary>Extracts the raw column name from a bracketed column name "[col]". Returns null when it is not a simple column (null, wrapped in a function, etc.).</summary>
    private static string? RawColumnName(string? bracketedColumn) =>
        bracketedColumn is { Length: >= 2 } && bracketedColumn[0] == '"' && bracketedColumn[^1] == '"'
            ? bracketedColumn[1..^1]
            : null;

    /// <summary>Escapes the LIKE wildcards (% _ [ \).</summary>
    private static string EscapeLike(string value) =>
        value.Replace("\\", "\\\\").Replace("%", "\\%").Replace("_", "\\_").Replace("[", "\\[");

    /// <summary>Builds, on the SQL side, a LIKE pattern that treats the column value as a literal (the same 4 characters as EscapeLike, escaped via REPLACE).</summary>
    /// <remarks>Rows where the argument column is NULL yield a NULL concatenation, then LIKE NULL, and thus no match. This is the column-argument case only: a null value argument never reaches SQL because SqlQuery.Where rejects it up front.</remarks>
    private static string BuildLikePatternFromColumn(string column, LikeKind kind)
    {
        var escaped =
            $"REPLACE(REPLACE(REPLACE(REPLACE({column}, '\\', '\\\\'), '%', '\\%'), '_', '\\_'), '[', '\\[')";

        return kind switch
        {
            LikeKind.Contains => $"'%' || {escaped} || '%'",
            LikeKind.StartsWith => $"{escaped} || '%'",
            _ => $"'%' || {escaped}",
        };
    }

    /// <summary>Walks the expression tree to determine whether it contains a lambda parameter (i.e. an entity column reference).</summary>
    private static bool ReferencesLambdaParameter(Expression expression)
    {
        var finder = new LambdaParameterFinder();
        finder.Visit(expression);
        return finder.Found;
    }

    /// <summary>A lightweight visitor that merely raises a flag when it finds a lambda-parameter reference.</summary>
    private sealed class LambdaParameterFinder : ExpressionVisitor
    {
        public bool Found { get; private set; }

        protected override Expression VisitParameter(ParameterExpression node)
        {
            Found = true;
            return node;
        }
    }
}

/// <summary>Why a save was rejected as a conflict (the classification carried by <see cref="SaveConflictException"/>).</summary>
public enum SaveConflictReason
{
    /// <summary>The reason was not reported (the exception was constructed directly rather than through a factory).</summary>
    Unknown,

    /// <summary>The row the save targeted no longer exists (it was deleted by someone else).</summary>
    NotFound,

    /// <summary>The row still exists, but its version moved on after the entity was read.</summary>
    Modified,
}

/// <summary>Represents an exception indicating that a record could not be saved because another party changed it first (it was deleted, or its version moved on).</summary>
/// <remarks>
/// <see cref="Reason"/>, <see cref="EntityTypeName"/>, and <see cref="Key"/> carry the material a reload-and-retry loop
/// needs, so the message does not have to be parsed. They are filled in by the factory methods; an instance built with the
/// message-only constructor reports <see cref="SaveConflictReason.Unknown"/> and nulls. The same details survive the remote
/// transport (HTTP 409), so a caller behaves identically against a direct and a remote repository.
/// </remarks>
public sealed class SaveConflictException : Exception
{
    /// <summary>Initializes a new instance with the specified message (no details: the reason stays <see cref="SaveConflictReason.Unknown"/>).</summary>
    public SaveConflictException(string message)
        : base(message) { }

    /// <summary>Initializes a new instance with the specified message and the details of the rejected save.</summary>
    /// <param name="message">The message describing the conflict.</param>
    /// <param name="reason">Why the save was rejected.</param>
    /// <param name="entityTypeName">The CLR type name (<c>Type.Name</c>) of the entity whose save was rejected, or <c>null</c> when unknown.</param>
    /// <param name="key">The primary key the save targeted, formatted for display, or <c>null</c> when unknown.</param>
    public SaveConflictException(
        string message,
        SaveConflictReason reason,
        string? entityTypeName,
        string? key
    )
        : base(message)
    {
        Reason = reason;
        EntityTypeName = entityTypeName;
        Key = key;
    }

    /// <summary>Gets why the save was rejected (<see cref="SaveConflictReason.Unknown"/> when the exception carries no details).</summary>
    public SaveConflictReason Reason { get; }

    /// <summary>Gets the CLR type name of the entity whose save was rejected (<c>null</c> when unknown).</summary>
    public string? EntityTypeName { get; }

    /// <summary>Gets the primary key the rejected save targeted, formatted for display (<c>null</c> when unknown).</summary>
    public string? Key { get; }

    /// <summary>Creates the conflict reported when the row an update targeted no longer exists.</summary>
    /// <param name="entityType">The type of the entity whose save was rejected.</param>
    /// <param name="key">The primary key value the save targeted.</param>
    public static SaveConflictException NotFound(Type entityType, object? key) =>
        new(
            $"The record to update was not found ({entityType.Name}, key {key}). It may have been deleted by another user.",
            SaveConflictReason.NotFound,
            entityType.Name,
            key?.ToString()
        );

    /// <summary>Creates the conflict reported when the row still exists but was changed by someone else after the entity was read.</summary>
    /// <param name="entityType">The type of the entity whose save was rejected.</param>
    /// <param name="key">The primary key value the save targeted.</param>
    /// <param name="operation">The lowercase verb of the rejected operation ("update" or "delete").</param>
    public static SaveConflictException Modified(
        Type entityType,
        object? key,
        string operation
    ) =>
        new(
            $"The record to {operation} was modified by another user ({entityType.Name}, key {key}). Reload the entity and try again.",
            SaveConflictReason.Modified,
            entityType.Name,
            key?.ToString()
        );
}

/// <summary>A child navigation targeted by cascading (property, collection kind, child type, and FK information).</summary>
internal sealed record CascadeNavigation(
    PropertyInfo Property,
    bool IsCollection,
    Type ChildType,
    string PrincipalColumn,
    string DependentColumn
);

/// <summary>The routes the generated remote server and its clients agree on.</summary>
/// <remarks>
/// Both sides read the values from here so the prefix is written down once: the server's
/// <c>MapGeneratedRemoteEndpoints</c> defaults to <see cref="DefaultPrefix"/>, and a client's base address has to
/// include whichever prefix the server was mapped under.
/// </remarks>
public static class RemotePaths
{
    /// <summary>The route prefix the generated endpoints are mapped under unless another one is passed to <c>MapGeneratedRemoteEndpoints</c>.</summary>
    public const string DefaultPrefix = "/quicker";

    /// <summary>The liveness endpoint's route, relative to the prefix (<c>GET {prefix}/health</c>).</summary>
    public const string HealthRoute = "health";
}

/// <summary>Shared serialization settings used for remote transport (HTTP + JSON).</summary>
/// <remarks>
/// Uses the same semantics as entity JSON round-trips (<see cref="EntityBase.ToJson"/> / <see cref="EntityBase.Clone"/>)
/// (get/set properties only, RowState included, no cycles because parent-reference navigations are [JsonIgnore]),
/// plus case-insensitive reading for transport. Client and server both use these settings so the wire representation matches.
/// </remarks>
public static class RemoteJson
{
    /// <summary>Transport JSON settings shared by client and server.</summary>
    /// <remarks>
    /// IgnoreReadOnlyProperties is intentionally not set (the anonymous types used as query-transport envelopes have
    /// get-only properties, so setting it would serialize an empty JSON body). Derived entity flags (get-only bools
    /// such as IsAdded) are serialized redundantly, but they have no setter and are ignored on read, so the
    /// round-trip semantics (RowState included) are unchanged.
    /// </remarks>
    public static JsonSerializerOptions Options { get; } =
        new()
        {
            ReferenceHandler = ReferenceHandler.IgnoreCycles,
            PropertyNameCaseInsensitive = true,
        };
}

/// <summary>Represents a remote call that failed with a server-side error (carries the HTTP status and the server's message).</summary>
/// <remarks>An optimistic conflict (HTTP 409) is restored as <see cref="SaveConflictException"/> rather than this exception, so the same catch blocks work as with a direct connection.</remarks>
public sealed class RemoteRepositoryException : Exception
{
    /// <summary>Initializes a new instance with the specified HTTP status code and message.</summary>
    public RemoteRepositoryException(int statusCode, string message)
        : base(message)
    {
        StatusCode = statusCode;
    }

    /// <summary>Gets the HTTP status code returned by the server.</summary>
    public int StatusCode { get; }
}

/// <summary>Structured payload for transport errors (server to client; the type restores the exception type on the client side).</summary>
/// <remarks>
/// The conflict detail fields (<see cref="Reason"/>, <see cref="EntityType"/>, <see cref="Key"/>) are written only for a
/// "SaveConflict" error and are optional on the wire: a body from a server built before they existed simply leaves them
/// null, and the restored <see cref="SaveConflictException"/> then reports <see cref="SaveConflictReason.Unknown"/>.
/// </remarks>
public sealed class RemoteError
{
    /// <summary>Gets or sets the error kind ("SaveConflict" = optimistic conflict / "BadRequest" = the request could not be interpreted / "Error" = anything else).</summary>
    public string Type { get; set; } = string.Empty;

    /// <summary>Gets or sets the server-side exception message.</summary>
    public string Message { get; set; } = string.Empty;

    /// <summary>Gets or sets the name of the <see cref="SaveConflictReason"/> behind a conflict (<c>null</c> for every other kind).</summary>
    public string? Reason { get; set; }

    /// <summary>Gets or sets the CLR type name of the entity whose save was rejected (<c>null</c> for every other kind).</summary>
    public string? EntityType { get; set; }

    /// <summary>Gets or sets the primary key the rejected save targeted, formatted for display (<c>null</c> for every other kind).</summary>
    public string? Key { get; set; }
}

/// <summary>Request body carrying a single primary key (GetById / Delete).</summary>
public sealed record RemoteIdRequest<TKey>(TKey Id);

/// <summary>Request body carrying a single entity (Insert).</summary>
public sealed record RemoteEntityRequest<TEntity>(TEntity Entity);

/// <summary>Request body for a single update (carries the concurrency policy alongside the entity).</summary>
/// <remarks>The policy defaults to <see cref="ConcurrencyMode.Optimistic"/>, so a body that omits it - one sent by a client built before the policy was carried - is read as the default.</remarks>
public sealed record RemoteUpdateRequest<TEntity>(
    TEntity Entity,
    ConcurrencyMode Mode = ConcurrencyMode.Optimistic
);

/// <summary>Request body for a graph save (single root).</summary>
public sealed record RemoteSaveRequest<TEntity>(
    TEntity Entity,
    bool CascadeSave,
    bool CascadeDelete,
    bool InsertWhenUpdateMissing,
    ConcurrencyMode Mode = ConcurrencyMode.Optimistic
);

/// <summary>Request body for a graph save (multiple roots).</summary>
public sealed record RemoteSaveManyRequest<TEntity>(
    List<TEntity> Entities,
    bool CascadeSave,
    bool CascadeDelete,
    bool InsertWhenUpdateMissing,
    ConcurrencyMode Mode = ConcurrencyMode.Optimistic
);

/// <summary>One row version a save assigned, identified by the entity's CLR type name and its primary key.</summary>
/// <remarks>
/// <paramref name="Key"/> is the primary key serialized with the transport settings (<see cref="RemoteJson.Options"/>),
/// which both sides produce the same way, so value-object keys and dialect differences round-trip unchanged.
/// </remarks>
/// <param name="EntityType">The CLR type name of the entity the version belongs to.</param>
/// <param name="Key">The entity's primary key, serialized with the transport settings.</param>
/// <param name="RowVersion">The row version the database assigned during the save.</param>
public sealed record RemoteRowVersionEntry(string EntityType, string Key, byte[] RowVersion);

/// <summary>One entity referenced across the transport, identified the same way as <see cref="RemoteRowVersionEntry"/> (CLR type name plus the serialized primary key).</summary>
/// <param name="EntityType">The CLR type name of the entity.</param>
/// <param name="Key">The entity's primary key, serialized with the transport settings.</param>
public sealed record RemoteEntityRef(string EntityType, string Key);

/// <summary>Response body of a single insert (the row version the database assigned, or <c>null</c> when the table carries no rowversion column).</summary>
public sealed record RemoteInsertResult(byte[]? RowVersion);

/// <summary>Response body of a single update (the result, plus the row version the database assigned when the table carries one).</summary>
public sealed record RemoteUpdateResult(bool Updated, byte[]? RowVersion);

/// <summary>Response body of a graph save (the affected row count, the row versions assigned across the saved graph, and the rows a save hook skipped).</summary>
/// <remarks>
/// The version list is empty for tables with no rowversion column, so backends that do not carry versions simply return
/// nothing to write back. <paramref name="Skipped"/> names the rows whose save was declined by a hook's Before, so that the
/// client can leave their RowState untouched exactly as a direct connection does; it defaults to <c>null</c> so that a
/// response produced before it was carried - one from a server built earlier - is read as "nothing was skipped".
/// </remarks>
public sealed record RemoteSaveResult(
    int Affected,
    List<RemoteRowVersionEntry> RowVersions,
    List<RemoteEntityRef>? Skipped = null
);

/// <summary>
/// Shared reflection over an entity graph for remote transport: the cascade navigations to walk, and the tables the server
/// collects after a save for the client to act on - the row versions (<see cref="RemoteRowVersionEntry"/>) to write back and
/// the rows (<see cref="RemoteEntityRef"/>) a save hook skipped.
/// </summary>
/// <remarks>
/// <para>
/// Both sides identify an entity the same way - CLR type name plus the primary key serialized with
/// <see cref="RemoteJson.Options"/> - so this single place defines the correspondence between the two.
/// The traversal is attribute-driven ([NavigationReference(Cascade=true)]) and therefore matches the child direction the
/// direct-connection graph saver walks.
/// </para>
/// <para>
/// It is public like the other transport types, because the server implementation is generated into a separate file that
/// may be compiled into a project of its own.
/// </para>
/// </remarks>
public static class RemoteEntityGraph
{
    private static readonly ConcurrentDictionary<Type, PropertyInfo[]> _cascadeNavigations = new();
    private static readonly ConcurrentDictionary<Type, PropertyInfo?> _rowVersionProperties = new();
    private static readonly ConcurrentDictionary<Type, PropertyInfo> _keyProperties = new();

    /// <summary>Enumerates the cascade-target (child-direction) navigation properties.</summary>
    public static PropertyInfo[] CascadeNavigations(Type entityType) =>
        _cascadeNavigations.GetOrAdd(
            entityType,
            static type =>
                type.GetProperties(BindingFlags.Public | BindingFlags.Instance)
                    .Where(property =>
                        property.GetCustomAttribute<NavigationReferenceAttribute>()
                            is { Cascade: true }
                    )
                    .ToArray()
        );

    /// <summary>Gets the rowversion (concurrency token) property, or <c>null</c> when the type has no such column.</summary>
    public static PropertyInfo? RowVersionProperty(Type entityType) =>
        _rowVersionProperties.GetOrAdd(
            entityType,
            static type =>
                type.GetProperties(BindingFlags.Public | BindingFlags.Instance)
                    .FirstOrDefault(property =>
                        property.GetCustomAttribute<StoreGeneratedColumnAttribute>() is not null
                    )
        );

    /// <summary>Reads the row version the entity currently carries (<c>null</c> when the type has no rowversion column or the value is unset).</summary>
    public static byte[]? ReadRowVersion(EntityBase entity) =>
        RowVersionProperty(entity.GetType())?.GetValue(entity) as byte[];

    /// <summary>Writes a row version back to the entity (a no-op for a type without a rowversion column).</summary>
    public static void WriteRowVersion(EntityBase entity, byte[] rowVersion) =>
        RowVersionProperty(entity.GetType())?.SetValue(entity, rowVersion);

    /// <summary>Serializes the entity's primary key the way the row version table identifies it.</summary>
    public static string KeyText(EntityBase entity) =>
        JsonSerializer.Serialize(
            KeyProperty(entity.GetType()).GetValue(entity),
            RemoteJson.Options
        );

    /// <summary>Collects the row versions a save assigned across the graph (server side; deleted entities are skipped because there is no row left to version).</summary>
    public static void CollectRowVersions(
        EntityBase entity,
        bool cascade,
        List<RemoteRowVersionEntry> into
    )
    {
        if (entity.IsRemoved)
        {
            return;
        }

        if (ReadRowVersion(entity) is byte[] rowVersion)
        {
            into.Add(
                new RemoteRowVersionEntry(entity.GetType().Name, KeyText(entity), rowVersion)
            );
        }

        if (!cascade)
        {
            return;
        }

        foreach (var property in CascadeNavigations(entity.GetType()))
        {
            var value = property.GetValue(entity);

            if (value is EntityBase child)
            {
                CollectRowVersions(child, true, into);
            }
            else if (value is IEnumerable<EntityBase> children)
            {
                foreach (var item in children)
                {
                    if (item is not null)
                    {
                        CollectRowVersions(item, true, into);
                    }
                }
            }
        }
    }

    /// <summary>Collects the rows a completed save left unsaved because a hook's Before declined them (server side; deleted entities are skipped because the client leaves them untouched either way).</summary>
    /// <remarks>
    /// A completed save has finalized every row it operated on to Unchanged and left the skipped ones as they were, so a row
    /// that still carries changes is exactly a row the hook skipped. The traversal matches <see cref="CollectRowVersions"/>.
    /// </remarks>
    public static void CollectSkipped(EntityBase entity, bool cascade, List<RemoteEntityRef> into)
    {
        if (entity.IsRemoved)
        {
            return;
        }

        if (entity.HasChanges)
        {
            into.Add(new RemoteEntityRef(entity.GetType().Name, KeyText(entity)));
        }

        if (!cascade)
        {
            return;
        }

        foreach (var property in CascadeNavigations(entity.GetType()))
        {
            var value = property.GetValue(entity);

            if (value is EntityBase child)
            {
                CollectSkipped(child, true, into);
            }
            else if (value is IEnumerable<EntityBase> children)
            {
                foreach (var item in children)
                {
                    if (item is not null)
                    {
                        CollectSkipped(item, true, into);
                    }
                }
            }
        }
    }

    /// <summary>Indexes the skipped rows a save response carried, or returns <c>null</c> when nothing was skipped.</summary>
    public static HashSet<(string EntityType, string Key)>? SkippedLookup(
        List<RemoteEntityRef>? entries
    )
    {
        if (entries is null || entries.Count == 0)
        {
            return null;
        }

        var lookup = new HashSet<(string EntityType, string Key)>();

        foreach (var entry in entries)
        {
            lookup.Add((entry.EntityType, entry.Key));
        }

        return lookup;
    }

    /// <summary>Determines whether the response named this entity as skipped by a save hook (client side).</summary>
    public static bool IsSkipped(
        EntityBase entity,
        HashSet<(string EntityType, string Key)>? lookup
    ) => lookup is not null && lookup.Contains((entity.GetType().Name, KeyText(entity)));

    /// <summary>Indexes the row versions a save response carried, or returns <c>null</c> when there is nothing to write back.</summary>
    public static Dictionary<(string EntityType, string Key), byte[]>? RowVersionLookup(
        List<RemoteRowVersionEntry>? entries
    )
    {
        if (entries is null || entries.Count == 0)
        {
            return null;
        }

        var lookup = new Dictionary<(string EntityType, string Key), byte[]>();

        foreach (var entry in entries)
        {
            lookup[(entry.EntityType, entry.Key)] = entry.RowVersion;
        }

        return lookup;
    }

    /// <summary>Writes back the row version the response carried for this entity, if any (client side).</summary>
    public static void ApplyRowVersion(
        EntityBase entity,
        Dictionary<(string EntityType, string Key), byte[]>? lookup
    )
    {
        if (lookup is null || RowVersionProperty(entity.GetType()) is null)
        {
            return;
        }

        if (lookup.TryGetValue((entity.GetType().Name, KeyText(entity)), out var rowVersion))
        {
            WriteRowVersion(entity, rowVersion);
        }
    }

    /// <summary>Gets the primary key property ([Key]) of the entity type.</summary>
    private static PropertyInfo KeyProperty(Type entityType) =>
        _keyProperties.GetOrAdd(
            entityType,
            static type =>
                type.GetProperties(BindingFlags.Public | BindingFlags.Instance)
                    .FirstOrDefault(property =>
                        property.GetCustomAttribute<KeyAttribute>() is not null
                    )
                ?? throw new InvalidOperationException(
                    $"{type.Name} requires a property with a [Key] attribute."
                )
        );
}

/// <summary>
/// Common base class for client implementations that call the remote surface (<see cref="IRemoteRepository{TEntity, TKey}"/>) over HTTP + JSON.
/// </summary>
/// <remarks>
/// <para>
/// Each operation sends a JSON body to <c>POST {BaseAddress}{entity route}/{operation name}</c> and deserializes the result JSON.
/// <see cref="HttpClient.BaseAddress"/> must include the server-side <c>MapGeneratedRemoteEndpoints</c> prefix (default <c>/quicker</c>)
/// and end with a trailing <c>/</c> (for example <c>https://server:5001/quicker/</c>). Authentication, TLS, and similar concerns are
/// delegated to the HttpClient configuration (DelegatingHandler, default headers).
/// </para>
/// <para>
/// After a successful graph save (Save), the local entities' RowState is finalized with the same semantics as a direct
/// connection (<c>EntityGraphSaver.AcceptChanges</c>), so swapping direct and remote implementations does not change
/// the post-save state transitions. A row whose save a server-side hook declined (<c>ISaveHook</c>'s Before returning
/// <c>false</c>) travels back in the response and keeps its state, so it is still pending on the next save just as it
/// would be on a direct connection.
/// </para>
/// <para>
/// The concurrency policy (<see cref="ConcurrencyMode"/>) travels with the request, and Update / Save responses carry the
/// row versions the save assigned, which are written back to the local entities. A remote client therefore ends up holding
/// the same versions a direct connection would leave behind, and can keep saving the same graph without re-reading it.
/// </para>
/// </remarks>
public abstract partial class HttpRemoteRepository<TEntity, TKey> : IRemoteRepository<TEntity, TKey>
    where TEntity : EntityBase, new()
{
    private readonly HttpClient _httpClient;
    private readonly string _entityRoute;

    /// <summary>Initializes a new instance with the HTTP client and the entity route (for example "Order").</summary>
    protected HttpRemoteRepository(HttpClient httpClient, string entityRoute)
    {
        ArgumentNullException.ThrowIfNull(httpClient);
        ArgumentException.ThrowIfNullOrWhiteSpace(entityRoute);
        _httpClient = httpClient;
        _entityRoute = entityRoute;
    }

    /// <summary>Asks the server whether it is up (<c>GET {prefix}/health</c>), returning <c>false</c> instead of throwing when it is not.</summary>
    /// <remarks>
    /// <para>
    /// A liveness check, not a health check: a 200 means the process is listening and the endpoints are mapped. It says
    /// nothing about the database behind them.
    /// </para>
    /// <para>
    /// Every way of "not reachable" - connection refused, DNS failure, TLS failure, the HttpClient's own timeout, or any
    /// status other than success - comes back as <c>false</c>, which is what makes this usable as the condition of a
    /// wait-for-startup loop. Cancelling <paramref name="cancellationToken"/> is not one of those ways: it still throws
    /// <see cref="OperationCanceledException"/>, so a caller's own timeout stays distinguishable from a server that is down.
    /// </para>
    /// <para>
    /// The endpoint lives on the group, so authorization applied to the group
    /// (<c>MapGeneratedRemoteEndpoints().RequireAuthorization()</c>) covers it too, and an unauthenticated client then
    /// reads a protected server as <c>false</c>.
    /// </para>
    /// </remarks>
    /// <param name="cancellationToken">A token that cancels the check.</param>
    /// <returns><c>true</c> when the server answered with a success status; otherwise <c>false</c>.</returns>
    public async Task<bool> PingAsync(CancellationToken cancellationToken = default)
    {
        try
        {
            using var response = await _httpClient.GetAsync(
                RemotePaths.HealthRoute,
                HttpCompletionOption.ResponseHeadersRead,
                cancellationToken
            ).ConfigureAwait(false);

            return response.IsSuccessStatusCode;
        }
        catch (HttpRequestException)
        {
            // The server is not listening yet (or not reachable at all): that is the answer, not a failure
            return false;
        }
        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
        {
            // The HttpClient's own timeout elapsed. The caller did not cancel, so this is still "not ready"
            return false;
        }
    }

    /// <summary>Posts an operation and deserializes the result JSON into <typeparamref name="TResult"/> (the shared path for generated transport methods).</summary>
    /// <remarks>On a failure response, reads the <see cref="RemoteError"/>; 409 with SaveConflict throws <see cref="SaveConflictException"/>, anything else throws <see cref="RemoteRepositoryException"/>.</remarks>
    protected async Task<TResult> InvokeAsync<TResult>(
        string operation,
        object? payload,
        CancellationToken cancellationToken
    )
    {
        using var response = await _httpClient.PostAsJsonAsync(
            $"{_entityRoute}/{operation}",
            payload,
            RemoteJson.Options,
            cancellationToken
        ).ConfigureAwait(false);

        await EnsureSuccessAsync(response, cancellationToken).ConfigureAwait(false);

        var result = await response.Content.ReadFromJsonAsync<TResult>(
            RemoteJson.Options,
            cancellationToken
        ).ConfigureAwait(false);
        return result!;
    }

    /// <summary>Converts a failure response into an exception (known kinds restore the original exception type).</summary>
    private static async Task EnsureSuccessAsync(
        HttpResponseMessage response,
        CancellationToken cancellationToken
    )
    {
        if (response.IsSuccessStatusCode)
        {
            return;
        }

        RemoteError? error = null;

        try
        {
            error = await response.Content.ReadFromJsonAsync<RemoteError>(
                RemoteJson.Options,
                cancellationToken
            ).ConfigureAwait(false);
        }
        catch (Exception parseError) when (parseError is JsonException or NotSupportedException)
        {
            // If the error payload is not JSON, report the status only. Malformed JSON surfaces as JsonException, while a
            // non-JSON content type (text/html or text/plain from a proxy or a developer exception page, or no
            // Content-Type at all on an empty body) surfaces as NotSupportedException from ReadFromJsonAsync
        }

        var statusCode = (int)response.StatusCode;
        var message =
            error?.Message ?? $"The remote call failed (HTTP {statusCode}).";

        if (statusCode == 409 && error?.Type == "SaveConflict")
        {
            // Restore the conflict details the server reported so that a reload-and-retry loop reads the same properties as
            // with a direct call. A body without them (an older server) degrades to Unknown rather than failing
            throw new SaveConflictException(
                message,
                Enum.TryParse(error.Reason, out SaveConflictReason reason)
                    ? reason
                    : SaveConflictReason.Unknown,
                error.EntityType,
                error.Key
            );
        }

        throw new RemoteRepositoryException(statusCode, message);
    }

    /// <summary>Gets a single entity by primary key (null when not found).</summary>
    public Task<TEntity?> GetByIdAsync(TKey id, CancellationToken cancellationToken = default) =>
        InvokeAsync<TEntity?>("GetById", new RemoteIdRequest<TKey>(id), cancellationToken);

    /// <summary>Gets all entities.</summary>
    public Task<IReadOnlyList<TEntity>> GetAllAsync(CancellationToken cancellationToken = default) =>
        InvokeAsync<IReadOnlyList<TEntity>>("GetAll", null, cancellationToken);

    /// <summary>Inserts an entity.</summary>
    /// <remarks>As on a direct connection, the row version the database assigned is written back to <paramref name="entity"/> when the table carries a rowversion column, so the inserted entity can be updated straight away without re-reading it.</remarks>
    public async Task InsertAsync(TEntity entity, CancellationToken cancellationToken = default)
    {
        var result = await InvokeAsync<RemoteInsertResult>(
            "Insert",
            new RemoteEntityRequest<TEntity>(entity),
            cancellationToken
        ).ConfigureAwait(false);

        if (result.RowVersion is byte[] rowVersion)
        {
            RemoteEntityGraph.WriteRowVersion(entity, rowVersion);
        }
    }

    /// <summary>Updates an entity (returns true when a matching row was updated).</summary>
    /// <remarks>The policy travels with the request, so a table with a rowversion column behaves exactly as it does on a direct connection: an optimistic conflict surfaces as <see cref="SaveConflictException"/> (HTTP 409) and a successful update writes the new version back to <paramref name="entity"/>.</remarks>
    /// <param name="entity">The entity to update.</param>
    /// <param name="mode">The concurrency policy applied on the server for tables that have a rowversion column (no effect otherwise). An undefined value throws <see cref="ArgumentOutOfRangeException"/> before anything is sent.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public async Task<bool> UpdateAsync(
        TEntity entity,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        mode = ConcurrencyModes.Validated(mode);

        // Reject updates that still carry values in unbounded binary columns before sending
        // (they are excluded from the server-side UPDATE and would be lost silently)
        UnboundedBinaryColumns.ThrowIfExcludedAssigned(entity);

        var result = await InvokeAsync<RemoteUpdateResult>(
            "Update",
            new RemoteUpdateRequest<TEntity>(entity, mode),
            cancellationToken
        ).ConfigureAwait(false);

        if (result.RowVersion is byte[] rowVersion)
        {
            RemoteEntityGraph.WriteRowVersion(entity, rowVersion);
        }

        return result.Updated;
    }

    /// <summary>Deletes an entity by primary key (returns true when a matching row was deleted).</summary>
    public Task<bool> DeleteAsync(TKey id, CancellationToken cancellationToken = default) =>
        InvokeAsync<bool>("Delete", new RemoteIdRequest<TKey>(id), cancellationToken);

    /// <summary>Saves inserts, updates, and deletes according to RowState in a single transaction (cascades to children by default).</summary>
    /// <remarks><paramref name="mode"/> travels with the request, and the response carries the row versions the save assigned so that the local graph ends up with the same versions a direct connection would leave behind.</remarks>
    public async Task<int> SaveAsync(
        TEntity entity,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        mode = ConcurrencyModes.Validated(mode);

        // Reject before sending if any entity to update (RowState==Updated) still carries values
        // in unbounded binary columns (cascade targets are traversed as well)
        GuardUnboundedBinaryOnSave(entity, cascadeSave);

        var result = await InvokeAsync<RemoteSaveResult>(
            "Save",
            new RemoteSaveRequest<TEntity>(entity, cascadeSave, cascadeDelete, insertWhenUpdateMissing, mode),
            cancellationToken
        ).ConfigureAwait(false);

        // As with a direct connection (EntityGraphSaver), finalize the local RowState after a successful save,
        // writing back the row versions the response carried and leaving the rows it reported as skipped alone
        AcceptChanges(
            entity,
            cascadeSave,
            RemoteEntityGraph.RowVersionLookup(result.RowVersions),
            RemoteEntityGraph.SkippedLookup(result.Skipped)
        );
        return result.Affected;
    }

    /// <summary>Saves multiple aggregate roots together in a single transaction (atomic: all succeed or all roll back).</summary>
    /// <remarks><paramref name="mode"/> travels with the request, and the response carries the row versions the save assigned so that the local graphs end up with the same versions a direct connection would leave behind.</remarks>
    public async Task<int> SaveAsync(
        IEnumerable<TEntity> entities,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        mode = ConcurrencyModes.Validated(mode);

        var list = entities.ToList();

        // Reject before sending if any updated entity in each aggregate root (including cascade targets)
        // still carries values in unbounded binary columns
        foreach (var entity in list)
        {
            GuardUnboundedBinaryOnSave(entity, cascadeSave);
        }

        var result = await InvokeAsync<RemoteSaveResult>(
            "SaveMany",
            new RemoteSaveManyRequest<TEntity>(list, cascadeSave, cascadeDelete, insertWhenUpdateMissing, mode),
            cancellationToken
        ).ConfigureAwait(false);

        var rowVersions = RemoteEntityGraph.RowVersionLookup(result.RowVersions);
        var skipped = RemoteEntityGraph.SkippedLookup(result.Skipped);

        foreach (var entity in list)
        {
            AcceptChanges(entity, cascadeSave, rowVersions, skipped);
        }

        return result.Affected;
    }

    /// <summary>Verifies that no updated (Updated) entity in the graph to save still carries values in unbounded binary columns (same child-direction traversal as AcceptChanges).</summary>
    private static void GuardUnboundedBinaryOnSave(EntityBase entity, bool cascade)
    {
        if (entity.IsUpdated)
        {
            UnboundedBinaryColumns.ThrowIfExcludedAssigned(entity);
        }

        if (!cascade)
        {
            return;
        }

        foreach (var property in RemoteEntityGraph.CascadeNavigations(entity.GetType()))
        {
            var value = property.GetValue(entity);

            if (value is EntityBase child)
            {
                GuardUnboundedBinaryOnSave(child, true);
            }
            else if (value is IEnumerable<EntityBase> children)
            {
                foreach (var item in children)
                {
                    if (item is not null)
                    {
                        GuardUnboundedBinaryOnSave(item, true);
                    }
                }
            }
        }
    }

    /// <summary>Finalizes saved entities to Unchanged after commit (same semantics as the direct-connection EntityGraphSaver.AcceptChanges), writing back the row versions the response carried.</summary>
    /// <remarks>
    /// Deleted (Removed) entities keep their state. Rows the response reported as skipped - a save hook's Before declined
    /// them on the server, so no INSERT or UPDATE was performed - keep their state as well, exactly as they do on a direct
    /// connection. When cascading, the child-direction [NavigationReference] navigations are finalized recursively. Both the
    /// row version write-back and the skip check ride along this traversal because it visits exactly the entities the server
    /// reported on.
    /// </remarks>
    private static void AcceptChanges(
        EntityBase entity,
        bool cascade,
        Dictionary<(string EntityType, string Key), byte[]>? rowVersions,
        HashSet<(string EntityType, string Key)>? skipped
    )
    {
        if (entity.IsRemoved)
        {
            return;
        }

        // A skipped row had no INSERT / UPDATE performed on the server, so its RowState is left untouched
        if (!RemoteEntityGraph.IsSkipped(entity, skipped))
        {
            entity.MarkUnchanged();
        }

        RemoteEntityGraph.ApplyRowVersion(entity, rowVersions);

        if (!cascade)
        {
            return;
        }

        foreach (var property in RemoteEntityGraph.CascadeNavigations(entity.GetType()))
        {
            var value = property.GetValue(entity);

            if (value is EntityBase child)
            {
                AcceptChanges(child, true, rowVersions, skipped);
            }
            else if (value is IEnumerable<EntityBase> children)
            {
                foreach (var item in children)
                {
                    if (item is not null)
                    {
                        AcceptChanges(item, true, rowVersions, skipped);
                    }
                }
            }
        }
    }

    /// <summary>Serializes the primary key into a string for the URL query (<c>?id=</c>) using the same JSON rules as the envelopes (value objects use their wrapped value, numbers as-is, strings/Guids quoted).</summary>
    /// <remarks>Carries the URL-encoded JSON representation of the key value. The server restores it with the same settings (<c>RemoteJson.Options</c>), so it round-trips regardless of dialect or value objects.</remarks>
    protected string FormatKeyForQuery(TKey id) =>
        Uri.EscapeDataString(JsonSerializer.Serialize(id, RemoteJson.Options));

    /// <summary>
    /// Streams an unbounded binary column (excluded column) down from the server (<c>GET {entity}/{column}?id=</c>).
    /// Reads only the response headers up front (<see cref="HttpCompletionOption.ResponseHeadersRead"/>) and copies the body
    /// to the destination in O(chunk) (the whole blob is never loaded into memory; no Base64). 200 = data was written
    /// (<c>true</c>; an empty blob is also true) / 404 = no row or NULL (<c>false</c>; nothing is written to the destination).
    /// Any other failure restores exceptions per the existing rules.
    /// </summary>
    protected async Task<bool> DownloadUnboundedBinaryColumnAsync(
        string columnRoute,
        TKey id,
        Stream destination,
        CancellationToken cancellationToken
    )
    {
        ArgumentNullException.ThrowIfNull(destination);

        var requestUri = $"{_entityRoute}/{columnRoute}?id={FormatKeyForQuery(id)}";
        using var response = await _httpClient.GetAsync(
            requestUri,
            HttpCompletionOption.ResponseHeadersRead,
            cancellationToken
        ).ConfigureAwait(false);

        if (response.StatusCode == HttpStatusCode.NotFound)
        {
            return false;
        }

        await EnsureSuccessAsync(response, cancellationToken).ConfigureAwait(false);

        await using var source = await response.Content.ReadAsStreamAsync(cancellationToken).ConfigureAwait(false);
        await source.CopyToAsync(destination, cancellationToken).ConfigureAwait(false);
        return true;
    }

    /// <summary>
    /// Streams an unbounded binary column (excluded column) up to the server. When <paramref name="source"/> is <c>null</c>,
    /// sends <c>DELETE</c> (sets the column to NULL); when non-<c>null</c>, sends <c>PUT</c> (<see cref="StreamContent"/> with
    /// Content-Length). A zero-byte PUT (empty body) and setting NULL (DELETE) are structurally distinct. The length contract
    /// is validated before sending (a non-<c>CanSeek</c> Stream requires <paramref name="length"/>). 204 = success (<c>true</c>) /
    /// 404 = no row (<c>false</c>). Anything else restores exceptions.
    /// </summary>
    protected async Task<bool> UploadUnboundedBinaryColumnAsync(
        string columnRoute,
        TKey id,
        Stream? source,
        long? length,
        CancellationToken cancellationToken
    )
    {
        var requestUri = $"{_entityRoute}/{columnRoute}?id={FormatKeyForQuery(id)}";

        // source=null sets the column to NULL (DELETE); this differs in meaning from a zero-byte PUT (empty body)
        if (source is null)
        {
            using var deleteResponse = await _httpClient.DeleteAsync(requestUri, cancellationToken).ConfigureAwait(false);

            if (deleteResponse.StatusCode == HttpStatusCode.NotFound)
            {
                return false;
            }

            await EnsureSuccessAsync(deleteResponse, cancellationToken).ConfigureAwait(false);
            return true;
        }

        // Determine the length before sending (a non-CanSeek Stream requires length, which naturally
        // aligns with Content-Length; a missing length throws before sending)
        var payloadLength = UnboundedBinaryColumns.ResolveWriteLength(source, length);

        using var content = new StreamContent(source);
        content.Headers.ContentLength = payloadLength;
        content.Headers.ContentType = new MediaTypeHeaderValue("application/octet-stream");

        using var request = new HttpRequestMessage(HttpMethod.Put, requestUri) { Content = content };
        using var response = await _httpClient.SendAsync(
            request,
            HttpCompletionOption.ResponseHeadersRead,
            cancellationToken
        ).ConfigureAwait(false);

        if (response.StatusCode == HttpStatusCode.NotFound)
        {
            return false;
        }

        await EnsureSuccessAsync(response, cancellationToken).ConfigureAwait(false);
        return true;
    }
}

/// <summary>Metadata built from the entity type's attributes that holds table/column information, CRUD SQL, and cascade child navigations, and provides row mapping and parameter binding.</summary>
/// <remarks>Built once per type and cached by type key (reduces reflection cost). Shared by the repository's CRUD, graph save, JSON query planner, and cascade delete planner.</remarks>
internal sealed class EntitySaveMetadata
{
    private static readonly ConcurrentDictionary<Type, EntitySaveMetadata> _cache = new();

    /// <summary>Gets the entity type this metadata describes (used to instantiate entities for multi-query Include).</summary>
    public required Type EntityType { get; init; }

    /// <summary>Gets the table name wrapped in quoting brackets.</summary>
    public required string TableName { get; init; }

    /// <summary>Gets the raw, unquoted table name (required by SqliteBlob and friends in the unbounded binary column Stream accessors).</summary>
    public required string RawTableName { get; init; }

    /// <summary>Gets the property that corresponds to the primary key.</summary>
    public required PropertyInfo KeyProperty { get; init; }

    /// <summary>Gets the column name of the primary key.</summary>
    public required string KeyColumnName { get; init; }

    /// <summary>Gets all column properties subject to mapping (excluding navigations and base-class properties). INSERT / BulkInsert always use this.</summary>
    public required IReadOnlyList<PropertyInfo> AllProperties { get; init; }

    /// <summary>Gets the column properties targeted by SELECT / UPDATE (all columns minus unbounded binary columns; identical to all columns when there are no excluded columns). Used by row mapping.</summary>
    public required IReadOnlyList<PropertyInfo> SelectProperties { get; init; }

    /// <summary>Gets the unbounded binary columns excluded from SELECT / UPDATE (marked with <see cref="UnboundedBinaryColumnAttribute"/>). Empty when there are no excluded columns.</summary>
    public required IReadOnlyList<PropertyInfo> ExcludedProperties { get; init; }

    /// <summary>Gets the rowversion (concurrency token) property, or <c>null</c> when the table has no such column.</summary>
    /// <remarks>Resolved from <see cref="StoreGeneratedColumnAttribute"/>. A table carries at most one rowversion column, so the first match is used.</remarks>
    public PropertyInfo? RowVersionProperty { get; init; }

    /// <summary>Gets the (property, column name) pairs of the SELECT columns, resolved at build time. Row mapping enumerates this instead of reflecting for column names per row.</summary>
    public required IReadOnlyList<(PropertyInfo Property, string ColumnName)> SelectColumns { get; init; }

    /// <summary>Gets the pre-resolved column property to column name map (used to resolve column names for arbitrary property sets such as projections and excluded columns).</summary>
    public required IReadOnlyDictionary<PropertyInfo, string> ColumnNameByProperty { get; init; }

    /// <summary>Gets the column properties targeted by INSERT / BulkInsert (all columns minus store-generated columns; identical to all columns when there are no store-generated columns).</summary>
    public required IReadOnlyList<PropertyInfo> InsertProperties { get; init; }

    /// <summary>Gets the column properties excluding the primary key.</summary>
    public required IReadOnlyList<PropertyInfo> NonKeyProperties { get; init; }

    /// <summary>Gets the (property name, column name) pairs of the columns. Used for aliasing in JSON projections ([col] AS Prop).</summary>
    public required IReadOnlyList<(string PropertyName, string ColumnName)> Columns { get; init; }

    /// <summary>Gets the column name to column property map (used to look up column types when explicitly typing query WHERE-clause parameters).</summary>
    public required IReadOnlyDictionary<string, PropertyInfo> PropertyByColumn { get; init; }

    /// <summary>Gets the quoted column list for SELECT (for example: [id], [name]).</summary>
    public required string ColumnList { get; init; }

    /// <summary>Gets the SELECT statement that fetches all rows.</summary>
    public required string SelectAllSql { get; init; }

    /// <summary>Gets the SELECT statement that fetches a row by primary key.</summary>
    public required string SelectByIdSql { get; init; }

    /// <summary>Gets the INSERT statement.</summary>
    public required string InsertSql { get; init; }

    /// <summary>Gets the UPDATE statement.</summary>
    public required string UpdateSql { get; init; }

    /// <summary>Gets the DELETE statement.</summary>
    public required string DeleteSql { get; init; }

    /// <summary>Gets the cascade-target child navigations.</summary>
    public required IReadOnlyList<CascadeNavigation> CascadeNavigations { get; init; }

    /// <summary>Gets the metadata for the specified type (built once per type and cached).</summary>
    public static EntitySaveMetadata For(Type entityType) => _cache.GetOrAdd(entityType, Build);

    /// <summary>Caches the navigation property to <see cref="NavigationReferenceAttribute"/> resolution per property.</summary>
    private static readonly ConcurrentDictionary<
        PropertyInfo,
        NavigationReferenceAttribute?
    > _navigationAttributeCache = new();

    /// <summary>Gets the <see cref="NavigationReferenceAttribute"/> of a navigation property (cached so Include resolution does not reflect per node).</summary>
    public static NavigationReferenceAttribute? NavigationAttribute(PropertyInfo property) =>
        _navigationAttributeCache.GetOrAdd(
            property,
            static p => p.GetCustomAttribute<NavigationReferenceAttribute>()
        );

    private static EntitySaveMetadata Build(Type entityType)
    {
        var tableAttribute =
            entityType.GetCustomAttribute<TableAttribute>()
            ?? throw new InvalidOperationException(
                $"{entityType.Name} requires a [Table] attribute."
            );
        var allProperties = entityType
            .GetProperties(BindingFlags.Public | BindingFlags.Instance)
            .ToList();
        var columns = allProperties
            .Where(property =>
                property.CanRead
                && property.CanWrite
                && property.DeclaringType != typeof(EntityBase)
                && property.GetCustomAttribute<NavigationReferenceAttribute>() is null
            )
            .ToList();
        var keyProperties = columns
            .Where(property => property.GetCustomAttribute<KeyAttribute>() is not null)
            .ToList();
        var keyProperty = keyProperties.Count switch
        {
            0 => throw new InvalidOperationException(
                $"{entityType.Name} requires a property with a [Key] attribute."
            ),
            1 => keyProperties[0],
            _ => throw new InvalidOperationException(
                $"{entityType.Name} may have only one property with a [Key] attribute (composite keys are not supported by the repository; found: {string.Join(", ", keyProperties.Select(property => property.Name))})."
            ),
        };
        // Exclude unbounded binary columns (UnboundedBinaryColumnAttribute) from SELECT / UPDATE. The full column set
        // (AllProperties) is kept for INSERT / BulkInsert; only the SELECT column set (selectProperties) is reduced.
        // With no excluded columns it matches the full set
        var excludedColumns = columns
            .Where(property =>
                property.GetCustomAttribute<UnboundedBinaryColumnAttribute>() is not null
            )
            .ToList();
        var selectProperties =
            excludedColumns.Count == 0
                ? columns
                : columns.Where(property => !excludedColumns.Contains(property)).ToList();
        // Columns whose values are generated by the database (rowversion / timestamp etc., StoreGeneratedColumnAttribute)
        // are excluded from INSERT / UPDATE. The database assigns them, so an explicit write fails at runtime
        // (e.g. SQL Server timestamp columns). They are still fetched by SELECT
        var storeGeneratedColumns = columns
            .Where(property =>
                property.GetCustomAttribute<StoreGeneratedColumnAttribute>() is not null
            )
            .ToList();
        // A store-generated column doubles as the table's concurrency token; a table carries at most one of them
        var rowVersionProperty =
            storeGeneratedColumns.Count == 0 ? null : storeGeneratedColumns[0];
        // INSERT / BulkInsert targets are all columns minus store-generated columns (identical to all columns when there are none)
        var insertProperties =
            storeGeneratedColumns.Count == 0
                ? columns
                : columns.Where(property => !storeGeneratedColumns.Contains(property)).ToList();
        var nonKeyProperties = selectProperties
            .Where(property =>
                property != keyProperty && !storeGeneratedColumns.Contains(property)
            )
            .ToList();
        var tableName = $"\"{tableAttribute.Name}\"";
        var keyColumnName = GetColumnName(keyProperty);
        var columnList = string.Join(", ", selectProperties.Select(property => $"\"{GetColumnName(property)}\""));
        var updateAssignments = nonKeyProperties.Select(property =>
            $"\"{GetColumnName(property)}\" = @{property.Name}"
        );
        var insertColumnList = string.Join(", ", insertProperties.Select(property => $"\"{GetColumnName(property)}\""));
        var insertValueList = string.Join(", ", insertProperties.Select(property => $"@{property.Name}"));
        var cascades = allProperties
            .Select(property =>
                (property, attribute: property.GetCustomAttribute<NavigationReferenceAttribute>())
            )
            .Where(pair => pair.attribute is { Cascade: true })
            .Select(pair => new CascadeNavigation(
                pair.property,
                pair.attribute!.IsCollection,
                pair.attribute.IsCollection
                    ? pair.property.PropertyType.GetGenericArguments()[0]
                    : pair.property.PropertyType,
                pair.attribute.PrincipalColumn,
                pair.attribute.DependentColumn
            ))
            .ToList();

        return new EntitySaveMetadata
        {
            EntityType = entityType,
            TableName = tableName,
            RawTableName = tableAttribute.Name,
            KeyProperty = keyProperty,
            KeyColumnName = keyColumnName,
            AllProperties = columns,
            SelectProperties = selectProperties,
            ExcludedProperties = excludedColumns,
            RowVersionProperty = rowVersionProperty,
            // Resolve column names for row mapping at build time to eliminate per-row [Column] reflection
            SelectColumns = selectProperties.Select(property => (property, GetColumnName(property))).ToList(),
            ColumnNameByProperty = columns.ToDictionary(property => property, GetColumnName),
            // Compile the expression-tree materializer for SelectColumns (the fixed SELECT set) once per type
            SelectMaterializer = BuildSelectMaterializer(entityType, selectProperties),
            InsertProperties = insertProperties,
            NonKeyProperties = nonKeyProperties,
            Columns = selectProperties.Select(property => (property.Name, GetColumnName(property))).ToList(),
            PropertyByColumn = columns.ToDictionary(
                GetColumnName,
                property => property,
                StringComparer.Ordinal
            ),
            ColumnList = columnList,
            SelectAllSql = $"SELECT {columnList} FROM {tableName};",
            SelectByIdSql = $"SELECT {columnList} FROM {tableName} WHERE \"{keyColumnName}\" = @id;",
            InsertSql =
                $"INSERT INTO {tableName} ({insertColumnList}) VALUES ({insertValueList});",
            UpdateSql =
                $"UPDATE {tableName} SET {string.Join(", ", updateAssignments)} WHERE \"{keyColumnName}\" = @id;",
            DeleteSql = $"DELETE FROM {tableName} WHERE \"{keyColumnName}\" = @id;",
            CascadeNavigations = cascades,
        };
    }

    // ===== Row materializer (expression-tree compiled; removes reflection from the hot path) =====
    /// <summary>Type-specialized reader accessors that avoid boxing (<c>GetInt32</c> etc.). Only the fast-path CLR types are registered.</summary>
    private static readonly IReadOnlyDictionary<Type, MethodInfo> _typedReaders = BuildTypedReaders();

    /// <summary>Resolved <see cref="MethodInfo"/> of <see cref="DbDataReader.IsDBNull(int)"/>.</summary>
    private static readonly MethodInfo _isDbNullMethod = typeof(DbDataReader).GetMethod(
        nameof(DbDataReader.IsDBNull),
        new[] { typeof(int) }
    )!;

    /// <summary>Resolved <see cref="MethodInfo"/> of <see cref="DbDataReader.GetValue(int)"/> (used as the fallback for columns that cannot be type-specialized).</summary>
    private static readonly MethodInfo _getValueMethod = typeof(DbDataReader).GetMethod(
        nameof(DbDataReader.GetValue),
        new[] { typeof(int) }
    )!;

    /// <summary>Resolved <see cref="MethodInfo"/> of <see cref="SetColumnValue"/> (called as the fallback for columns that cannot be type-specialized).</summary>
    private static readonly MethodInfo _setColumnValueMethod = typeof(EntitySaveMetadata).GetMethod(
        nameof(SetColumnValue),
        BindingFlags.NonPublic | BindingFlags.Static
    )!;

    /// <summary>Resolved <see cref="PropertyInfo"/> of <see cref="EntityBase.RowState"/>.</summary>
    private static readonly PropertyInfo _rowStateProperty = typeof(EntityBase).GetProperty(
        nameof(EntityBase.RowState)
    )!;

    /// <summary>Gets the expression-tree-compiled delegate that materializes one row of SelectColumns (the fixed SELECT set) (built once per type and cached).</summary>
    /// <remarks>The arguments are <c>(reader, ordinals)</c>. <c>ordinals</c> holds the column ordinals in SelectColumns order, resolved once before the row loop.</remarks>
    public required Func<DbDataReader, int[], EntityBase> SelectMaterializer { get; init; }

    /// <summary>Builds the type-specialized reader accessor table (each value is a <see cref="DbDataReader"/> method taking an <c>int</c> and returning the corresponding CLR type).</summary>
    private static IReadOnlyDictionary<Type, MethodInfo> BuildTypedReaders()
    {
        static MethodInfo Getter(string name) =>
            typeof(DbDataReader).GetMethod(name, new[] { typeof(int) })!;

        // Type-specialized accessors for the declared column types the generated SELECT returns. On SQLite each GetXxx
        // coerces the storage type (long to int, TEXT to DateTime, etc.), equivalent to CoerceScalar; on SQL Server each
        // returns the column's CLR type directly, equivalent to the previous pass-through. Types not listed here
        // (byte[], enums, DateTimeOffset, TimeSpan, etc.) are converted via the fallback as before.
        return new Dictionary<Type, MethodInfo>
        {
            [typeof(bool)] = Getter(nameof(DbDataReader.GetBoolean)),
            [typeof(byte)] = Getter(nameof(DbDataReader.GetByte)),
            [typeof(short)] = Getter(nameof(DbDataReader.GetInt16)),
            [typeof(int)] = Getter(nameof(DbDataReader.GetInt32)),
            [typeof(long)] = Getter(nameof(DbDataReader.GetInt64)),
            [typeof(float)] = Getter(nameof(DbDataReader.GetFloat)),
            [typeof(double)] = Getter(nameof(DbDataReader.GetDouble)),
            [typeof(decimal)] = Getter(nameof(DbDataReader.GetDecimal)),
            [typeof(string)] = Getter(nameof(DbDataReader.GetString)),
            [typeof(DateTime)] = Getter(nameof(DbDataReader.GetDateTime)),
            [typeof(Guid)] = Getter(nameof(DbDataReader.GetGuid)),
        };
    }

    /// <summary>
    /// Builds the expression-tree-compiled delegate that materializes one row of SelectColumns (the fixed SELECT set)
    /// into an entity using a pre-resolved ordinal array (once per type).
    /// </summary>
    /// <remarks>
    /// Columns with a type-specialized accessor are read directly without boxing (<c>DBNull</c> becomes the default value,
    /// equivalent to the previous <c>SetValue(null)</c>);
    /// all other columns fall back to the previous
    /// <see cref="SetColumnValue"/> (dialect-specific conversion / value object re-wrapping).
    /// The resulting final state (<c>RowState = Unchanged</c>) matches the previous row mapping.
    /// </remarks>
    private static Func<DbDataReader, int[], EntityBase> BuildSelectMaterializer(
        Type entityType,
        IReadOnlyList<PropertyInfo> properties
    )
    {
        var readerParam = Expression.Parameter(typeof(DbDataReader), "reader");
        var ordinalsParam = Expression.Parameter(typeof(int[]), "ordinals");
        var entityVar = Expression.Variable(entityType, "entity");

        var body = new List<Expression>
        {
            Expression.Assign(entityVar, Expression.New(entityType)),
        };

        for (var i = 0; i < properties.Count; i++)
        {
            var ordinal = Expression.ArrayIndex(ordinalsParam, Expression.Constant(i));
            body.Add(BuildColumnAssign(entityVar, readerParam, ordinal, properties[i]));
        }

        // Rows read from the database are treated as unchanged (same post-state as the previous row mapping)
        body.Add(
            Expression.Assign(
                Expression.Property(entityVar, _rowStateProperty),
                Expression.Constant(RowState.Unchanged)
            )
        );
        body.Add(Expression.Convert(entityVar, typeof(EntityBase)));

        var block = Expression.Block(typeof(EntityBase), new[] { entityVar }, body);
        return Expression
            .Lambda<Func<DbDataReader, int[], EntityBase>>(block, readerParam, ordinalsParam)
            .Compile();
    }

    /// <summary>Builds the assignment expression for one column. Type-specializable columns are read directly without boxing; anything else falls back to <see cref="SetColumnValue"/>.</summary>
    private static Expression BuildColumnAssign(
        Expression entityExpr,
        ParameterExpression readerParam,
        Expression ordinal,
        PropertyInfo property
    )
    {
        var propertyType = property.PropertyType;
        var underlying = Nullable.GetUnderlyingType(propertyType) ?? propertyType;

        // Columns with a type-specialized accessor are read directly without boxing
        // (DBNull becomes the default value, equivalent to the previous SetValue(null))
        if (_typedReaders.TryGetValue(underlying, out var getter))
        {
            Expression read = Expression.Call(readerParam, getter, ordinal);

            if (getter.ReturnType != propertyType)
            {
                read = Expression.Convert(read, propertyType);
            }

            var value = Expression.Condition(
                Expression.Call(readerParam, _isDbNullMethod, ordinal),
                Expression.Default(propertyType),
                read
            );
            return Expression.Assign(Expression.Property(entityExpr, property), value);
        }

        // Fallback: call the previous SetColumnValue (DBNull to null / dialect-specific conversion / value object re-wrapping) via the ordinal
        return Expression.Call(
            _setColumnValueMethod,
            Expression.Convert(entityExpr, typeof(EntityBase)),
            Expression.Constant(property, typeof(PropertyInfo)),
            Expression.Call(readerParam, _getValueMethod, ordinal)
        );
    }

    /// <summary>Resolves each SelectColumns column name to its ordinal on this reader once (call before the row loop).</summary>
    public int[] SelectOrdinals(DbDataReader reader)
    {
        var ordinals = new int[SelectColumns.Count];

        for (var i = 0; i < ordinals.Length; i++)
        {
            ordinals[i] = reader.GetOrdinal(SelectColumns[i].ColumnName);
        }

        return ordinals;
    }

    /// <summary>Maps one data reader row to an entity (pre-resolved ordinal variant, for hot loops).</summary>
    public TEntity MapEntity<TEntity>(
        DbDataReader reader,
        int[] ordinals
    )
        where TEntity : EntityBase => (TEntity)SelectMaterializer(reader, ordinals);

    /// <summary>Maps one data reader row to an entity (single-row variant that resolves the SelectColumns ordinals on each call).</summary>
    public TEntity MapEntity<TEntity>(DbDataReader reader)
        where TEntity : EntityBase, new() => (TEntity)SelectMaterializer(reader, SelectOrdinals(reader));

    /// <summary>
    /// Strict row mapping for raw SQL (the column set and column types are variable, so no type specialization;
    /// uses the previous lenient <see cref="SetColumnValue"/>).
    /// </summary>
    private TEntity MapEntityStrict<TEntity>(DbDataReader reader)
        where TEntity : EntityBase, new()
    {
        var entity = new TEntity();

        // Unbounded binary columns are excluded from SELECT by default, so only SelectColumns
        // (the pre-resolved pairs of SelectProperties) are mapped
        foreach (var (property, columnName) in SelectColumns)
        {
            SetColumnValue(entity, property, reader[columnName]);
        }

        // Rows read from the database are treated as unchanged (later edits transition them to Updated)
        entity.RowState = RowState.Unchanged;
        return entity;
    }

    /// <summary>
    /// Sets a column value read from the reader onto the target property (the shared row-mapping step). <c>DBNull</c>
    /// assigns <c>null</c>; otherwise the value is re-wrapped for value objects, coerced from the SQLite storage type,
    /// or passed through for SQL Server, depending on the dialect.
    /// </summary>
    private static void SetColumnValue(EntityBase entity, PropertyInfo property, object value)
    {
        if (value is DBNull)
        {
            property.SetValue(entity, null);
        }
        else
        {
            // Plain columns are coerced from the SQLite storage type (int stored as long, decimal/Guid/DateTime as TEXT, etc.) to the property type
            property.SetValue(entity, CoerceScalar(value, property.PropertyType));
        }
    }

    /// <summary>
    /// Maps a raw SQL result row to {TEntity}. Same strict mapping as <see cref="MapEntityStrict"/> (the SELECT columns are
    /// required), but when a column cannot be found (a partial SELECT), the error is wrapped in an
    /// <see cref="InvalidOperationException"/> that lists the required columns for clarity. The exception thrown for an
    /// unknown column reference differs by data reader implementation (<see cref="IndexOutOfRangeException"/> vs
    /// <see cref="ArgumentOutOfRangeException"/>), so both are caught.
    /// Unbounded binary columns are not fetched by default, but if the raw SQL SELECT explicitly includes them they are mapped additionally (so a user who deliberately selected them gets the values).
    /// </summary>
    public TEntity MapEntityFromRawSql<TEntity>(DbDataReader reader)
        where TEntity : EntityBase, new()
    {
        TEntity entity;

        try
        {
            entity = MapEntityStrict<TEntity>(reader);
        }
        catch (Exception ex) when (ex is IndexOutOfRangeException or ArgumentOutOfRangeException)
        {
            throw new InvalidOperationException(
                $"The raw SQL SELECT must include the {typeof(TEntity).Name} columns ({ColumnList}); use SELECT * or list all columns. "
                    + $"The result set is missing a column: {ex.Message}",
                ex
            );
        }

        // If excluded columns (unbounded binary) are present in the raw SQL result, take them opportunistically
        if (ExcludedProperties.Count > 0)
        {
            var present = RawReaderColumnNames(reader);

            foreach (var property in ExcludedProperties)
            {
                var columnName = ColumnNameByProperty[property];

                if (!present.Contains(columnName))
                {
                    continue;
                }

                SetColumnValue(entity, property, reader[columnName]);
            }

            // Re-finalize as unchanged so the opportunistic assignments do not shift state
            // (the column properties are plain auto-properties, but just in case)
            entity.RowState = RowState.Unchanged;
        }

        return entity;
    }

    /// <summary>Enumerates the data reader's column name set once, case-insensitively (used to detect excluded columns in raw SQL results).</summary>
    private static HashSet<string> RawReaderColumnNames(DbDataReader reader)
    {
        var names = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        for (var i = 0; i < reader.FieldCount; i++)
        {
            names.Add(reader.GetName(i));
        }

        return names;
    }

    /// <summary>
    /// Resolves the set of column property names referenced by a projection selector into the column properties
    /// (<see cref="PropertyInfo"/>) to SELECT. When every reference is a column property (including unbounded binary
    /// columns), returns the list in order; when even one non-column name (a navigation etc.) is present, or when there
    /// are zero references, returns <c>null</c> (= server-side column pruning is not possible; fall back to the previous path).
    /// </summary>
    public IReadOnlyList<PropertyInfo>? ResolveProjectionColumns(
        IReadOnlyCollection<string> propertyNames
    )
    {
        // With zero referenced columns there is nothing to SELECT, so a fallback is required (e.g. a constants-only projection)
        if (propertyNames.Count == 0)
        {
            return null;
        }

        var resolved = new List<PropertyInfo>(propertyNames.Count);

        foreach (var name in propertyNames)
        {
            // Look up by name in the full column set (AllProperties); excluded (unbounded binary) columns
            // are also fetched when the projection references them
            var property = AllProperties.FirstOrDefault(candidate => candidate.Name == name);

            if (property is null)
            {
                // A non-column (navigation etc.) is present = cannot prune safely
                return null;
            }

            resolved.Add(property);
        }

        return resolved;
    }

    /// <summary>Returns a SELECT column list joining the specified column properties as quoted column names with "," (for example: [id], [name]) (for projection pruning).</summary>
    public string BuildColumnList(IReadOnlyList<PropertyInfo> properties) =>
        string.Join(
            ", ",
            properties.Select(property => $"\"{GetColumnName(property)}\"")
        );

    /// <summary>Per-column-property "reader+ordinal, set onto entity" binders (expression-tree compiled, cached per property).</summary>
    private static readonly ConcurrentDictionary<
        PropertyInfo,
        Action<EntityBase, DbDataReader, int>
    > _columnBinderCache = new();

    /// <summary>Gets the type-specialized binder for one column (so the variable column sets of projections and full-column fetches bind without per-row reflection).</summary>
    private static Action<EntityBase, DbDataReader, int> ColumnBinder(PropertyInfo property) =>
        _columnBinderCache.GetOrAdd(property, BuildColumnBinder);

    /// <summary>Compiles the single-column expression tree (<see cref="BuildColumnAssign"/>) into an <c>Action&lt;EntityBase, DbDataReader, int&gt;</c>.</summary>
    private static Action<EntityBase, DbDataReader, int> BuildColumnBinder(PropertyInfo property)
    {
        var entityParam = Expression.Parameter(typeof(EntityBase), "entity");
        var readerParam = Expression.Parameter(typeof(DbDataReader), "reader");
        var ordinalParam = Expression.Parameter(typeof(int), "ordinal");

        // Properties are declared on the derived entity type, so downcast EntityBase to the declaring type before accessing
        var assign = BuildColumnAssign(
            Expression.Convert(entityParam, property.DeclaringType!),
            readerParam,
            ordinalParam,
            property
        );

        return Expression
            .Lambda<Action<EntityBase, DbDataReader, int>>(
                assign,
                entityParam,
                readerParam,
                ordinalParam
            )
            .Compile();
    }

    /// <summary>Resolves the column names of the specified column properties to their ordinals on this reader once (call before the row loop of projections and full-column fetches).</summary>
    public int[] ColumnOrdinals(DbDataReader reader, IReadOnlyList<PropertyInfo> properties)
    {
        var ordinals = new int[properties.Count];

        for (var i = 0; i < ordinals.Length; i++)
        {
            ordinals[i] = reader.GetOrdinal(ColumnNameByProperty[properties[i]]);
        }

        return ordinals;
    }

    /// <summary>
    /// Returns a {TEntity} with only the specified column properties mapped from one data reader row (shared by
    /// server-side column pruning for projections and the full-column fetch of WithUnboundedBinary).
    /// Only the columns included in the SELECT are bound; all other columns keep their default values. Projection use
    /// (<paramref name="markUnchanged"/> = false, the default) does not set RowState because the entity is discarded after
    /// the selector is applied, whereas the full-column fetch of WithUnboundedBinary (<paramref name="markUnchanged"/> = true)
    /// finalizes RowState=Unchanged because it returns a legitimate entity equivalent to a normal fetch. <paramref name="ordinals"/>
    /// holds the column ordinals in <paramref name="properties"/> order, resolved once before the row loop via <see cref="ColumnOrdinals"/>.
    /// </summary>
    public TEntity MapEntityColumns<TEntity>(
        SqliteDataReader reader,
        IReadOnlyList<PropertyInfo> properties,
        int[] ordinals,
        bool markUnchanged = false
    )
        where TEntity : EntityBase
    {
        // The query executor's TEntity has no new() constraint, so create via Activator (entities always have a parameterless constructor)
        var entity = (TEntity)Activator.CreateInstance(typeof(TEntity))!;

        for (var i = 0; i < properties.Count; i++)
        {
            ColumnBinder(properties[i])(entity, reader, ordinals[i]);
        }

        if (markUnchanged)
        {
            // When returning a "legitimate entity" with all columns bound, finalize it as unchanged, like any row read from the database
            entity.RowState = RowState.Unchanged;
        }

        return entity;
    }

    /// <summary>Maps one data reader row to an entity (without a type argument) (pre-resolved ordinal variant). Used to materialize entities for multi-query Include.</summary>
    /// <remarks>
    /// Same column-to-property binding as <c>MapEntity</c>, but created without a generic constraint because the Include
    /// loader works with runtime <see cref="Type"/> values. <paramref name="ordinals"/> is resolved once before the row loop via <see cref="SelectOrdinals"/>.
    /// </remarks>
    // Without value objects, plain columns are bound by the expression-tree materializer, equivalent to SetColumnValue (= CoerceScalar) (type-specialized, no reflection)
    public EntityBase MapEntityObject(DbDataReader reader, int[] ordinals) =>
        SelectMaterializer(reader, ordinals);

    /// <summary>Maps one data reader row to an entity (without a type argument) (single-row variant that resolves the SelectColumns ordinals on each call).</summary>
    public EntityBase MapEntityObject(DbDataReader reader) =>
        MapEntityObject(reader, SelectOrdinals(reader));

    /// <summary>
    /// Coerces the raw value SQLite returns (long / double / string / byte[]) to the target property's CLR type.
    /// </summary>
    /// <remarks>
    /// Handles the SQLite storage conventions (same as EF Core Sqlite: decimal/Guid/DateTime/DateTimeOffset/TimeSpan
    /// stored as TEXT, bool as INTEGER). Values already assignable are returned as-is, and Nullable types are judged by
    /// their underlying type. When conversion is impossible, throws an exception with a clear message.
    /// </remarks>
    private static object CoerceScalar(object value, Type targetType)
    {
        var underlying = Nullable.GetUnderlyingType(targetType) ?? targetType;

        if (underlying.IsInstanceOfType(value))
        {
            return value;
        }

        // Enums are coerced to their underlying integer type first, then converted
        if (underlying.IsEnum)
        {
            return Enum.ToObject(underlying, Convert.ChangeType(value, Enum.GetUnderlyingType(underlying), CultureInfo.InvariantCulture));
        }

        // Types stored as TEXT are restored from the string (ISO 8601 / "N" format)
        if (value is string text)
        {
            if (underlying == typeof(Guid))
            {
                return Guid.Parse(text);
            }

            if (underlying == typeof(DateTime))
            {
                return DateTime.Parse(text, CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.RoundtripKind);
            }

            if (underlying == typeof(DateTimeOffset))
            {
                return DateTimeOffset.Parse(text, CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.RoundtripKind);
            }

            if (underlying == typeof(TimeSpan))
            {
                return TimeSpan.Parse(text, CultureInfo.InvariantCulture);
            }
        }

        // bool is stored as INTEGER (0/1)
        if (underlying == typeof(bool) && value is long boolLong)
        {
            return boolLong != 0;
        }

        try
        {
            // Numeric narrowing (long to int/short/byte, double to float/decimal, etc.)
            return Convert.ChangeType(value, underlying, CultureInfo.InvariantCulture);
        }
        catch (Exception ex) when (ex is InvalidCastException or FormatException or OverflowException)
        {
            throw new InvalidOperationException(
                $"The value read from SQLite ({value.GetType().Name}) could not be converted to {underlying.Name}.",
                ex
            );
        }
    }

    /// <summary>Extracts the value of the specified column from an entity (value objects are unwrapped to their raw value). Used for parent/child key matching in Include.</summary>
    public object? GetColumnValue(EntityBase entity, string columnName)
    {
        if (!PropertyByColumn.TryGetValue(columnName, out var property))
        {
            throw new InvalidOperationException(
                $"{EntityType.Name} has no property corresponding to column {columnName}."
            );
        }

        var value = property.GetValue(entity);
        return value;
    }
    /// <summary>Binds the INSERT parameters (the insert-target columns excluding store-generated columns) (shared by insert and graph insert).</summary>
    public void BindInsertParameters(SqliteCommand command, EntityBase entity)
    {
        foreach (var property in InsertProperties)
        {
            AddColumnParameter(
                command,
                $"@{property.Name}",
                property,
                property.GetValue(entity)
            );
        }
    }

    /// <summary>Binds the UPDATE parameters (non-key columns plus the primary key) (shared by update and graph update).</summary>
    public void BindUpdateParameters(SqliteCommand command, EntityBase entity)
    {
        // Updates that still carry values in unbounded binary columns (excluded from UPDATE) would lose them silently,
        // so reject them up front. Both direct UpdateAsync and cascading graph updates pass through here,
        // so this single spot covers both
        UnboundedBinaryColumns.ThrowIfExcludedAssigned(entity);

        foreach (var property in NonKeyProperties)
        {
            AddColumnParameter(
                command,
                $"@{property.Name}",
                property,
                property.GetValue(entity)
            );
        }

        AddColumnParameter(
            command,
            "@id",
            KeyProperty,
            KeyProperty.GetValue(entity)
        );
    }

    /// <summary>Binds the entity's primary key value to the @id parameter (used by graph delete).</summary>
    public void BindEntityKeyParameter(SqliteCommand command, EntityBase entity)
    {
        AddColumnParameter(
            command,
            "@id",
            KeyProperty,
            KeyProperty.GetValue(entity)
        );
    }

    /// <summary>Binds an externally supplied primary key value to the @id parameter (used by GetById/Delete).</summary>
    public void BindKeyParameter(SqliteCommand command, object? id)
    {
        var value =
            id
            ?? throw new InvalidOperationException("id cannot be null.");
        AddColumnParameter(command, "@id", KeyProperty, value);
    }

    /// <summary>Binding used when the [SqlColumnType] attribute is not generated. Adds via AddWithValue as before.</summary>
    /// <param name="command">The command to add the parameter to</param>
    /// <param name="name">The parameter name (with the @ prefix)</param>
    /// <param name="property">The property corresponding to the target column (unused in this branch)</param>
    /// <param name="rawValue">The value after value objects have already been unwrapped to their raw value; null is bound as DBNull.Value</param>
    private static void AddColumnParameter(
        SqliteCommand command,
        string name,
        PropertyInfo property,
        object? rawValue
    ) => command.Parameters.AddWithValue(name, rawValue ?? DBNull.Value);

    /// <summary>
    /// Binds a query WHERE-clause parameter. When the column name is known and its column property is found, the
    /// parameter is explicitly constructed with the column type; otherwise falls back to AddWithValue.
    /// </summary>
    /// <param name="command">The command to add the parameter to</param>
    /// <param name="name">The parameter name (with the @ prefix)</param>
    /// <param name="columnName">The unquoted column name; null when the column cannot be determined</param>
    /// <param name="rawValue">The value after value objects have already been unwrapped to their raw value; null is bound as DBNull.Value</param>
    public void AddQueryParameter(
        SqliteCommand command,
        string name,
        string? columnName,
        object? rawValue
    )
    {
        if (columnName is not null && PropertyByColumn.TryGetValue(columnName, out var property))
        {
            AddColumnParameter(command, name, property, rawValue);
            return;
        }

        command.Parameters.AddWithValue(name, rawValue ?? DBNull.Value);
    }

    private static string GetColumnName(PropertyInfo property) =>
        property.GetCustomAttribute<ColumnAttribute>()?.Name ?? property.Name;

    /// <summary>Looks up the column property for a C# property name (searched across all columns, including unbounded binary = excluded columns). Used by the Stream accessors in both the repository and the in-memory implementation.</summary>
    public PropertyInfo ColumnByPropertyName(string propertyName) =>
        AllProperties.FirstOrDefault(property => property.Name == propertyName)
        ?? throw new InvalidOperationException(
            $"Property {propertyName} was not found as a column."
        );

    /// <summary>Returns the quoted column name of the specified column property (for example: \"payload\") (for building SQL in the Stream accessors).</summary>
    public string QuotedColumnName(PropertyInfo property) =>
        $"\"{GetColumnName(property)}\"";

    /// <summary>Returns the raw, unquoted column name of the specified column property (required by SqliteBlob and friends).</summary>
    public string RawColumnName(PropertyInfo property) => GetColumnName(property);
}

/// <summary>Planner that builds the cascade-delete DELETE statements from FK metadata (database-independent, pure).</summary>
internal static class CascadeDeletePlanner
{
    /// <summary>Returns the DELETE statements that remove the rootType rows matching the condition and their descendants, in child-to-parent execution order.</summary>
    /// <param name="rootType">The entity type at which the delete starts</param>
    /// <param name="rootTable">The quoted root table name</param>
    /// <param name="whereClause">The root WHERE clause (" WHERE ..." or an empty string)</param>
    public static IReadOnlyList<string> BuildDeleteStatements(
        Type rootType,
        string rootTable,
        string whereClause
    )
    {
        var statements = new List<string>();
        AppendDescendantDeletes(
            rootType,
            rootTable,
            whereClause,
            new HashSet<Type> { rootType },
            statements
        );
        statements.Add($"DELETE FROM {rootTable}{whereClause};");
        return statements;
    }

    private static void AppendDescendantDeletes(
        Type parentType,
        string parentTable,
        string parentScopeWhere,
        HashSet<Type> visited,
        List<string> statements
    )
    {
        foreach (var navigation in EntitySaveMetadata.For(parentType).CascadeNavigations)
        {
            // Cyclic cascades (self-references etc.) cannot be expressed with fixed nesting, so they are unsupported
            if (!visited.Add(navigation.ChildType))
            {
                throw new NotSupportedException(
                    $"Cyclic cascades ({navigation.ChildType.Name}) are not supported by ExecuteDeleteAsync. Load the graph and use SaveAsync, or use ON DELETE CASCADE in the database."
                );
            }

            var childTable = EntitySaveMetadata.For(navigation.ChildType).TableName;
            var childScopeWhere =
                $" WHERE \"{navigation.DependentColumn}\" IN (SELECT \"{navigation.PrincipalColumn}\" FROM {parentTable}{parentScopeWhere})";

            // Delete grandchildren and below first, then the children (FK consistency)
            AppendDescendantDeletes(
                navigation.ChildType,
                childTable,
                childScopeWhere,
                visited,
                statements
            );
            statements.Add($"DELETE FROM {childTable}{childScopeWhere};");

            visited.Remove(navigation.ChildType);
        }
    }
}

/// <summary>A save hook session that lives only for the duration of a single Save call (carries the registry, context factory, and skip set).</summary>
/// <remarks>
/// The context factory is supplied by the backend (QuickER dialect, EF Core, InMemory) with the in-progress transaction
/// context captured inside. The skip set is tracked by reference equality (<see cref="ReferenceEqualityComparer"/>) and
/// used by the post-commit <c>AcceptChanges</c> to leave states untouched.
/// </remarks>
internal sealed class SaveHookSession(
    ISaveHookRegistry registry,
    Func<EntityBase, ISaveHookContext> contextFactory
)
{
    private readonly ISaveHookRegistry _registry = registry;
    private readonly Func<EntityBase, ISaveHookContext> _contextFactory = contextFactory;
    private readonly HashSet<EntityBase> _skipped = new(ReferenceEqualityComparer.Instance);

    /// <summary>Gets the set of entities skipped by a Before returning <c>false</c> (reference equality). Used by AcceptChanges to leave states untouched.</summary>
    public IReadOnlySet<EntityBase> Skipped => _skipped;

    /// <summary>Adds an entity to the skip set.</summary>
    public void Skip(EntityBase entity) => _skipped.Add(entity);

    /// <summary>Calls Before in registration order and short-circuits at the first <c>false</c> (types with no hooks yield <c>true</c>).</summary>
    public Task<bool> InvokeBeforeAsync(
        EntityBase entity,
        SaveOperation operation,
        CancellationToken cancellationToken
    )
    {
        var invoker = _registry.GetInvoker(entity.GetType());
        return invoker is null
            ? Task.FromResult(true)
            : invoker.InvokeBeforeAsync(entity, operation, cancellationToken);
    }

    /// <summary>Calls After in registration order (types with no hooks do nothing). The context is created bound to the entity type.</summary>
    public Task InvokeAfterAsync(
        EntityBase entity,
        SaveOperation operation,
        CancellationToken cancellationToken
    )
    {
        var invoker = _registry.GetInvoker(entity.GetType());
        return invoker is null
            ? Task.CompletedTask
            : invoker.InvokeAfterAsync(
                entity,
                operation,
                _contextFactory(entity),
                cancellationToken
            );
    }
}

/// <summary>Internal engine that saves an entity graph in a single transaction according to RowState.</summary>
internal static class EntityGraphSaver
{
    /// <summary>Returns whether the entity itself, or (when cascading) any child, has changes.</summary>
    public static bool HasChanges(EntityBase entity, bool cascade) =>
        entity.HasChanges
        || (cascade && EnumerateCascadeChildren(entity).Any(child => HasChanges(child, true)));

    /// <summary>Saves the graph and returns the number of saved records (when <paramref name="hooks"/> is provided, fires the save hooks before and after each operation).</summary>
    /// <remarks>
    /// When <c>changesAlreadyVerified</c> is <c>true</c> (the caller has already checked <see cref="HasChanges"/>, i.e.
    /// changes are known to exist), the redundant graph traversal (change detection) at the start is skipped. Recursion
    /// into children passes the default <c>false</c>, so per-subtree change detection (pruning clean branches) is still
    /// performed as before.
    /// </remarks>
    public static async Task<int> SaveAsync(
        EntityBase entity,
        SqliteConnection connection,
        SqliteTransaction transaction,
        bool cascadeSave,
        bool cascadeDelete,
        bool insertWhenUpdateMissing,
        CancellationToken cancellationToken,
        SaveHookSession? hooks = null,
        bool changesAlreadyVerified = false
    )
    {
        if (!changesAlreadyVerified && !HasChanges(entity, cascadeSave))
        {
            return 0;
        }

        var rows = 0;

        if (entity.IsRemoved)
        {
            // Deletion removes the children (subtree) first, then the entity itself (FK consistency)
            if (cascadeDelete)
            {
                foreach (var child in EnumerateCascadeChildren(entity))
                {
                    rows += await DeleteGraphAsync(
                        child,
                        connection,
                        transaction,
                        cancellationToken,
                        hooks
                    ).ConfigureAwait(false);
                }
            }

            // Before(Delete). On false, only this node's deletion is skipped (the children were deleted above, so this node remains)
            if (
                hooks is not null
                && !await hooks.InvokeBeforeAsync(
                    entity,
                    SaveOperation.Delete,
                    cancellationToken
                ).ConfigureAwait(false)
            )
            {
                hooks.Skip(entity);
                return rows;
            }

            rows += await DeleteEntityAsync(
                entity,
                connection,
                transaction,
                cancellationToken
            ).ConfigureAwait(false);

            // After(Delete) fires immediately after the DML (before commit)
            if (hooks is not null)
            {
                await hooks.InvokeAfterAsync(entity, SaveOperation.Delete, cancellationToken).ConfigureAwait(false);
            }

            return rows;
        }

        // Inserts and updates save the entity itself first, then proceed to the children (child FKs reference the parent PK)
        if (entity.IsAdded)
        {
            if (
                hooks is null
                || await hooks.InvokeBeforeAsync(entity, SaveOperation.Insert, cancellationToken).ConfigureAwait(false)
            )
            {
                rows += await InsertEntityAsync(
                    entity,
                    connection,
                    transaction,
                    cancellationToken
                ).ConfigureAwait(false);

                if (hooks is not null)
                {
                    await hooks.InvokeAfterAsync(entity, SaveOperation.Insert, cancellationToken).ConfigureAwait(false);
                }
            }
            else
            {
                // Before returned false = only this one insert is skipped (the child cascade continues)
                hooks.Skip(entity);
            }
        }
        else if (entity.IsUpdated)
        {
            if (
                hooks is null
                || await hooks.InvokeBeforeAsync(entity, SaveOperation.Update, cancellationToken).ConfigureAwait(false)
            )
            {
                var (affected, performed) = await UpdateAsync(
                    entity,
                    connection,
                    transaction,
                    insertWhenUpdateMissing,
                    cancellationToken
                ).ConfigureAwait(false);
                rows += affected;

                // After fires with the operation actually performed (Insert when switched by insertWhenUpdateMissing)
                if (hooks is not null)
                {
                    await hooks.InvokeAfterAsync(entity, performed, cancellationToken).ConfigureAwait(false);
                }
            }
            else
            {
                hooks.Skip(entity);
            }
        }

        if (cascadeSave)
        {
            foreach (var child in EnumerateCascadeChildren(entity))
            {
                rows += await SaveAsync(
                    child,
                    connection,
                    transaction,
                    cascadeSave,
                    cascadeDelete,
                    insertWhenUpdateMissing,
                    cancellationToken,
                    hooks
                ).ConfigureAwait(false);
            }
        }

        return rows;
    }

    /// <summary>Finalizes saved entities to Unchanged after commit.</summary>
    public static void AcceptChanges(EntityBase entity, bool cascade) =>
        AcceptChanges(entity, cascade, null);

    /// <summary>
    /// Finalizes saved entities to Unchanged after commit. Entities contained in <paramref name="skip"/> (rows skipped
    /// because a save hook's Before returned <c>false</c>) were not operated on, so their state is left untouched.
    /// </summary>
    public static void AcceptChanges(
        EntityBase entity,
        bool cascade,
        IReadOnlySet<EntityBase>? skip
    )
    {
        if (entity.IsRemoved)
        {
            return;
        }

        // Skipped entities had no INSERT / UPDATE performed, so their RowState is left untouched
        if (skip is null || !skip.Contains(entity))
        {
            entity.MarkUnchanged();
        }

        if (cascade)
        {
            foreach (var child in EnumerateCascadeChildren(entity))
            {
                AcceptChanges(child, true, skip);
            }
        }
    }

    /// <summary>Deletes the subtree starting from the children (deleted regardless of state; when <paramref name="hooks"/> is provided, fires Before/After(Delete) per child).</summary>
    private static async Task<int> DeleteGraphAsync(
        EntityBase entity,
        SqliteConnection connection,
        SqliteTransaction transaction,
        CancellationToken cancellationToken,
        SaveHookSession? hooks = null
    )
    {
        var rows = 0;

        foreach (var child in EnumerateCascadeChildren(entity))
        {
            rows += await DeleteGraphAsync(
                child,
                connection,
                transaction,
                cancellationToken,
                hooks
            ).ConfigureAwait(false);
        }

        // Before(Delete) fires from the subtree's children upward. On false, "the children are gone but this node remains" (the consequence of a standalone skip)
        if (
            hooks is not null
            && !await hooks.InvokeBeforeAsync(entity, SaveOperation.Delete, cancellationToken).ConfigureAwait(false)
        )
        {
            hooks.Skip(entity);
            return rows;
        }

        rows += await DeleteEntityAsync(
            entity,
            connection,
            transaction,
            cancellationToken
        ).ConfigureAwait(false);

        if (hooks is not null)
        {
            await hooks.InvokeAfterAsync(entity, SaveOperation.Delete, cancellationToken).ConfigureAwait(false);
        }

        return rows;
    }

    /// <summary>Inserts a single row.</summary>
    private static Task<int> InsertEntityAsync(
        EntityBase entity,
        SqliteConnection connection,
        SqliteTransaction transaction,
        CancellationToken cancellationToken
    )
    {
        return ExecuteAsync(
            entity,
            meta => meta.InsertSql,
            static (meta, command, e) => meta.BindInsertParameters(command, e),
            connection,
            transaction,
            cancellationToken
        );
    }

    /// <summary>Deletes a single row.</summary>
    private static Task<int> DeleteEntityAsync(
        EntityBase entity,
        SqliteConnection connection,
        SqliteTransaction transaction,
        CancellationToken cancellationToken
    )
    {
        return ExecuteAsync(
            entity,
            meta => meta.DeleteSql,
            static (meta, command, e) => meta.BindEntityKeyParameter(command, e),
            connection,
            transaction,
            cancellationToken
        );
    }

    /// <summary>Executes the update and returns the affected row count and the operation actually performed (Insert when switched).</summary>
    private static async Task<(int Rows, SaveOperation Performed)> UpdateAsync(
        EntityBase entity,
        SqliteConnection connection,
        SqliteTransaction transaction,
        bool insertWhenUpdateMissing,
        CancellationToken cancellationToken
    )
    {
        var metadata = EntitySaveMetadata.For(entity.GetType());

        var affected = await ExecuteAsync(
            entity,
            meta => meta.UpdateSql,
            static (meta, command, e) => meta.BindUpdateParameters(command, e),
            connection,
            transaction,
            cancellationToken
        ).ConfigureAwait(false);

        if (affected != 0)
        {
            return (affected, SaveOperation.Update);
        }

        // The record to update does not exist (e.g. deleted by another user). Depending on the policy,
        // switch to INSERT or report it as a conflict
        if (insertWhenUpdateMissing)
        {
            var inserted = await InsertEntityAsync(
                entity,
                connection,
                transaction,
                cancellationToken
            ).ConfigureAwait(false);
            return (inserted, SaveOperation.Insert);
        }

        throw SaveConflictException.NotFound(
            entity.GetType(),
            metadata.KeyProperty.GetValue(entity)
        );
    }

    private static async Task<int> ExecuteAsync(
        EntityBase entity,
        Func<EntitySaveMetadata, string> sqlSelector,
        Action<EntitySaveMetadata, SqliteCommand, EntityBase> bind,
        SqliteConnection connection,
        SqliteTransaction transaction,
        CancellationToken cancellationToken
    )
    {
        var metadata = EntitySaveMetadata.For(entity.GetType());

        await using var command = new SqliteCommand(sqlSelector(metadata), connection, transaction);
        bind(metadata, command, entity);
        return await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Enumerates the cascade-target child entities (nulls are excluded).</summary>
    private static IEnumerable<EntityBase> EnumerateCascadeChildren(EntityBase entity)
    {
        foreach (var navigation in EntitySaveMetadata.For(entity.GetType()).CascadeNavigations)
        {
            var value = navigation.Property.GetValue(entity);

            if (value is null)
            {
                continue;
            }

            if (navigation.IsCollection)
            {
                if (value is IEnumerable<EntityBase> children)
                {
                    foreach (var child in children)
                    {
                        if (child is not null)
                        {
                            yield return child;
                        }
                    }
                }
            }
            else if (value is EntityBase child)
            {
                yield return child;
            }
        }
    }
}

/// <summary>Extensions that register save hooks (<c>ISaveHook&lt;TEntity&gt;</c>) with the DI container.</summary>
/// <remarks>
/// The default registry (<c>ServiceProviderSaveHookRegistry</c>, registered by every <c>AddGenerated*Repositories</c>
/// overload) resolves <c>IEnumerable&lt;ISaveHook&lt;TEntity&gt;&gt;</c>, so a hook must be registered under each closed
/// interface it implements. This extension derives those from the instance itself, which keeps registration code free of
/// per-entity-type branching (and free of the maintenance it needs whenever a table is added).
/// </remarks>
public static class SaveHookServiceCollectionExtensions
{
    /// <summary>Registers a save hook instance as a singleton under every <c>ISaveHook&lt;TEntity&gt;</c> it implements.</summary>
    /// <param name="services">The service collection to register with.</param>
    /// <param name="hook">The hook instance (one object may implement the hook interface for several entity types).</param>
    /// <returns>The same service collection, so that calls can be chained.</returns>
    /// <exception cref="ArgumentException">The object implements no <c>ISaveHook&lt;TEntity&gt;</c> interface, so registering it would silently do nothing.</exception>
    public static IServiceCollection AddSaveHook(this IServiceCollection services, object hook)
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentNullException.ThrowIfNull(hook);

        var registered = false;

        foreach (var contract in hook.GetType().GetInterfaces())
        {
            if (
                !contract.IsGenericType
                || contract.GetGenericTypeDefinition() != typeof(ISaveHook<>)
            )
            {
                continue;
            }

            services.AddSingleton(contract, hook);
            registered = true;
        }

        return registered
            ? services
            : throw new ArgumentException(
                $"The object of type '{hook.GetType().Name}' implements no ISaveHook<TEntity> interface.",
                nameof(hook)
            );
    }
}

/// <summary>Extensions that register the generated repositories (SQLite implementation) with the DI container.</summary>
/// <remarks>
/// DI registration is provided per engine under the name <c>AddGeneratedSqliteRepositories</c>, registering
/// the same contracts (I{Entity}Repository / ISqlExecutor) with dialect-specific implementations. To use multiple dialects
/// (multi-targeting) in the same process, use the overloads with <c>object? serviceKey</c> (keyed DI) and resolve the
/// dialect-specific connection via <c>[FromKeyedServices("...")]</c>.
/// </remarks>
public static class GeneratedSqliteRepositoryServiceCollectionExtensions
{
    /// <summary>Registers the SQLite repositories with the DI container using a connection string (non-keyed, for standalone use).</summary>
    public static IServiceCollection AddGeneratedSqliteRepositories(
        this IServiceCollection services,
        string connectionString
    )
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentException.ThrowIfNullOrWhiteSpace(connectionString);

        services.AddSingleton<ISqlConnectionFactory>(_ => new SqlConnectionFactory(
            connectionString
        ));
        services.AddSingleton<ISqlExecutor, SqlExecutor>();

        // Register the save hook registry by default (a complete no-op when no ISaveHook<T> is registered)
        services.TryAddScoped<ISaveHookRegistry>(provider => new ServiceProviderSaveHookRegistry(
            provider
        ));
        services.AddScoped<IDocumentRepository, DocumentRepository>();
        services.AddScoped<IDocumentRemoteRepository>(provider =>
            provider.GetRequiredService<IDocumentRepository>()
        );
        services.AddScoped<IDocumentNoteRepository, DocumentNoteRepository>();
        services.AddScoped<IDocumentNoteRemoteRepository>(provider =>
            provider.GetRequiredService<IDocumentNoteRepository>()
        );

        return services;
    }

    /// <summary>Registers the SQLite repositories with a service key (keyed DI, for using multiple dialects simultaneously).</summary>
    /// <remarks>
    /// Registers I{Entity}Repository / ISqlExecutor keyed by <paramref name="serviceKey"/>. Consumers resolve the
    /// dialect-specific implementation like <c>[FromKeyedServices(serviceKey)] ICustomerRepository</c>.
    /// The connection factory is captured per key in a closure, so it causes no non-keyed registration collisions.
    /// </remarks>
    public static IServiceCollection AddGeneratedSqliteRepositories(
        this IServiceCollection services,
        object? serviceKey,
        string connectionString
    )
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentException.ThrowIfNullOrWhiteSpace(connectionString);

        var connectionFactory = new SqlConnectionFactory(connectionString);
        services.AddKeyedSingleton<ISqlConnectionFactory>(serviceKey, (_, _) => connectionFactory);
        services.AddKeyedSingleton<ISqlExecutor>(
            serviceKey,
            (_, _) => new SqlExecutor(connectionFactory)
        );

        // Register the save hook registry by default (non-keyed; a complete no-op when no ISaveHook<T> is registered)
        services.TryAddScoped<ISaveHookRegistry>(provider => new ServiceProviderSaveHookRegistry(
            provider
        ));
        services.AddKeyedScoped<IDocumentRepository>(
            serviceKey,
            (provider, _) => new DocumentRepository(
                connectionFactory,
                provider.GetService<ISaveHookRegistry>()
            )
        );
        services.AddKeyedScoped<IDocumentRemoteRepository>(
            serviceKey,
            (provider, key) => provider.GetRequiredKeyedService<IDocumentRepository>(key)
        );
        services.AddKeyedScoped<IDocumentNoteRepository>(
            serviceKey,
            (provider, _) => new DocumentNoteRepository(
                connectionFactory,
                provider.GetService<ISaveHookRegistry>()
            )
        );
        services.AddKeyedScoped<IDocumentNoteRemoteRepository>(
            serviceKey,
            (provider, key) => provider.GetRequiredKeyedService<IDocumentNoteRepository>(key)
        );

        return services;
    }
}

/// <summary>Remote surface of the DocumentEntity repository (only CRUD, save, and named queries that can cross a network boundary; swappable for a remote implementation later).</summary>
public partial interface IDocumentRemoteRepository : IRemoteRepository<DocumentEntity, int>
{
    /// <summary>文書 ID と本体バイナリ（除外列 payload）を射影で取得する（文書 ID 昇順）</summary>
    Task<IReadOnlyList<DocumentPayloadRow>> GetPayloadsAsync(CancellationToken cancellationToken = default);

    /// <summary>タイトル完全一致で文書を取得する（除外列 payload は取得されない）</summary>
    Task<IReadOnlyList<DocumentEntity>> GetByTitleAsync(string title, CancellationToken cancellationToken = default);

    /// <summary>本体バイナリ（payload）が存在する文書の件数を取得する</summary>
    Task<int> CountWithPayloadAsync(CancellationToken cancellationToken = default);

    /// <summary>Checks the UNIQUE constraints of documents against the database and returns the violations (an empty list when there are none).</summary>
    /// <remarks>
    /// Rows that share the entity's primary key are excluded, so the same call is correct for both insert and update (an entity whose key is not set yet excludes nothing). Constraint member values that contain
    /// a null are skipped (NULL collision semantics differ per dialect). The result is advisory only: the definitive guarantee is the database's own UNIQUE
    /// constraint, and a concurrent insert between this check and the save can still make the save fail (TOCTOU).
    /// </remarks>
    /// <param name="entity">The entity whose constraint member values are checked.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    Task<IReadOnlyList<UniquenessViolation>> CheckUniquenessAsync(
        DocumentEntity entity,
        CancellationToken cancellationToken = default
    );

    /// <summary>Reads the payload column into the destination stream (unbounded binary column, O(chunk) streaming; true = written, false = no row or NULL).</summary>
    Task<bool> ReadPayloadAsync(int id, Stream destination, CancellationToken cancellationToken = default);

    /// <summary>Writes the payload column from a stream (unbounded binary column, O(chunk) streaming; source = null sets NULL, non-seekable streams require an explicit length; true = updated, false = no row).</summary>
    Task<bool> WritePayloadAsync(int id, Stream? source, long? length = null, CancellationToken cancellationToken = default);

    /// <summary>Reads the thumb column into the destination stream (unbounded binary column, O(chunk) streaming; true = written, false = no row or NULL).</summary>
    Task<bool> ReadThumbAsync(int id, Stream destination, CancellationToken cancellationToken = default);

    /// <summary>Writes the thumb column from a stream (unbounded binary column, O(chunk) streaming; source = null sets NULL, non-seekable streams require an explicit length; true = updated, false = no row).</summary>
    Task<bool> WriteThumbAsync(int id, Stream? source, long? length = null, CancellationToken cancellationToken = default);
}

